-- KJV batch 12 (blocks 276-300 of 349)
-- Run this in Supabase Dashboard SQL Editor

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 49, E'While he yet spake, there cometh one from the ruler of the synagogue’s house, saying to him, Thy daughter is dead; trouble not the Master.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 50, E'But when Jesus heard it, he answered him, saying, Fear not: believe only, and she shall be made whole.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 51, E'And when he came into the house, he suffered no man to go in, save Peter, and James, and John, and the father and the mother of the maiden.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 52, E'And all wept, and bewailed her: but he said, Weep not; she is not dead, but sleepeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 53, E'And they laughed him to scorn, knowing that she was dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 54, E'And he put them all out, and took her by the hand, and called, saying, Maid, arise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 55, E'And her spirit came again, and she arose straightway: and he commanded to give her meat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 56, E'And her parents were astonished: but he charged them that they should tell no man what was done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 1, E'Then he called his twelve disciples together, and gave them power and authority over all devils, and to cure diseases.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 2, E'And he sent them to preach the kingdom of God, and to heal the sick.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 3, E'And he said unto them, Take nothing for your journey, neither staves, nor scrip, neither bread, neither money; neither have two coats apiece.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 4, E'And whatsoever house ye enter into, there abide, and thence depart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 5, E'And whosoever will not receive you, when ye go out of that city, shake off the very dust from your feet for a testimony against them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 6, E'And they departed, and went through the towns, preaching the gospel, and healing every where.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 7, E'Now Herod the tetrarch heard of all that was done by him: and he was perplexed, because that it was said of some, that John was risen from the dead;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 8, E'And of some, that Elias had appeared; and of others, that one of the old prophets was risen again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 9, E'And Herod said, John have I beheaded: but who is this, of whom I hear such things? And he desired to see him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 10, E'And the apostles, when they were returned, told him all that they had done. And he took them, and went aside privately into a desert place belonging to the city called Bethsaida.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 11, E'And the people, when they knew it, followed him: and he received them, and spake unto them of the kingdom of God, and healed them that had need of healing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 12, E'And when the day began to wear away, then came the twelve, and said unto him, Send the multitude away, that they may go into the towns and country round about, and lodge, and get victuals: for we are here in a desert place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 13, E'But he said unto them, Give ye them to eat. And they said, We have no more but five loaves and two fishes; except we should go and buy meat for all this people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 14, E'For they were about five thousand men. And he said to his disciples, Make them sit down by fifties in a company.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 15, E'And they did so, and made them all sit down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 16, E'Then he took the five loaves and the two fishes, and looking up to heaven, he blessed them, and brake, and gave to the disciples to set before the multitude.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 17, E'And they did eat, and were all filled: and there was taken up of fragments that remained to them twelve baskets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 18, E'And it came to pass, as he was alone praying, his disciples were with him: and he asked them, saying, Whom say the people that I am?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 19, E'They answering said, John the Baptist; but some say, Elias; and others say, that one of the old prophets is risen again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 20, E'He said unto them, But whom say ye that I am? Peter answering said, The Christ of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 21, E'And he straitly charged them, and commanded them to tell no man that thing;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 22, E'Saying, The Son of man must suffer many things, and be rejected of the elders and chief priests and scribes, and be slain, and be raised the third day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 23, E'And he said to them all, If any man will come after me, let him deny himself, and take up his cross daily, and follow me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 24, E'For whosoever will save his life shall lose it: but whosoever will lose his life for my sake, the same shall save it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 25, E'For what is a man advantaged, if he gain the whole world, and lose himself, or be cast away?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 26, E'For whosoever shall be ashamed of me and of my words, of him shall the Son of man be ashamed, when he shall come in his own glory, and in his Father’s, and of the holy angels.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 27, E'But I tell you of a truth, there be some standing here, which shall not taste of death, till they see the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 28, E'And it came to pass about an eight days after these sayings, he took Peter and John and James, and went up into a mountain to pray.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 29, E'And as he prayed, the fashion of his countenance was altered, and his raiment was white and glistering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 30, E'And, behold, there talked with him two men, which were Moses and Elias:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 31, E'Who appeared in glory, and spake of his decease which he should accomplish at Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 32, E'But Peter and they that were with him were heavy with sleep: and when they were awake, they saw his glory, and the two men that stood with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 33, E'And it came to pass, as they departed from him, Peter said unto Jesus, Master, it is good for us to be here: and let us make three tabernacles; one for thee, and one for Moses, and one for Elias: not knowing what he said.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 34, E'While he thus spake, there came a cloud, and overshadowed them: and they feared as they entered into the cloud.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 35, E'And there came a voice out of the cloud, saying, This is my beloved Son: hear him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 36, E'And when the voice was past, Jesus was found alone. And they kept it close, and told no man in those days any of those things which they had seen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 37, E'And it came to pass, that on the next day, when they were come down from the hill, much people met him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 38, E'And, behold, a man of the company cried out, saying, Master, I beseech thee, look upon my son: for he is mine only child.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 39, E'And, lo, a spirit taketh him, and he suddenly crieth out; and it teareth him that he foameth again, and bruising him hardly departeth from him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 40, E'And I besought thy disciples to cast him out; and they could not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 41, E'And Jesus answering said, O faithless and perverse generation, how long shall I be with you, and suffer you? Bring thy son hither.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 42, E'And as he was yet a coming, the devil threw him down, and tare him. And Jesus rebuked the unclean spirit, and healed the child, and delivered him again to his father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 43, E'And they were all amazed at the mighty power of God. But while they wondered every one at all things which Jesus did, he said unto his disciples,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 44, E'Let these sayings sink down into your ears: for the Son of man shall be delivered into the hands of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 45, E'But they understood not this saying, and it was hid from them, that they perceived it not: and they feared to ask him of that saying.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 46, E'Then there arose a reasoning among them, which of them should be greatest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 47, E'And Jesus, perceiving the thought of their heart, took a child, and set him by him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 48, E'And said unto them, Whosoever shall receive this child in my name receiveth me: and whosoever shall receive me receiveth him that sent me: for he that is least among you all, the same shall be great.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 49, E'And John answered and said, Master, we saw one casting out devils in thy name; and we forbad him, because he followeth not with us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 50, E'And Jesus said unto him, Forbid him not: for he that is not against us is for us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 51, E'And it came to pass, when the time was come that he should be received up, he stedfastly set his face to go to Jerusalem,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 52, E'And sent messengers before his face: and they went, and entered into a village of the Samaritans, to make ready for him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 53, E'And they did not receive him, because his face was as though he would go to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 54, E'And when his disciples James and John saw this, they said, Lord, wilt thou that we command fire to come down from heaven, and consume them, even as Elias did?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 55, E'But he turned, and rebuked them, and said, Ye know not what manner of spirit ye are of.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 56, E'For the Son of man is not come to destroy men’s lives, but to save them. And they went to another village.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 57, E'And it came to pass, that, as they went in the way, a certain man said unto him, Lord, I will follow thee whithersoever thou goest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 58, E'And Jesus said unto him, Foxes have holes, and birds of the air have nests; but the Son of man hath not where to lay his head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 59, E'And he said unto another, Follow me. But he said, Lord, suffer me first to go and bury my father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 60, E'Jesus said unto him, Let the dead bury their dead: but go thou and preach the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 61, E'And another also said, Lord, I will follow thee; but let me first go bid them farewell, which are at home at my house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 62, E'And Jesus said unto him, No man, having put his hand to the plough, and looking back, is fit for the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 1, E'After these things the LORD appointed other seventy also, and sent them two and two before his face into every city and place, whither he himself would come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 2, E'Therefore said he unto them, The harvest truly is great, but the labourers are few: pray ye therefore the Lord of the harvest, that he would send forth labourers into his harvest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 3, E'Go your ways: behold, I send you forth as lambs among wolves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 4, E'Carry neither purse, nor scrip, nor shoes: and salute no man by the way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 5, E'And into whatsoever house ye enter, first say, Peace be to this house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 6, E'And if the son of peace be there, your peace shall rest upon it: if not, it shall turn to you again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 7, E'And in the same house remain, eating and drinking such things as they give: for the labourer is worthy of his hire. Go not from house to house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 8, E'And into whatsoever city ye enter, and they receive you, eat such things as are set before you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 9, E'And heal the sick that are therein, and say unto them, The kingdom of God is come nigh unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 10, E'But into whatsoever city ye enter, and they receive you not, go your ways out into the streets of the same, and say,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 11, E'Even the very dust of your city, which cleaveth on us, we do wipe off against you: notwithstanding be ye sure of this, that the kingdom of God is come nigh unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 12, E'But I say unto you, that it shall be more tolerable in that day for Sodom, than for that city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 13, E'Woe unto thee, Chorazin! woe unto thee, Bethsaida! for if the mighty works had been done in Tyre and Sidon, which have been done in you, they had a great while ago repented, sitting in sackcloth and ashes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 14, E'But it shall be more tolerable for Tyre and Sidon at the judgment, than for you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 15, E'And thou, Capernaum, which art exalted to heaven, shalt be thrust down to hell.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 16, E'He that heareth you heareth me; and he that despiseth you despiseth me; and he that despiseth me despiseth him that sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 17, E'And the seventy returned again with joy, saying, Lord, even the devils are subject unto us through thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 18, E'And he said unto them, I beheld Satan as lightning fall from heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 19, E'Behold, I give unto you power to tread on serpents and scorpions, and over all the power of the enemy: and nothing shall by any means hurt you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 20, E'Notwithstanding in this rejoice not, that the spirits are subject unto you; but rather rejoice, because your names are written in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 21, E'In that hour Jesus rejoiced in spirit, and said, I thank thee, O Father, Lord of heaven and earth, that thou hast hid these things from the wise and prudent, and hast revealed them unto babes: even so, Father; for so it seemed good in thy sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 22, E'All things are delivered to me of my Father: and no man knoweth who the Son is, but the Father; and who the Father is, but the Son, and he to whom the Son will reveal him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 23, E'And he turned him unto his disciples, and said privately, Blessed are the eyes which see the things that ye see:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 24, E'For I tell you, that many prophets and kings have desired to see those things which ye see, and have not seen them; and to hear those things which ye hear, and have not heard them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 25, E'And, behold, a certain lawyer stood up, and tempted him, saying, Master, what shall I do to inherit eternal life?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 26, E'He said unto him, What is written in the law? how readest thou?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 27, E'And he answering said, Thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy strength, and with all thy mind; and thy neighbour as thyself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 28, E'And he said unto him, Thou hast answered right: this do, and thou shalt live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 29, E'But he, willing to justify himself, said unto Jesus, And who is my neighbour?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 30, E'And Jesus answering said, A certain man went down from Jerusalem to Jericho, and fell among thieves, which stripped him of his raiment, and wounded him, and departed, leaving him half dead.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Luke') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 31, E'And by chance there came down a certain priest that way: and when he saw him, he passed by on the other side.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 32, E'And likewise a Levite, when he was at the place, came and looked on him, and passed by on the other side.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 33, E'But a certain Samaritan, as he journeyed, came where he was: and when he saw him, he had compassion on him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 34, E'And went to him, and bound up his wounds, pouring in oil and wine, and set him on his own beast, and brought him to an inn, and took care of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 35, E'And on the morrow when he departed, he took out two pence, and gave them to the host, and said unto him, Take care of him; and whatsoever thou spendest more, when I come again, I will repay thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 36, E'Which now of these three, thinkest thou, was neighbour unto him that fell among the thieves?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 37, E'And he said, He that shewed mercy on him. Then said Jesus unto him, Go, and do thou likewise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 38, E'Now it came to pass, as they went, that he entered into a certain village: and a certain woman named Martha received him into her house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 39, E'And she had a sister called Mary, which also sat at Jesus’ feet, and heard his word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 40, E'But Martha was cumbered about much serving, and came to him, and said, Lord, dost thou not care that my sister hath left me to serve alone? bid her therefore that she help me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 41, E'And Jesus answered and said unto her, Martha, Martha, thou art careful and troubled about many things:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 42, E'But one thing is needful: and Mary hath chosen that good part, which shall not be taken away from her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 1, E'And it came to pass, that, as he was praying in a certain place, when he ceased, one of his disciples said unto him, Lord, teach us to pray, as John also taught his disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 2, E'And he said unto them, When ye pray, say, Our Father which art in heaven, Hallowed be thy name. Thy kingdom come. Thy will be done, as in heaven, so in earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 3, E'Give us day by day our daily bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 4, E'And forgive us our sins; for we also forgive every one that is indebted to us. And lead us not into temptation; but deliver us from evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 5, E'And he said unto them, Which of you shall have a friend, and shall go unto him at midnight, and say unto him, Friend, lend me three loaves;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 6, E'For a friend of mine in his journey is come to me, and I have nothing to set before him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 7, E'And he from within shall answer and say, Trouble me not: the door is now shut, and my children are with me in bed; I cannot rise and give thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 8, E'I say unto you, Though he will not rise and give him, because he is his friend, yet because of his importunity he will rise and give him as many as he needeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 9, E'And I say unto you, Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 10, E'For every one that asketh receiveth; and he that seeketh findeth; and to him that knocketh it shall be opened.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 11, E'If a son shall ask bread of any of you that is a father, will he give him a stone? or if he ask a fish, will he for a fish give him a serpent?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 12, E'Or if he shall ask an egg, will he offer him a scorpion?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 13, E'If ye then, being evil, know how to give good gifts unto your children: how much more shall your heavenly Father give the Holy Spirit to them that ask him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 14, E'And he was casting out a devil, and it was dumb. And it came to pass, when the devil was gone out, the dumb spake; and the people wondered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 15, E'But some of them said, He casteth out devils through Beelzebub the chief of the devils.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 16, E'And others, tempting him, sought of him a sign from heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 17, E'But he, knowing their thoughts, said unto them, Every kingdom divided against itself is brought to desolation; and a house divided against a house falleth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 18, E'If Satan also be divided against himself, how shall his kingdom stand? because ye say that I cast out devils through Beelzebub.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 19, E'And if I by Beelzebub cast out devils, by whom do your sons cast them out? therefore shall they be your judges.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 20, E'But if I with the finger of God cast out devils, no doubt the kingdom of God is come upon you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 21, E'When a strong man armed keepeth his palace, his goods are in peace:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 22, E'But when a stronger than he shall come upon him, and overcome him, he taketh from him all his armour wherein he trusted, and divideth his spoils.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 23, E'He that is not with me is against me: and he that gathereth not with me scattereth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 24, E'When the unclean spirit is gone out of a man, he walketh through dry places, seeking rest; and finding none, he saith, I will return unto my house whence I came out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 25, E'And when he cometh, he findeth it swept and garnished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 26, E'Then goeth he, and taketh to him seven other spirits more wicked than himself; and they enter in, and dwell there: and the last state of that man is worse than the first.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 27, E'And it came to pass, as he spake these things, a certain woman of the company lifted up her voice, and said unto him, Blessed is the womb that bare thee, and the paps which thou hast sucked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 28, E'But he said, Yea rather, blessed are they that hear the word of God, and keep it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 29, E'And when the people were gathered thick together, he began to say, This is an evil generation: they seek a sign; and there shall no sign be given it, but the sign of Jonas the prophet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 30, E'For as Jonas was a sign unto the Ninevites, so shall also the Son of man be to this generation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 31, E'The queen of the south shall rise up in the judgment with the men of this generation, and condemn them: for she came from the utmost parts of the earth to hear the wisdom of Solomon; and, behold, a greater than Solomon is here.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 32, E'The men of Nineve shall rise up in the judgment with this generation, and shall condemn it: for they repented at the preaching of Jonas; and, behold, a greater than Jonas is here.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 33, E'No man, when he hath lighted a candle, putteth it in a secret place, neither under a bushel, but on a candlestick, that they which come in may see the light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 34, E'The light of the body is the eye: therefore when thine eye is single, thy whole body also is full of light; but when thine eye is evil, thy body also is full of darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 35, E'Take heed therefore that the light which is in thee be not darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 36, E'If thy whole body therefore be full of light, having no part dark, the whole shall be full of light, as when the bright shining of a candle doth give thee light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 37, E'And as he spake, a certain Pharisee besought him to dine with him: and he went in, and sat down to meat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 38, E'And when the Pharisee saw it, he marvelled that he had not first washed before dinner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 39, E'And the Lord said unto him, Now do ye Pharisees make clean the outside of the cup and the platter; but your inward part is full of ravening and wickedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 40, E'Ye fools, did not he that made that which is without make that which is within also?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 41, E'But rather give alms of such things as ye have; and, behold, all things are clean unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 42, E'But woe unto you, Pharisees! for ye tithe mint and rue and all manner of herbs, and pass over judgment and the love of God: these ought ye to have done, and not to leave the other undone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 43, E'Woe unto you, Pharisees! for ye love the uppermost seats in the synagogues, and greetings in the markets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 44, E'Woe unto you, scribes and Pharisees, hypocrites! for ye are as graves which appear not, and the men that walk over them are not aware of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 45, E'Then answered one of the lawyers, and said unto him, Master, thus saying thou reproachest us also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 46, E'And he said, Woe unto you also, ye lawyers! for ye lade men with burdens grievous to be borne, and ye yourselves touch not the burdens with one of your fingers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 47, E'Woe unto you! for ye build the sepulchres of the prophets, and your fathers killed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 48, E'Truly ye bear witness that ye allow the deeds of your fathers: for they indeed killed them, and ye build their sepulchres.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 49, E'Therefore also said the wisdom of God, I will send them prophets and apostles, and some of them they shall slay and persecute:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 50, E'That the blood of all the prophets, which was shed from the foundation of the world, may be required of this generation;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 51, E'From the blood of Abel unto the blood of Zacharias, which perished between the altar and the temple: verily I say unto you, It shall be required of this generation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 52, E'Woe unto you, lawyers! for ye have taken away the key of knowledge: ye entered not in yourselves, and them that were entering in ye hindered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 53, E'And as he said these things unto them, the scribes and the Pharisees began to urge him vehemently, and to provoke him to speak of many things:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 54, E'Laying wait for him, and seeking to catch something out of his mouth, that they might accuse him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 1, E'In the mean time, when there were gathered together an innumerable multitude of people, insomuch that they trode one upon another, he began to say unto his disciples first of all, Beware ye of the leaven of the Pharisees, which is hypocrisy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 2, E'For there is nothing covered, that shall not be revealed; neither hid, that shall not be known.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 3, E'Therefore whatsoever ye have spoken in darkness shall be heard in the light; and that which ye have spoken in the ear in closets shall be proclaimed upon the housetops.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 4, E'And I say unto you my friends, Be not afraid of them that kill the body, and after that have no more that they can do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 5, E'But I will forewarn you whom ye shall fear: Fear him, which after he hath killed hath power to cast into hell; yea, I say unto you, Fear him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 6, E'Are not five sparrows sold for two farthings, and not one of them is forgotten before God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 7, E'But even the very hairs of your head are all numbered. Fear not therefore: ye are of more value than many sparrows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 8, E'Also I say unto you, Whosoever shall confess me before men, him shall the Son of man also confess before the angels of God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 9, E'But he that denieth me before men shall be denied before the angels of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 10, E'And whosoever shall speak a word against the Son of man, it shall be forgiven him: but unto him that blasphemeth against the Holy Ghost it shall not be forgiven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 11, E'And when they bring you unto the synagogues, and unto magistrates, and powers, take ye no thought how or what thing ye shall answer, or what ye shall say:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 12, E'For the Holy Ghost shall teach you in the same hour what ye ought to say.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 13, E'And one of the company said unto him, Master, speak to my brother, that he divide the inheritance with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 14, E'And he said unto him, Man, who made me a judge or a divider over you?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 15, E'And he said unto them, Take heed, and beware of covetousness: for a man’s life consisteth not in the abundance of the things which he possesseth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 16, E'And he spake a parable unto them, saying, The ground of a certain rich man brought forth plentifully:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 17, E'And he thought within himself, saying, What shall I do, because I have no room where to bestow my fruits?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 18, E'And he said, This will I do: I will pull down my barns, and build greater; and there will I bestow all my fruits and my goods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 19, E'And I will say to my soul, Soul, thou hast much goods laid up for many years; take thine ease, eat, drink, and be merry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 20, E'But God said unto him, Thou fool, this night thy soul shall be required of thee: then whose shall those things be, which thou hast provided?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 21, E'So is he that layeth up treasure for himself, and is not rich toward God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 22, E'And he said unto his disciples, Therefore I say unto you, Take no thought for your life, what ye shall eat; neither for the body, what ye shall put on.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 23, E'The life is more than meat, and the body is more than raiment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 24, E'Consider the ravens: for they neither sow nor reap; which neither have storehouse nor barn; and God feedeth them: how much more are ye better than the fowls?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 25, E'And which of you with taking thought can add to his stature one cubit?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 26, E'If ye then be not able to do that thing which is least, why take ye thought for the rest?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 27, E'Consider the lilies how they grow: they toil not, they spin not; and yet I say unto you, that Solomon in all his glory was not arrayed like one of these.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 28, E'If then God so clothe the grass, which is to day in the field, and to morrow is cast into the oven; how much more will he clothe you, O ye of little faith?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 29, E'And seek not ye what ye shall eat, or what ye shall drink, neither be ye of doubtful mind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 30, E'For all these things do the nations of the world seek after: and your Father knoweth that ye have need of these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 31, E'But rather seek ye the kingdom of God; and all these things shall be added unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 32, E'Fear not, little flock; for it is your Father’s good pleasure to give you the kingdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 33, E'Sell that ye have, and give alms; provide yourselves bags which wax not old, a treasure in the heavens that faileth not, where no thief approacheth, neither moth corrupteth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 34, E'For where your treasure is, there will your heart be also.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Luke') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 35, E'Let your loins be girded about, and your lights burning;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 36, E'And ye yourselves like unto men that wait for their lord, when he will return from the wedding; that when he cometh and knocketh, they may open unto him immediately.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 37, E'Blessed are those servants, whom the lord when he cometh shall find watching: verily I say unto you, that he shall gird himself, and make them to sit down to meat, and will come forth and serve them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 38, E'And if he shall come in the second watch, or come in the third watch, and find them so, blessed are those servants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 39, E'And this know, that if the goodman of the house had known what hour the thief would come, he would have watched, and not have suffered his house to be broken through.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 40, E'Be ye therefore ready also: for the Son of man cometh at an hour when ye think not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 41, E'Then Peter said unto him, Lord, speakest thou this parable unto us, or even to all?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 42, E'And the Lord said, Who then is that faithful and wise steward, whom his lord shall make ruler over his household, to give them their portion of meat in due season?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 43, E'Blessed is that servant, whom his lord when he cometh shall find so doing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 44, E'Of a truth I say unto you, that he will make him ruler over all that he hath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 45, E'But and if that servant say in his heart, My lord delayeth his coming; and shall begin to beat the menservants and maidens, and to eat and drink, and to be drunken;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 46, E'The lord of that servant will come in a day when he looketh not for him, and at an hour when he is not aware, and will cut him in sunder, and will appoint him his portion with the unbelievers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 47, E'And that servant, which knew his lord’s will, and prepared not himself, neither did according to his will, shall be beaten with many stripes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 48, E'But he that knew not, and did commit things worthy of stripes, shall be beaten with few stripes. For unto whomsoever much is given, of him shall be much required: and to whom men have committed much, of him they will ask the more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 49, E'I am come to send fire on the earth; and what will I, if it be already kindled?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 50, E'But I have a baptism to be baptized with; and how am I straitened till it be accomplished!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 51, E'Suppose ye that I am come to give peace on earth? I tell you, Nay; but rather division:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 52, E'For from henceforth there shall be five in one house divided, three against two, and two against three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 53, E'The father shall be divided against the son, and the son against the father; the mother against the daughter, and the daughter against the mother; the mother in law against her daughter in law, and the daughter in law against her mother in law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 54, E'And he said also to the people, When ye see a cloud rise out of the west, straightway ye say, There cometh a shower; and so it is.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 55, E'And when ye see the south wind blow, ye say, There will be heat; and it cometh to pass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 56, E'Ye hypocrites, ye can discern the face of the sky and of the earth; but how is it that ye do not discern this time?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 57, E'Yea, and why even of yourselves judge ye not what is right?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 58, E'When thou goest with thine adversary to the magistrate, as thou art in the way, give diligence that thou mayest be delivered from him; lest he hale thee to the judge, and the judge deliver thee to the officer, and the officer cast thee into prison.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 59, E'I tell thee, thou shalt not depart thence, till thou hast paid the very last mite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 1, E'There were present at that season some that told him of the Galilaeans, whose blood Pilate had mingled with their sacrifices.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 2, E'And Jesus answering said unto them, Suppose ye that these Galilaeans were sinners above all the Galilaeans, because they suffered such things?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 3, E'I tell you, Nay: but, except ye repent, ye shall all likewise perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 4, E'Or those eighteen, upon whom the tower in Siloam fell, and slew them, think ye that they were sinners above all men that dwelt in Jerusalem?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 5, E'I tell you, Nay: but, except ye repent, ye shall all likewise perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 6, E'He spake also this parable; A certain man had a fig tree planted in his vineyard; and he came and sought fruit thereon, and found none.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 7, E'Then said he unto the dresser of his vineyard, Behold, these three years I come seeking fruit on this fig tree, and find none: cut it down; why cumbereth it the ground?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 8, E'And he answering said unto him, Lord, let it alone this year also, till I shall dig about it, and dung it:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 9, E'And if it bear fruit, well: and if not, then after that thou shalt cut it down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 10, E'And he was teaching in one of the synagogues on the sabbath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 11, E'And, behold, there was a woman which had a spirit of infirmity eighteen years, and was bowed together, and could in no wise lift up herself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 12, E'And when Jesus saw her, he called her to him, and said unto her, Woman, thou art loosed from thine infirmity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 13, E'And he laid his hands on her: and immediately she was made straight, and glorified God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 14, E'And the ruler of the synagogue answered with indignation, because that Jesus had healed on the sabbath day, and said unto the people, There are six days in which men ought to work: in them therefore come and be healed, and not on the sabbath day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 15, E'The Lord then answered him, and said, Thou hypocrite, doth not each one of you on the sabbath loose his ox or his ass from the stall, and lead him away to watering?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 16, E'And ought not this woman, being a daughter of Abraham, whom Satan hath bound, lo, these eighteen years, be loosed from this bond on the sabbath day?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 17, E'And when he had said these things, all his adversaries were ashamed: and all the people rejoiced for all the glorious things that were done by him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 18, E'Then said he, Unto what is the kingdom of God like? and whereunto shall I resemble it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 19, E'It is like a grain of mustard seed, which a man took, and cast into his garden; and it grew, and waxed a great tree; and the fowls of the air lodged in the branches of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 20, E'And again he said, Whereunto shall I liken the kingdom of God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 21, E'It is like leaven, which a woman took and hid in three measures of meal, till the whole was leavened.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 22, E'And he went through the cities and villages, teaching, and journeying toward Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 23, E'Then said one unto him, Lord, are there few that be saved? And he said unto them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 24, E'Strive to enter in at the strait gate: for many, I say unto you, will seek to enter in, and shall not be able.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 25, E'When once the master of the house is risen up, and hath shut to the door, and ye begin to stand without, and to knock at the door, saying, Lord, Lord, open unto us; and he shall answer and say unto you, I know you not whence ye are:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 26, E'Then shall ye begin to say, We have eaten and drunk in thy presence, and thou hast taught in our streets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 27, E'But he shall say, I tell you, I know you not whence ye are; depart from me, all ye workers of iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 28, E'There shall be weeping and gnashing of teeth, when ye shall see Abraham, and Isaac, and Jacob, and all the prophets, in the kingdom of God, and you yourselves thrust out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 29, E'And they shall come from the east, and from the west, and from the north, and from the south, and shall sit down in the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 30, E'And, behold, there are last which shall be first, and there are first which shall be last.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 31, E'The same day there came certain of the Pharisees, saying unto him, Get thee out, and depart hence: for Herod will kill thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 32, E'And he said unto them, Go ye, and tell that fox, Behold, I cast out devils, and I do cures to day and to morrow, and the third day I shall be perfected.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 33, E'Nevertheless I must walk to day, and to morrow, and the day following: for it cannot be that a prophet perish out of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 34, E'O Jerusalem, Jerusalem, which killest the prophets, and stonest them that are sent unto thee; how often would I have gathered thy children together, as a hen doth gather her brood under her wings, and ye would not!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 35, E'Behold, your house is left unto you desolate: and verily I say unto you, Ye shall not see me, until the time come when ye shall say, Blessed is he that cometh in the name of the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 1, E'And it came to pass, as he went into the house of one of the chief Pharisees to eat bread on the sabbath day, that they watched him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 2, E'And, behold, there was a certain man before him which had the dropsy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 3, E'And Jesus answering spake unto the lawyers and Pharisees, saying, Is it lawful to heal on the sabbath day?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 4, E'And they held their peace. And he took him, and healed him, and let him go;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 5, E'And answered them, saying, Which of you shall have an ass or an ox fallen into a pit, and will not straightway pull him out on the sabbath day?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 6, E'And they could not answer him again to these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 7, E'And he put forth a parable to those which were bidden, when he marked how they chose out the chief rooms; saying unto them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 8, E'When thou art bidden of any man to a wedding, sit not down in the highest room; lest a more honourable man than thou be bidden of him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 9, E'And he that bade thee and him come and say to thee, Give this man place; and thou begin with shame to take the lowest room.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 10, E'But when thou art bidden, go and sit down in the lowest room; that when he that bade thee cometh, he may say unto thee, Friend, go up higher: then shalt thou have worship in the presence of them that sit at meat with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 11, E'For whosoever exalteth himself shall be abased; and he that humbleth himself shall be exalted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 12, E'Then said he also to him that bade him, When thou makest a dinner or a supper, call not thy friends, nor thy brethren, neither thy kinsmen, nor thy rich neighbours; lest they also bid thee again, and a recompence be made thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 13, E'But when thou makest a feast, call the poor, the maimed, the lame, the blind:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 14, E'And thou shalt be blessed; for they cannot recompense thee: for thou shalt be recompensed at the resurrection of the just.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 15, E'And when one of them that sat at meat with him heard these things, he said unto him, Blessed is he that shall eat bread in the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 16, E'Then said he unto him, A certain man made a great supper, and bade many:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 17, E'And sent his servant at supper time to say to them that were bidden, Come; for all things are now ready.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 18, E'And they all with one consent began to make excuse. The first said unto him, I have bought a piece of ground, and I must needs go and see it: I pray thee have me excused.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 19, E'And another said, I have bought five yoke of oxen, and I go to prove them: I pray thee have me excused.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 20, E'And another said, I have married a wife, and therefore I cannot come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 21, E'So that servant came, and shewed his lord these things. Then the master of the house being angry said to his servant, Go out quickly into the streets and lanes of the city, and bring in hither the poor, and the maimed, and the halt, and the blind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 22, E'And the servant said, Lord, it is done as thou hast commanded, and yet there is room.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 23, E'And the lord said unto the servant, Go out into the highways and hedges, and compel them to come in, that my house may be filled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 24, E'For I say unto you, That none of those men which were bidden shall taste of my supper.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 25, E'And there went great multitudes with him: and he turned, and said unto them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 26, E'If any man come to me, and hate not his father, and mother, and wife, and children, and brethren, and sisters, yea, and his own life also, he cannot be my disciple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 27, E'And whosoever doth not bear his cross, and come after me, cannot be my disciple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 28, E'For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 29, E'Lest haply, after he hath laid the foundation, and is not able to finish it, all that behold it begin to mock him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 30, E'Saying, This man began to build, and was not able to finish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 31, E'Or what king, going to make war against another king, sitteth not down first, and consulteth whether he be able with ten thousand to meet him that cometh against him with twenty thousand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 32, E'Or else, while the other is yet a great way off, he sendeth an ambassage, and desireth conditions of peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 33, E'So likewise, whosoever he be of you that forsaketh not all that he hath, he cannot be my disciple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 34, E'Salt is good: but if the salt have lost his savour, wherewith shall it be seasoned?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 35, E'It is neither fit for the land, nor yet for the dunghill; but men cast it out. He that hath ears to hear, let him hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 1, E'Then drew near unto him all the publicans and sinners for to hear him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 2, E'And the Pharisees and scribes murmured, saying, This man receiveth sinners, and eateth with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 3, E'And he spake this parable unto them, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 4, E'What man of you, having an hundred sheep, if he lose one of them, doth not leave the ninety and nine in the wilderness, and go after that which is lost, until he find it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 5, E'And when he hath found it, he layeth it on his shoulders, rejoicing.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Luke') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 6, E'And when he cometh home, he calleth together his friends and neighbours, saying unto them, Rejoice with me; for I have found my sheep which was lost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 7, E'I say unto you, that likewise joy shall be in heaven over one sinner that repenteth, more than over ninety and nine just persons, which need no repentance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 8, E'Either what woman having ten pieces of silver, if she lose one piece, doth not light a candle, and sweep the house, and seek diligently till she find it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 9, E'And when she hath found it, she calleth her friends and her neighbours together, saying, Rejoice with me; for I have found the piece which I had lost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 10, E'Likewise, I say unto you, there is joy in the presence of the angels of God over one sinner that repenteth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 11, E'And he said, A certain man had two sons:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 12, E'And the younger of them said to his father, Father, give me the portion of goods that falleth to me. And he divided unto them his living.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 13, E'And not many days after the younger son gathered all together, and took his journey into a far country, and there wasted his substance with riotous living.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 14, E'And when he had spent all, there arose a mighty famine in that land; and he began to be in want.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 15, E'And he went and joined himself to a citizen of that country; and he sent him into his fields to feed swine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 16, E'And he would fain have filled his belly with the husks that the swine did eat: and no man gave unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 17, E'And when he came to himself, he said, How many hired servants of my father’s have bread enough and to spare, and I perish with hunger!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 18, E'I will arise and go to my father, and will say unto him, Father, I have sinned against heaven, and before thee,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 19, E'And am no more worthy to be called thy son: make me as one of thy hired servants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 20, E'And he arose, and came to his father. But when he was yet a great way off, his father saw him, and had compassion, and ran, and fell on his neck, and kissed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 21, E'And the son said unto him, Father, I have sinned against heaven, and in thy sight, and am no more worthy to be called thy son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 22, E'But the father said to his servants, Bring forth the best robe, and put it on him; and put a ring on his hand, and shoes on his feet:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 23, E'And bring hither the fatted calf, and kill it; and let us eat, and be merry:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 24, E'For this my son was dead, and is alive again; he was lost, and is found. And they began to be merry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 25, E'Now his elder son was in the field: and as he came and drew nigh to the house, he heard musick and dancing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 26, E'And he called one of the servants, and asked what these things meant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 27, E'And he said unto him, Thy brother is come; and thy father hath killed the fatted calf, because he hath received him safe and sound.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 28, E'And he was angry, and would not go in: therefore came his father out, and intreated him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 29, E'And he answering said to his father, Lo, these many years do I serve thee, neither transgressed I at any time thy commandment: and yet thou never gavest me a kid, that I might make merry with my friends:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 30, E'But as soon as this thy son was come, which hath devoured thy living with harlots, thou hast killed for him the fatted calf.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 31, E'And he said unto him, Son, thou art ever with me, and all that I have is thine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 32, E'It was meet that we should make merry, and be glad: for this thy brother was dead, and is alive again; and was lost, and is found.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 1, E'And he said also unto his disciples, There was a certain rich man, which had a steward; and the same was accused unto him that he had wasted his goods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 2, E'And he called him, and said unto him, How is it that I hear this of thee? give an account of thy stewardship; for thou mayest be no longer steward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 3, E'Then the steward said within himself, What shall I do? for my lord taketh away from me the stewardship: I cannot dig; to beg I am ashamed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 4, E'I am resolved what to do, that, when I am put out of the stewardship, they may receive me into their houses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 5, E'So he called every one of his lord’s debtors unto him, and said unto the first, How much owest thou unto my lord?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 6, E'And he said, An hundred measures of oil. And he said unto him, Take thy bill, and sit down quickly, and write fifty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 7, E'Then said he to another, And how much owest thou? And he said, An hundred measures of wheat. And he said unto him, Take thy bill, and write fourscore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 8, E'And the lord commended the unjust steward, because he had done wisely: for the children of this world are in their generation wiser than the children of light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 9, E'And I say unto you, Make to yourselves friends of the mammon of unrighteousness; that, when ye fail, they may receive you into everlasting habitations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 10, E'He that is faithful in that which is least is faithful also in much: and he that is unjust in the least is unjust also in much.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 11, E'If therefore ye have not been faithful in the unrighteous mammon, who will commit to your trust the true riches?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 12, E'And if ye have not been faithful in that which is another man’s, who shall give you that which is your own?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 13, E'No servant can serve two masters: for either he will hate the one, and love the other; or else he will hold to the one, and despise the other. Ye cannot serve God and mammon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 14, E'And the Pharisees also, who were covetous, heard all these things: and they derided him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 15, E'And he said unto them, Ye are they which justify yourselves before men; but God knoweth your hearts: for that which is highly esteemed among men is abomination in the sight of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 16, E'The law and the prophets were until John: since that time the kingdom of God is preached, and every man presseth into it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 17, E'And it is easier for heaven and earth to pass, than one tittle of the law to fail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 18, E'Whosoever putteth away his wife, and marrieth another, committeth adultery: and whosoever marrieth her that is put away from her husband committeth adultery.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 19, E'There was a certain rich man, which was clothed in purple and fine linen, and fared sumptuously every day:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 20, E'And there was a certain beggar named Lazarus, which was laid at his gate, full of sores,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 21, E'And desiring to be fed with the crumbs which fell from the rich man’s table: moreover the dogs came and licked his sores.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 22, E'And it came to pass, that the beggar died, and was carried by the angels into Abraham’s bosom: the rich man also died, and was buried;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 23, E'And in hell he lift up his eyes, being in torments, and seeth Abraham afar off, and Lazarus in his bosom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 24, E'And he cried and said, Father Abraham, have mercy on me, and send Lazarus, that he may dip the tip of his finger in water, and cool my tongue; for I am tormented in this flame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 25, E'But Abraham said, Son, remember that thou in thy lifetime receivedst thy good things, and likewise Lazarus evil things: but now he is comforted, and thou art tormented.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 26, E'And beside all this, between us and you there is a great gulf fixed: so that they which would pass from hence to you cannot; neither can they pass to us, that would come from thence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 27, E'Then he said, I pray thee therefore, father, that thou wouldest send him to my father’s house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 28, E'For I have five brethren; that he may testify unto them, lest they also come into this place of torment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 29, E'Abraham saith unto him, They have Moses and the prophets; let them hear them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 30, E'And he said, Nay, father Abraham: but if one went unto them from the dead, they will repent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 31, E'And he said unto him, If they hear not Moses and the prophets, neither will they be persuaded, though one rose from the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 1, E'Then said he unto the disciples, It is impossible but that offences will come: but woe unto him, through whom they come!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 2, E'It were better for him that a millstone were hanged about his neck, and he cast into the sea, than that he should offend one of these little ones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 3, E'Take heed to yourselves: If thy brother trespass against thee, rebuke him; and if he repent, forgive him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 4, E'And if he trespass against thee seven times in a day, and seven times in a day turn again to thee, saying, I repent; thou shalt forgive him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 5, E'And the apostles said unto the Lord, Increase our faith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 6, E'And the Lord said, If ye had faith as a grain of mustard seed, ye might say unto this sycamine tree, Be thou plucked up by the root, and be thou planted in the sea; and it should obey you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 7, E'But which of you, having a servant plowing or feeding cattle, will say unto him by and by, when he is come from the field, Go and sit down to meat?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 8, E'And will not rather say unto him, Make ready wherewith I may sup, and gird thyself, and serve me, till I have eaten and drunken; and afterward thou shalt eat and drink?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 9, E'Doth he thank that servant because he did the things that were commanded him? I trow not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 10, E'So likewise ye, when ye shall have done all those things which are commanded you, say, We are unprofitable servants: we have done that which was our duty to do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 11, E'And it came to pass, as he went to Jerusalem, that he passed through the midst of Samaria and Galilee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 12, E'And as he entered into a certain village, there met him ten men that were lepers, which stood afar off:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 13, E'And they lifted up their voices, and said, Jesus, Master, have mercy on us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 14, E'And when he saw them, he said unto them, Go shew yourselves unto the priests. And it came to pass, that, as they went, they were cleansed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 15, E'And one of them, when he saw that he was healed, turned back, and with a loud voice glorified God,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 16, E'And fell down on his face at his feet, giving him thanks: and he was a Samaritan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 17, E'And Jesus answering said, Were there not ten cleansed? but where are the nine?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 18, E'There are not found that returned to give glory to God, save this stranger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 19, E'And he said unto him, Arise, go thy way: thy faith hath made thee whole.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 20, E'And when he was demanded of the Pharisees, when the kingdom of God should come, he answered them and said, The kingdom of God cometh not with observation:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 21, E'Neither shall they say, Lo here! or, lo there! for, behold, the kingdom of God is within you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 22, E'And he said unto the disciples, The days will come, when ye shall desire to see one of the days of the Son of man, and ye shall not see it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 23, E'And they shall say to you, See here; or, see there: go not after them, nor follow them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 24, E'For as the lightning, that lighteneth out of the one part under heaven, shineth unto the other part under heaven; so shall also the Son of man be in his day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 25, E'But first must he suffer many things, and be rejected of this generation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 26, E'And as it was in the days of Noe, so shall it be also in the days of the Son of man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 27, E'They did eat, they drank, they married wives, they were given in marriage, until the day that Noe entered into the ark, and the flood came, and destroyed them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 28, E'Likewise also as it was in the days of Lot; they did eat, they drank, they bought, they sold, they planted, they builded;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 29, E'But the same day that Lot went out of Sodom it rained fire and brimstone from heaven, and destroyed them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 30, E'Even thus shall it be in the day when the Son of man is revealed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 31, E'In that day, he which shall be upon the housetop, and his stuff in the house, let him not come down to take it away: and he that is in the field, let him likewise not return back.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 32, E'Remember Lot’s wife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 33, E'Whosoever shall seek to save his life shall lose it; and whosoever shall lose his life shall preserve it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 34, E'I tell you, in that night there shall be two men in one bed; the one shall be taken, and the other shall be left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 35, E'Two women shall be grinding together; the one shall be taken, and the other left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 36, E'Two men shall be in the field; the one shall be taken, and the other left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 37, E'And they answered and said unto him, Where, Lord? And he said unto them, Wheresoever the body is, thither will the eagles be gathered together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 1, E'And he spake a parable unto them to this end, that men ought always to pray, and not to faint;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 2, E'Saying, There was in a city a judge, which feared not God, neither regarded man:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 3, E'And there was a widow in that city; and she came unto him, saying, Avenge me of mine adversary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 4, E'And he would not for a while: but afterward he said within himself, Though I fear not God, nor regard man;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 5, E'Yet because this widow troubleth me, I will avenge her, lest by her continual coming she weary me.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Luke') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 6, E'And the Lord said, Hear what the unjust judge saith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 7, E'And shall not God avenge his own elect, which cry day and night unto him, though he bear long with them?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 8, E'I tell you that he will avenge them speedily. Nevertheless when the Son of man cometh, shall he find faith on the earth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 9, E'And he spake this parable unto certain which trusted in themselves that they were righteous, and despised others:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 10, E'Two men went up into the temple to pray; the one a Pharisee, and the other a publican.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 11, E'The Pharisee stood and prayed thus with himself, God, I thank thee, that I am not as other men are, extortioners, unjust, adulterers, or even as this publican.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 12, E'I fast twice in the week, I give tithes of all that I possess.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 13, E'And the publican, standing afar off, would not lift up so much as his eyes unto heaven, but smote upon his breast, saying, God be merciful to me a sinner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 14, E'I tell you, this man went down to his house justified rather than the other: for every one that exalteth himself shall be abased; and he that humbleth himself shall be exalted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 15, E'And they brought unto him also infants, that he would touch them: but when his disciples saw it, they rebuked them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 16, E'But Jesus called them unto him, and said, Suffer little children to come unto me, and forbid them not: for of such is the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 17, E'Verily I say unto you, Whosoever shall not receive the kingdom of God as a little child shall in no wise enter therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 18, E'And a certain ruler asked him, saying, Good Master, what shall I do to inherit eternal life?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 19, E'And Jesus said unto him, Why callest thou me good? none is good, save one, that is, God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 20, E'Thou knowest the commandments, Do not commit adultery, Do not kill, Do not steal, Do not bear false witness, Honour thy father and thy mother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 21, E'And he said, All these have I kept from my youth up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 22, E'Now when Jesus heard these things, he said unto him, Yet lackest thou one thing: sell all that thou hast, and distribute unto the poor, and thou shalt have treasure in heaven: and come, follow me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 23, E'And when he heard this, he was very sorrowful: for he was very rich.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 24, E'And when Jesus saw that he was very sorrowful, he said, How hardly shall they that have riches enter into the kingdom of God!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 25, E'For it is easier for a camel to go through a needle’s eye, than for a rich man to enter into the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 26, E'And they that heard it said, Who then can be saved?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 27, E'And he said, The things which are impossible with men are possible with God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 28, E'Then Peter said, Lo, we have left all, and followed thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 29, E'And he said unto them, Verily I say unto you, There is no man that hath left house, or parents, or brethren, or wife, or children, for the kingdom of God’s sake,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 30, E'Who shall not receive manifold more in this present time, and in the world to come life everlasting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 31, E'Then he took unto him the twelve, and said unto them, Behold, we go up to Jerusalem, and all things that are written by the prophets concerning the Son of man shall be accomplished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 32, E'For he shall be delivered unto the Gentiles, and shall be mocked, and spitefully entreated, and spitted on:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 33, E'And they shall scourge him, and put him to death: and the third day he shall rise again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 34, E'And they understood none of these things: and this saying was hid from them, neither knew they the things which were spoken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 35, E'And it came to pass, that as he was come nigh unto Jericho, a certain blind man sat by the way side begging:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 36, E'And hearing the multitude pass by, he asked what it meant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 37, E'And they told him, that Jesus of Nazareth passeth by.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 38, E'And he cried, saying, Jesus, thou son of David, have mercy on me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 39, E'And they which went before rebuked him, that he should hold his peace: but he cried so much the more, Thou son of David, have mercy on me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 40, E'And Jesus stood, and commanded him to be brought unto him: and when he was come near, he asked him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 41, E'Saying, What wilt thou that I shall do unto thee? And he said, Lord, that I may receive my sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 42, E'And Jesus said unto him, Receive thy sight: thy faith hath saved thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 43, E'And immediately he received his sight, and followed him, glorifying God: and all the people, when they saw it, gave praise unto God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 1, E'And Jesus entered and passed through Jericho.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 2, E'And, behold, there was a man named Zacchaeus, which was the chief among the publicans, and he was rich.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 3, E'And he sought to see Jesus who he was; and could not for the press, because he was little of stature.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 4, E'And he ran before, and climbed up into a sycomore tree to see him: for he was to pass that way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 5, E'And when Jesus came to the place, he looked up, and saw him, and said unto him, Zacchaeus, make haste, and come down; for to day I must abide at thy house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 6, E'And he made haste, and came down, and received him joyfully.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 7, E'And when they saw it, they all murmured, saying, That he was gone to be guest with a man that is a sinner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 8, E'And Zacchaeus stood, and said unto the Lord; Behold, Lord, the half of my goods I give to the poor; and if I have taken any thing from any man by false accusation, I restore him fourfold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 9, E'And Jesus said unto him, This day is salvation come to this house, forsomuch as he also is a son of Abraham.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 10, E'For the Son of man is come to seek and to save that which was lost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 11, E'And as they heard these things, he added and spake a parable, because he was nigh to Jerusalem, and because they thought that the kingdom of God should immediately appear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 12, E'He said therefore, A certain nobleman went into a far country to receive for himself a kingdom, and to return.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 13, E'And he called his ten servants, and delivered them ten pounds, and said unto them, Occupy till I come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 14, E'But his citizens hated him, and sent a message after him, saying, We will not have this man to reign over us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 15, E'And it came to pass, that when he was returned, having received the kingdom, then he commanded these servants to be called unto him, to whom he had given the money, that he might know how much every man had gained by trading.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 16, E'Then came the first, saying, Lord, thy pound hath gained ten pounds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 17, E'And he said unto him, Well, thou good servant: because thou hast been faithful in a very little, have thou authority over ten cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 18, E'And the second came, saying, Lord, thy pound hath gained five pounds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 19, E'And he said likewise to him, Be thou also over five cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 20, E'And another came, saying, Lord, behold, here is thy pound, which I have kept laid up in a napkin:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 21, E'For I feared thee, because thou art an austere man: thou takest up that thou layedst not down, and reapest that thou didst not sow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 22, E'And he saith unto him, Out of thine own mouth will I judge thee, thou wicked servant. Thou knewest that I was an austere man, taking up that I laid not down, and reaping that I did not sow:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 23, E'Wherefore then gavest not thou my money into the bank, that at my coming I might have required mine own with usury?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 24, E'And he said unto them that stood by, Take from him the pound, and give it to him that hath ten pounds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 25, E'(And they said unto him, Lord, he hath ten pounds.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 26, E'For I say unto you, That unto every one which hath shall be given; and from him that hath not, even that he hath shall be taken away from him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 27, E'But those mine enemies, which would not that I should reign over them, bring hither, and slay them before me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 28, E'And when he had thus spoken, he went before, ascending up to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 29, E'And it came to pass, when he was come nigh to Bethphage and Bethany, at the mount called the mount of Olives, he sent two of his disciples,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 30, E'Saying, Go ye into the village over against you; in the which at your entering ye shall find a colt tied, whereon yet never man sat: loose him, and bring him hither.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 31, E'And if any man ask you, Why do ye loose him? thus shall ye say unto him, Because the Lord hath need of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 32, E'And they that were sent went their way, and found even as he had said unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 33, E'And as they were loosing the colt, the owners thereof said unto them, Why loose ye the colt?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 34, E'And they said, The Lord hath need of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 35, E'And they brought him to Jesus: and they cast their garments upon the colt, and they set Jesus thereon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 36, E'And as he went, they spread their clothes in the way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 37, E'And when he was come nigh, even now at the descent of the mount of Olives, the whole multitude of the disciples began to rejoice and praise God with a loud voice for all the mighty works that they had seen;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 38, E'Saying, Blessed be the King that cometh in the name of the Lord: peace in heaven, and glory in the highest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 39, E'And some of the Pharisees from among the multitude said unto him, Master, rebuke thy disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 40, E'And he answered and said unto them, I tell you that, if these should hold their peace, the stones would immediately cry out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 41, E'And when he was come near, he beheld the city, and wept over it,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 42, E'Saying, If thou hadst known, even thou, at least in this thy day, the things which belong unto thy peace! but now they are hid from thine eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 43, E'For the days shall come upon thee, that thine enemies shall cast a trench about thee, and compass thee round, and keep thee in on every side,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 44, E'And shall lay thee even with the ground, and thy children within thee; and they shall not leave in thee one stone upon another; because thou knewest not the time of thy visitation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 45, E'And he went into the temple, and began to cast out them that sold therein, and them that bought;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 46, E'Saying unto them, It is written, My house is the house of prayer: but ye have made it a den of thieves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 47, E'And he taught daily in the temple. But the chief priests and the scribes and the chief of the people sought to destroy him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 48, E'And could not find what they might do: for all the people were very attentive to hear him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 1, E'And it came to pass, that on one of those days, as he taught the people in the temple, and preached the gospel, the chief priests and the scribes came upon him with the elders,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 2, E'And spake unto him, saying, Tell us, by what authority doest thou these things? or who is he that gave thee this authority?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 3, E'And he answered and said unto them, I will also ask you one thing; and answer me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 4, E'The baptism of John, was it from heaven, or of men?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 5, E'And they reasoned with themselves, saying, If we shall say, From heaven; he will say, Why then believed ye him not?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 6, E'But and if we say, Of men; all the people will stone us: for they be persuaded that John was a prophet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 7, E'And they answered, that they could not tell whence it was.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 8, E'And Jesus said unto them, Neither tell I you by what authority I do these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 9, E'Then began he to speak to the people this parable; A certain man planted a vineyard, and let it forth to husbandmen, and went into a far country for a long time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 10, E'And at the season he sent a servant to the husbandmen, that they should give him of the fruit of the vineyard: but the husbandmen beat him, and sent him away empty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 11, E'And again he sent another servant: and they beat him also, and entreated him shamefully, and sent him away empty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 12, E'And again he sent a third: and they wounded him also, and cast him out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 13, E'Then said the lord of the vineyard, What shall I do? I will send my beloved son: it may be they will reverence him when they see him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 14, E'But when the husbandmen saw him, they reasoned among themselves, saying, This is the heir: come, let us kill him, that the inheritance may be ours.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Luke') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 15, E'So they cast him out of the vineyard, and killed him. What therefore shall the lord of the vineyard do unto them?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 16, E'He shall come and destroy these husbandmen, and shall give the vineyard to others. And when they heard it, they said, God forbid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 17, E'And he beheld them, and said, What is this then that is written, The stone which the builders rejected, the same is become the head of the corner?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 18, E'Whosoever shall fall upon that stone shall be broken; but on whomsoever it shall fall, it will grind him to powder.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 19, E'And the chief priests and the scribes the same hour sought to lay hands on him; and they feared the people: for they perceived that he had spoken this parable against them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 20, E'And they watched him, and sent forth spies, which should feign themselves just men, that they might take hold of his words, that so they might deliver him unto the power and authority of the governor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 21, E'And they asked him, saying, Master, we know that thou sayest and teachest rightly, neither acceptest thou the person of any, but teachest the way of God truly:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 22, E'Is it lawful for us to give tribute unto Caesar, or no?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 23, E'But he perceived their craftiness, and said unto them, Why tempt ye me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 24, E'Shew me a penny. Whose image and superscription hath it? They answered and said, Caesar’s.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 25, E'And he said unto them, Render therefore unto Caesar the things which be Caesar’s, and unto God the things which be God’s.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 26, E'And they could not take hold of his words before the people: and they marvelled at his answer, and held their peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 27, E'Then came to him certain of the Sadducees, which deny that there is any resurrection; and they asked him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 28, E'Saying, Master, Moses wrote unto us, If any man’s brother die, having a wife, and he die without children, that his brother should take his wife, and raise up seed unto his brother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 29, E'There were therefore seven brethren: and the first took a wife, and died without children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 30, E'And the second took her to wife, and he died childless.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 31, E'And the third took her; and in like manner the seven also: and they left no children, and died.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 32, E'Last of all the woman died also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 33, E'Therefore in the resurrection whose wife of them is she? for seven had her to wife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 34, E'And Jesus answering said unto them, The children of this world marry, and are given in marriage:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 35, E'But they which shall be accounted worthy to obtain that world, and the resurrection from the dead, neither marry, nor are given in marriage:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 36, E'Neither can they die any more: for they are equal unto the angels; and are the children of God, being the children of the resurrection.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 37, E'Now that the dead are raised, even Moses shewed at the bush, when he calleth the Lord the God of Abraham, and the God of Isaac, and the God of Jacob.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 38, E'For he is not a God of the dead, but of the living: for all live unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 39, E'Then certain of the scribes answering said, Master, thou hast well said.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 40, E'And after that they durst not ask him any question at all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 41, E'And he said unto them, How say they that Christ is David’s son?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 42, E'And David himself saith in the book of Psalms, The LORD said unto my Lord, Sit thou on my right hand,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 43, E'Till I make thine enemies thy footstool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 44, E'David therefore calleth him Lord, how is he then his son?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 45, E'Then in the audience of all the people he said unto his disciples,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 46, E'Beware of the scribes, which desire to walk in long robes, and love greetings in the markets, and the highest seats in the synagogues, and the chief rooms at feasts;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 47, E'Which devour widows’ houses, and for a shew make long prayers: the same shall receive greater damnation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 1, E'And he looked up, and saw the rich men casting their gifts into the treasury.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 2, E'And he saw also a certain poor widow casting in thither two mites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 3, E'And he said, Of a truth I say unto you, that this poor widow hath cast in more than they all:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 4, E'For all these have of their abundance cast in unto the offerings of God: but she of her penury hath cast in all the living that she had.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 5, E'And as some spake of the temple, how it was adorned with goodly stones and gifts, he said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 6, E'As for these things which ye behold, the days will come, in the which there shall not be left one stone upon another, that shall not be thrown down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 7, E'And they asked him, saying, Master, but when shall these things be? and what sign will there be when these things shall come to pass?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 8, E'And he said, Take heed that ye be not deceived: for many shall come in my name, saying, I am Christ; and the time draweth near: go ye not therefore after them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 9, E'But when ye shall hear of wars and commotions, be not terrified: for these things must first come to pass; but the end is not by and by.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 10, E'Then said he unto them, Nation shall rise against nation, and kingdom against kingdom:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 11, E'And great earthquakes shall be in divers places, and famines, and pestilences; and fearful sights and great signs shall there be from heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 12, E'But before all these, they shall lay their hands on you, and persecute you, delivering you up to the synagogues, and into prisons, being brought before kings and rulers for my name’s sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 13, E'And it shall turn to you for a testimony.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 14, E'Settle it therefore in your hearts, not to meditate before what ye shall answer:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 15, E'For I will give you a mouth and wisdom, which all your adversaries shall not be able to gainsay nor resist.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 16, E'And ye shall be betrayed both by parents, and brethren, and kinsfolks, and friends; and some of you shall they cause to be put to death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 17, E'And ye shall be hated of all men for my name’s sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 18, E'But there shall not an hair of your head perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 19, E'In your patience possess ye your souls.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 20, E'And when ye shall see Jerusalem compassed with armies, then know that the desolation thereof is nigh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 21, E'Then let them which are in Judaea flee to the mountains; and let them which are in the midst of it depart out; and let not them that are in the countries enter thereinto.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 22, E'For these be the days of vengeance, that all things which are written may be fulfilled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 23, E'But woe unto them that are with child, and to them that give suck, in those days! for there shall be great distress in the land, and wrath upon this people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 24, E'And they shall fall by the edge of the sword, and shall be led away captive into all nations: and Jerusalem shall be trodden down of the Gentiles, until the times of the Gentiles be fulfilled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 25, E'And there shall be signs in the sun, and in the moon, and in the stars; and upon the earth distress of nations, with perplexity; the sea and the waves roaring;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 26, E'Men’s hearts failing them for fear, and for looking after those things which are coming on the earth: for the powers of heaven shall be shaken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 27, E'And then shall they see the Son of man coming in a cloud with power and great glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 28, E'And when these things begin to come to pass, then look up, and lift up your heads; for your redemption draweth nigh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 29, E'And he spake to them a parable; Behold the fig tree, and all the trees;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 30, E'When they now shoot forth, ye see and know of your own selves that summer is now nigh at hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 31, E'So likewise ye, when ye see these things come to pass, know ye that the kingdom of God is nigh at hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 32, E'Verily I say unto you, This generation shall not pass away, till all be fulfilled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 33, E'Heaven and earth shall pass away: but my words shall not pass away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 34, E'And take heed to yourselves, lest at any time your hearts be overcharged with surfeiting, and drunkenness, and cares of this life, and so that day come upon you unawares.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 35, E'For as a snare shall it come on all them that dwell on the face of the whole earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 36, E'Watch ye therefore, and pray always, that ye may be accounted worthy to escape all these things that shall come to pass, and to stand before the Son of man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 37, E'And in the day time he was teaching in the temple; and at night he went out, and abode in the mount that is called the mount of Olives.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 21, 38, E'And all the people came early in the morning to him in the temple, for to hear him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 1, E'Now the feast of unleavened bread drew nigh, which is called the Passover.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 2, E'And the chief priests and scribes sought how they might kill him; for they feared the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 3, E'Then entered Satan into Judas surnamed Iscariot, being of the number of the twelve.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 4, E'And he went his way, and communed with the chief priests and captains, how he might betray him unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 5, E'And they were glad, and covenanted to give him money.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 6, E'And he promised, and sought opportunity to betray him unto them in the absence of the multitude.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 7, E'Then came the day of unleavened bread, when the passover must be killed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 8, E'And he sent Peter and John, saying, Go and prepare us the passover, that we may eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 9, E'And they said unto him, Where wilt thou that we prepare?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 10, E'And he said unto them, Behold, when ye are entered into the city, there shall a man meet you, bearing a pitcher of water; follow him into the house where he entereth in.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 11, E'And ye shall say unto the goodman of the house, The Master saith unto thee, Where is the guestchamber, where I shall eat the passover with my disciples?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 12, E'And he shall shew you a large upper room furnished: there make ready.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 13, E'And they went, and found as he had said unto them: and they made ready the passover.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 14, E'And when the hour was come, he sat down, and the twelve apostles with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 15, E'And he said unto them, With desire I have desired to eat this passover with you before I suffer:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 16, E'For I say unto you, I will not any more eat thereof, until it be fulfilled in the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 17, E'And he took the cup, and gave thanks, and said, Take this, and divide it among yourselves:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 18, E'For I say unto you, I will not drink of the fruit of the vine, until the kingdom of God shall come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 19, E'And he took bread, and gave thanks, and brake it, and gave unto them, saying, This is my body which is given for you: this do in remembrance of me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 20, E'Likewise also the cup after supper, saying, This cup is the new testament in my blood, which is shed for you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 21, E'But, behold, the hand of him that betrayeth me is with me on the table.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 22, E'And truly the Son of man goeth, as it was determined: but woe unto that man by whom he is betrayed!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 23, E'And they began to enquire among themselves, which of them it was that should do this thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 24, E'And there was also a strife among them, which of them should be accounted the greatest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 25, E'And he said unto them, The kings of the Gentiles exercise lordship over them; and they that exercise authority upon them are called benefactors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 26, E'But ye shall not be so: but he that is greatest among you, let him be as the younger; and he that is chief, as he that doth serve.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 27, E'For whether is greater, he that sitteth at meat, or he that serveth? is not he that sitteth at meat? but I am among you as he that serveth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 28, E'Ye are they which have continued with me in my temptations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 29, E'And I appoint unto you a kingdom, as my Father hath appointed unto me;')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Luke') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 30, E'That ye may eat and drink at my table in my kingdom, and sit on thrones judging the twelve tribes of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 31, E'And the Lord said, Simon, Simon, behold, Satan hath desired to have you, that he may sift you as wheat:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 32, E'But I have prayed for thee, that thy faith fail not: and when thou art converted, strengthen thy brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 33, E'And he said unto him, Lord, I am ready to go with thee, both into prison, and to death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 34, E'And he said, I tell thee, Peter, the cock shall not crow this day, before that thou shalt thrice deny that thou knowest me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 35, E'And he said unto them, When I sent you without purse, and scrip, and shoes, lacked ye any thing? And they said, Nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 36, E'Then said he unto them, But now, he that hath a purse, let him take it, and likewise his scrip: and he that hath no sword, let him sell his garment, and buy one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 37, E'For I say unto you, that this that is written must yet be accomplished in me, And he was reckoned among the transgressors: for the things concerning me have an end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 38, E'And they said, Lord, behold, here are two swords. And he said unto them, It is enough.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 39, E'And he came out, and went, as he was wont, to the mount of Olives; and his disciples also followed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 40, E'And when he was at the place, he said unto them, Pray that ye enter not into temptation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 41, E'And he was withdrawn from them about a stone’s cast, and kneeled down, and prayed,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 42, E'Saying, Father, if thou be willing, remove this cup from me: nevertheless not my will, but thine, be done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 43, E'And there appeared an angel unto him from heaven, strengthening him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 44, E'And being in an agony he prayed more earnestly: and his sweat was as it were great drops of blood falling down to the ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 45, E'And when he rose up from prayer, and was come to his disciples, he found them sleeping for sorrow,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 46, E'And said unto them, Why sleep ye? rise and pray, lest ye enter into temptation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 47, E'And while he yet spake, behold a multitude, and he that was called Judas, one of the twelve, went before them, and drew near unto Jesus to kiss him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 48, E'But Jesus said unto him, Judas, betrayest thou the Son of man with a kiss?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 49, E'When they which were about him saw what would follow, they said unto him, Lord, shall we smite with the sword?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 50, E'And one of them smote the servant of the high priest, and cut off his right ear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 51, E'And Jesus answered and said, Suffer ye thus far. And he touched his ear, and healed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 52, E'Then Jesus said unto the chief priests, and captains of the temple, and the elders, which were come to him, Be ye come out, as against a thief, with swords and staves?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 53, E'When I was daily with you in the temple, ye stretched forth no hands against me: but this is your hour, and the power of darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 54, E'Then took they him, and led him, and brought him into the high priest’s house. And Peter followed afar off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 55, E'And when they had kindled a fire in the midst of the hall, and were set down together, Peter sat down among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 56, E'But a certain maid beheld him as he sat by the fire, and earnestly looked upon him, and said, This man was also with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 57, E'And he denied him, saying, Woman, I know him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 58, E'And after a little while another saw him, and said, Thou art also of them. And Peter said, Man, I am not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 59, E'And about the space of one hour after another confidently affirmed, saying, Of a truth this fellow also was with him: for he is a Galilaean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 60, E'And Peter said, Man, I know not what thou sayest. And immediately, while he yet spake, the cock crew.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 61, E'And the Lord turned, and looked upon Peter. And Peter remembered the word of the Lord, how he had said unto him, Before the cock crow, thou shalt deny me thrice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 62, E'And Peter went out, and wept bitterly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 63, E'And the men that held Jesus mocked him, and smote him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 64, E'And when they had blindfolded him, they struck him on the face, and asked him, saying, Prophesy, who is it that smote thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 65, E'And many other things blasphemously spake they against him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 66, E'And as soon as it was day, the elders of the people and the chief priests and the scribes came together, and led him into their council, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 67, E'Art thou the Christ? tell us. And he said unto them, If I tell you, ye will not believe:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 68, E'And if I also ask you, ye will not answer me, nor let me go.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 69, E'Hereafter shall the Son of man sit on the right hand of the power of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 70, E'Then said they all, Art thou then the Son of God? And he said unto them, Ye say that I am.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 22, 71, E'And they said, What need we any further witness? for we ourselves have heard of his own mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 1, E'And the whole multitude of them arose, and led him unto Pilate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 2, E'And they began to accuse him, saying, We found this fellow perverting the nation, and forbidding to give tribute to Caesar, saying that he himself is Christ a King.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 3, E'And Pilate asked him, saying, Art thou the King of the Jews? And he answered him and said, Thou sayest it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 4, E'Then said Pilate to the chief priests and to the people, I find no fault in this man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 5, E'And they were the more fierce, saying, He stirreth up the people, teaching throughout all Jewry, beginning from Galilee to this place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 6, E'When Pilate heard of Galilee, he asked whether the man were a Galilaean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 7, E'And as soon as he knew that he belonged unto Herod’s jurisdiction, he sent him to Herod, who himself also was at Jerusalem at that time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 8, E'And when Herod saw Jesus, he was exceeding glad: for he was desirous to see him of a long season, because he had heard many things of him; and he hoped to have seen some miracle done by him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 9, E'Then he questioned with him in many words; but he answered him nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 10, E'And the chief priests and scribes stood and vehemently accused him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 11, E'And Herod with his men of war set him at nought, and mocked him, and arrayed him in a gorgeous robe, and sent him again to Pilate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 12, E'And the same day Pilate and Herod were made friends together: for before they were at enmity between themselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 13, E'And Pilate, when he had called together the chief priests and the rulers and the people,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 14, E'Said unto them, Ye have brought this man unto me, as one that perverteth the people: and, behold, I, having examined him before you, have found no fault in this man touching those things whereof ye accuse him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 15, E'No, nor yet Herod: for I sent you to him; and, lo, nothing worthy of death is done unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 16, E'I will therefore chastise him, and release him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 17, E'(For of necessity he must release one unto them at the feast.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 18, E'And they cried out all at once, saying, Away with this man, and release unto us Barabbas:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 19, E'(Who for a certain sedition made in the city, and for murder, was cast into prison.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 20, E'Pilate therefore, willing to release Jesus, spake again to them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 21, E'But they cried, saying, Crucify him, crucify him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 22, E'And he said unto them the third time, Why, what evil hath he done? I have found no cause of death in him: I will therefore chastise him, and let him go.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 23, E'And they were instant with loud voices, requiring that he might be crucified. And the voices of them and of the chief priests prevailed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 24, E'And Pilate gave sentence that it should be as they required.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 25, E'And he released unto them him that for sedition and murder was cast into prison, whom they had desired; but he delivered Jesus to their will.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 26, E'And as they led him away, they laid hold upon one Simon, a Cyrenian, coming out of the country, and on him they laid the cross, that he might bear it after Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 27, E'And there followed him a great company of people, and of women, which also bewailed and lamented him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 28, E'But Jesus turning unto them said, Daughters of Jerusalem, weep not for me, but weep for yourselves, and for your children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 29, E'For, behold, the days are coming, in the which they shall say, Blessed are the barren, and the wombs that never bare, and the paps which never gave suck.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 30, E'Then shall they begin to say to the mountains, Fall on us; and to the hills, Cover us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 31, E'For if they do these things in a green tree, what shall be done in the dry?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 32, E'And there were also two other, malefactors, led with him to be put to death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 33, E'And when they were come to the place, which is called Calvary, there they crucified him, and the malefactors, one on the right hand, and the other on the left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 34, E'Then said Jesus, Father, forgive them; for they know not what they do. And they parted his raiment, and cast lots.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 35, E'And the people stood beholding. And the rulers also with them derided him, saying, He saved others; let him save himself, if he be Christ, the chosen of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 36, E'And the soldiers also mocked him, coming to him, and offering him vinegar,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 37, E'And saying, If thou be the king of the Jews, save thyself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 38, E'And a superscription also was written over him in letters of Greek, and Latin, and Hebrew, THIS IS THE KING OF THE JEWS.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 39, E'And one of the malefactors which were hanged railed on him, saying, If thou be Christ, save thyself and us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 40, E'But the other answering rebuked him, saying, Dost not thou fear God, seeing thou art in the same condemnation?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 41, E'And we indeed justly; for we receive the due reward of our deeds: but this man hath done nothing amiss.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 42, E'And he said unto Jesus, Lord, remember me when thou comest into thy kingdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 43, E'And Jesus said unto him, Verily I say unto thee, To day shalt thou be with me in paradise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 44, E'And it was about the sixth hour, and there was a darkness over all the earth until the ninth hour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 45, E'And the sun was darkened, and the veil of the temple was rent in the midst.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 46, E'And when Jesus had cried with a loud voice, he said, Father, into thy hands I commend my spirit: and having said thus, he gave up the ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 47, E'Now when the centurion saw what was done, he glorified God, saying, Certainly this was a righteous man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 48, E'And all the people that came together to that sight, beholding the things which were done, smote their breasts, and returned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 49, E'And all his acquaintance, and the women that followed him from Galilee, stood afar off, beholding these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 50, E'And, behold, there was a man named Joseph, a counsellor; and he was a good man, and a just:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 51, E'(The same had not consented to the counsel and deed of them;) he was of Arimathaea, a city of the Jews: who also himself waited for the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 52, E'This man went unto Pilate, and begged the body of Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 53, E'And he took it down, and wrapped it in linen, and laid it in a sepulchre that was hewn in stone, wherein never man before was laid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 54, E'And that day was the preparation, and the sabbath drew on.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 55, E'And the women also, which came with him from Galilee, followed after, and beheld the sepulchre, and how his body was laid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 23, 56, E'And they returned, and prepared spices and ointments; and rested the sabbath day according to the commandment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 1, E'Now upon the first day of the week, very early in the morning, they came unto the sepulchre, bringing the spices which they had prepared, and certain others with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 2, E'And they found the stone rolled away from the sepulchre.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Luke') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 3, E'And they entered in, and found not the body of the Lord Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 4, E'And it came to pass, as they were much perplexed thereabout, behold, two men stood by them in shining garments:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 5, E'And as they were afraid, and bowed down their faces to the earth, they said unto them, Why seek ye the living among the dead?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 6, E'He is not here, but is risen: remember how he spake unto you when he was yet in Galilee,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 7, E'Saying, The Son of man must be delivered into the hands of sinful men, and be crucified, and the third day rise again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 8, E'And they remembered his words,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 9, E'And returned from the sepulchre, and told all these things unto the eleven, and to all the rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 10, E'It was Mary Magdalene, and Joanna, and Mary the mother of James, and other women that were with them, which told these things unto the apostles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 11, E'And their words seemed to them as idle tales, and they believed them not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 12, E'Then arose Peter, and ran unto the sepulchre; and stooping down, he beheld the linen clothes laid by themselves, and departed, wondering in himself at that which was come to pass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 13, E'And, behold, two of them went that same day to a village called Emmaus, which was from Jerusalem about threescore furlongs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 14, E'And they talked together of all these things which had happened.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 15, E'And it came to pass, that, while they communed together and reasoned, Jesus himself drew near, and went with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 16, E'But their eyes were holden that they should not know him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 17, E'And he said unto them, What manner of communications are these that ye have one to another, as ye walk, and are sad?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 18, E'And the one of them, whose name was Cleopas, answering said unto him, Art thou only a stranger in Jerusalem, and hast not known the things which are come to pass there in these days?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 19, E'And he said unto them, What things? And they said unto him, Concerning Jesus of Nazareth, which was a prophet mighty in deed and word before God and all the people:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 20, E'And how the chief priests and our rulers delivered him to be condemned to death, and have crucified him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 21, E'But we trusted that it had been he which should have redeemed Israel: and beside all this, to day is the third day since these things were done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 22, E'Yea, and certain women also of our company made us astonished, which were early at the sepulchre;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 23, E'And when they found not his body, they came, saying, that they had also seen a vision of angels, which said that he was alive.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 24, E'And certain of them which were with us went to the sepulchre, and found it even so as the women had said: but him they saw not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 25, E'Then he said unto them, O fools, and slow of heart to believe all that the prophets have spoken:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 26, E'Ought not Christ to have suffered these things, and to enter into his glory?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 27, E'And beginning at Moses and all the prophets, he expounded unto them in all the scriptures the things concerning himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 28, E'And they drew nigh unto the village, whither they went: and he made as though he would have gone further.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 29, E'But they constrained him, saying, Abide with us: for it is toward evening, and the day is far spent. And he went in to tarry with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 30, E'And it came to pass, as he sat at meat with them, he took bread, and blessed it, and brake, and gave to them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 31, E'And their eyes were opened, and they knew him; and he vanished out of their sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 32, E'And they said one to another, Did not our heart burn within us, while he talked with us by the way, and while he opened to us the scriptures?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 33, E'And they rose up the same hour, and returned to Jerusalem, and found the eleven gathered together, and them that were with them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 34, E'Saying, The Lord is risen indeed, and hath appeared to Simon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 35, E'And they told what things were done in the way, and how he was known of them in breaking of bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 36, E'And as they thus spake, Jesus himself stood in the midst of them, and saith unto them, Peace be unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 37, E'But they were terrified and affrighted, and supposed that they had seen a spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 38, E'And he said unto them, Why are ye troubled? and why do thoughts arise in your hearts?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 39, E'Behold my hands and my feet, that it is I myself: handle me, and see; for a spirit hath not flesh and bones, as ye see me have.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 40, E'And when he had thus spoken, he shewed them his hands and his feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 41, E'And while they yet believed not for joy, and wondered, he said unto them, Have ye here any meat?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 42, E'And they gave him a piece of a broiled fish, and of an honeycomb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 43, E'And he took it, and did eat before them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 44, E'And he said unto them, These are the words which I spake unto you, while I was yet with you, that all things must be fulfilled, which were written in the law of Moses, and in the prophets, and in the psalms, concerning me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 45, E'Then opened he their understanding, that they might understand the scriptures,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 46, E'And said unto them, Thus it is written, and thus it behoved Christ to suffer, and to rise from the dead the third day:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 47, E'And that repentance and remission of sins should be preached in his name among all nations, beginning at Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 48, E'And ye are witnesses of these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 49, E'And, behold, I send the promise of my Father upon you: but tarry ye in the city of Jerusalem, until ye be endued with power from on high.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 50, E'And he led them out as far as to Bethany, and he lifted up his hands, and blessed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 51, E'And it came to pass, while he blessed them, he was parted from them, and carried up into heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 52, E'And they worshipped him, and returned to Jerusalem with great joy:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 24, 53, E'And were continually in the temple, praising and blessing God. Amen.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Luke') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 1, E'In the beginning was the Word, and the Word was with God, and the Word was God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 2, E'The same was in the beginning with God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 3, E'All things were made by him; and without him was not any thing made that was made.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 4, E'In him was life; and the life was the light of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 5, E'And the light shineth in darkness; and the darkness comprehended it not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 6, E'There was a man sent from God, whose name was John.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 7, E'The same came for a witness, to bear witness of the Light, that all men through him might believe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 8, E'He was not that Light, but was sent to bear witness of that Light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 9, E'That was the true Light, which lighteth every man that cometh into the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 10, E'He was in the world, and the world was made by him, and the world knew him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 11, E'He came unto his own, and his own received him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 12, E'But as many as received him, to them gave he power to become the sons of God, even to them that believe on his name:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 13, E'Which were born, not of blood, nor of the will of the flesh, nor of the will of man, but of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 14, E'And the Word was made flesh, and dwelt among us, (and we beheld his glory, the glory as of the only begotten of the Father,) full of grace and truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 15, E'John bare witness of him, and cried, saying, This was he of whom I spake, He that cometh after me is preferred before me: for he was before me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 16, E'And of his fulness have all we received, and grace for grace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 17, E'For the law was given by Moses, but grace and truth came by Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 18, E'No man hath seen God at any time; the only begotten Son, which is in the bosom of the Father, he hath declared him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 19, E'And this is the record of John, when the Jews sent priests and Levites from Jerusalem to ask him, Who art thou?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 20, E'And he confessed, and denied not; but confessed, I am not the Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 21, E'And they asked him, What then? Art thou Elias? And he saith, I am not. Art thou that prophet? And he answered, No.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 22, E'Then said they unto him, Who art thou? that we may give an answer to them that sent us. What sayest thou of thyself?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 23, E'He said, I am the voice of one crying in the wilderness, Make straight the way of the Lord, as said the prophet Esaias.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 24, E'And they which were sent were of the Pharisees.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 25, E'And they asked him, and said unto him, Why baptizest thou then, if thou be not that Christ, nor Elias, neither that prophet?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 26, E'John answered them, saying, I baptize with water: but there standeth one among you, whom ye know not;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 27, E'He it is, who coming after me is preferred before me, whose shoe’s latchet I am not worthy to unloose.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 28, E'These things were done in Bethabara beyond Jordan, where John was baptizing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 29, E'The next day John seeth Jesus coming unto him, and saith, Behold the Lamb of God, which taketh away the sin of the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 30, E'This is he of whom I said, After me cometh a man which is preferred before me: for he was before me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 31, E'And I knew him not: but that he should be made manifest to Israel, therefore am I come baptizing with water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 32, E'And John bare record, saying, I saw the Spirit descending from heaven like a dove, and it abode upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 33, E'And I knew him not: but he that sent me to baptize with water, the same said unto me, Upon whom thou shalt see the Spirit descending, and remaining on him, the same is he which baptizeth with the Holy Ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 34, E'And I saw, and bare record that this is the Son of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 35, E'Again the next day after John stood, and two of his disciples;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 36, E'And looking upon Jesus as he walked, he saith, Behold the Lamb of God!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 37, E'And the two disciples heard him speak, and they followed Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 38, E'Then Jesus turned, and saw them following, and saith unto them, What seek ye? They said unto him, Rabbi, (which is to say, being interpreted, Master,) where dwellest thou?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 39, E'He saith unto them, Come and see. They came and saw where he dwelt, and abode with him that day: for it was about the tenth hour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 40, E'One of the two which heard John speak, and followed him, was Andrew, Simon Peter’s brother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 41, E'He first findeth his own brother Simon, and saith unto him, We have found the Messias, which is, being interpreted, the Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 42, E'And he brought him to Jesus. And when Jesus beheld him, he said, Thou art Simon the son of Jona: thou shalt be called Cephas, which is by interpretation, A stone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 43, E'The day following Jesus would go forth into Galilee, and findeth Philip, and saith unto him, Follow me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 44, E'Now Philip was of Bethsaida, the city of Andrew and Peter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 45, E'Philip findeth Nathanael, and saith unto him, We have found him, of whom Moses in the law, and the prophets, did write, Jesus of Nazareth, the son of Joseph.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 46, E'And Nathanael said unto him, Can there any good thing come out of Nazareth? Philip saith unto him, Come and see.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 47, E'Jesus saw Nathanael coming to him, and saith of him, Behold an Israelite indeed, in whom is no guile!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 48, E'Nathanael saith unto him, Whence knowest thou me? Jesus answered and said unto him, Before that Philip called thee, when thou wast under the fig tree, I saw thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 49, E'Nathanael answered and saith unto him, Rabbi, thou art the Son of God; thou art the King of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 50, E'Jesus answered and said unto him, Because I said unto thee, I saw thee under the fig tree, believest thou? thou shalt see greater things than these.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 1, 51, E'And he saith unto him, Verily, verily, I say unto you, Hereafter ye shall see heaven open, and the angels of God ascending and descending upon the Son of man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 1, E'And the third day there was a marriage in Cana of Galilee; and the mother of Jesus was there:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 2, E'And both Jesus was called, and his disciples, to the marriage.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 3, E'And when they wanted wine, the mother of Jesus saith unto him, They have no wine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 4, E'Jesus saith unto her, Woman, what have I to do with thee? mine hour is not yet come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 5, E'His mother saith unto the servants, Whatsoever he saith unto you, do it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 6, E'And there were set there six waterpots of stone, after the manner of the purifying of the Jews, containing two or three firkins apiece.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 7, E'Jesus saith unto them, Fill the waterpots with water. And they filled them up to the brim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 8, E'And he saith unto them, Draw out now, and bear unto the governor of the feast. And they bare it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 9, E'When the ruler of the feast had tasted the water that was made wine, and knew not whence it was: (but the servants which drew the water knew;) the governor of the feast called the bridegroom,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 10, E'And saith unto him, Every man at the beginning doth set forth good wine; and when men have well drunk, then that which is worse: but thou hast kept the good wine until now.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 11, E'This beginning of miracles did Jesus in Cana of Galilee, and manifested forth his glory; and his disciples believed on him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 12, E'After this he went down to Capernaum, he, and his mother, and his brethren, and his disciples: and they continued there not many days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 13, E'And the Jews’ passover was at hand, and Jesus went up to Jerusalem,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 14, E'And found in the temple those that sold oxen and sheep and doves, and the changers of money sitting:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 15, E'And when he had made a scourge of small cords, he drove them all out of the temple, and the sheep, and the oxen; and poured out the changers’ money, and overthrew the tables;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 16, E'And said unto them that sold doves, Take these things hence; make not my Father’s house an house of merchandise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 17, E'And his disciples remembered that it was written, The zeal of thine house hath eaten me up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 18, E'Then answered the Jews and said unto him, What sign shewest thou unto us, seeing that thou doest these things?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 19, E'Jesus answered and said unto them, Destroy this temple, and in three days I will raise it up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 20, E'Then said the Jews, Forty and six years was this temple in building, and wilt thou rear it up in three days?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 21, E'But he spake of the temple of his body.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 22, E'When therefore he was risen from the dead, his disciples remembered that he had said this unto them; and they believed the scripture, and the word which Jesus had said.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 23, E'Now when he was in Jerusalem at the passover, in the feast day, many believed in his name, when they saw the miracles which he did.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 24, E'But Jesus did not commit himself unto them, because he knew all men,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 2, 25, E'And needed not that any should testify of man: for he knew what was in man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 1, E'There was a man of the Pharisees, named Nicodemus, a ruler of the Jews:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 2, E'The same came to Jesus by night, and said unto him, Rabbi, we know that thou art a teacher come from God: for no man can do these miracles that thou doest, except God be with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 3, E'Jesus answered and said unto him, Verily, verily, I say unto thee, Except a man be born again, he cannot see the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 4, E'Nicodemus saith unto him, How can a man be born when he is old? can he enter the second time into his mother’s womb, and be born?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 5, E'Jesus answered, Verily, verily, I say unto thee, Except a man be born of water and of the Spirit, he cannot enter into the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 6, E'That which is born of the flesh is flesh; and that which is born of the Spirit is spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 7, E'Marvel not that I said unto thee, Ye must be born again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 8, E'The wind bloweth where it listeth, and thou hearest the sound thereof, but canst not tell whence it cometh, and whither it goeth: so is every one that is born of the Spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 9, E'Nicodemus answered and said unto him, How can these things be?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 10, E'Jesus answered and said unto him, Art thou a master of Israel, and knowest not these things?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 11, E'Verily, verily, I say unto thee, We speak that we do know, and testify that we have seen; and ye receive not our witness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 12, E'If I have told you earthly things, and ye believe not, how shall ye believe, if I tell you of heavenly things?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 13, E'And no man hath ascended up to heaven, but he that came down from heaven, even the Son of man which is in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 14, E'And as Moses lifted up the serpent in the wilderness, even so must the Son of man be lifted up:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 15, E'That whosoever believeth in him should not perish, but have eternal life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 16, E'For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 17, E'For God sent not his Son into the world to condemn the world; but that the world through him might be saved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 18, E'He that believeth on him is not condemned: but he that believeth not is condemned already, because he hath not believed in the name of the only begotten Son of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 19, E'And this is the condemnation, that light is come into the world, and men loved darkness rather than light, because their deeds were evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 20, E'For every one that doeth evil hateth the light, neither cometh to the light, lest his deeds should be reproved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 21, E'But he that doeth truth cometh to the light, that his deeds may be made manifest, that they are wrought in God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 22, E'After these things came Jesus and his disciples into the land of Judaea; and there he tarried with them, and baptized.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 23, E'And John also was baptizing in Aenon near to Salim, because there was much water there: and they came, and were baptized.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 24, E'For John was not yet cast into prison.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'John') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 25, E'Then there arose a question between some of John’s disciples and the Jews about purifying.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 26, E'And they came unto John, and said unto him, Rabbi, he that was with thee beyond Jordan, to whom thou barest witness, behold, the same baptizeth, and all men come to him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 27, E'John answered and said, A man can receive nothing, except it be given him from heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 28, E'Ye yourselves bear me witness, that I said, I am not the Christ, but that I am sent before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 29, E'He that hath the bride is the bridegroom: but the friend of the bridegroom, which standeth and heareth him, rejoiceth greatly because of the bridegroom’s voice: this my joy therefore is fulfilled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 30, E'He must increase, but I must decrease.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 31, E'He that cometh from above is above all: he that is of the earth is earthly, and speaketh of the earth: he that cometh from heaven is above all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 32, E'And what he hath seen and heard, that he testifieth; and no man receiveth his testimony.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 33, E'He that hath received his testimony hath set to his seal that God is true.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 34, E'For he whom God hath sent speaketh the words of God: for God giveth not the Spirit by measure unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 35, E'The Father loveth the Son, and hath given all things into his hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 3, 36, E'He that believeth on the Son hath everlasting life: and he that believeth not the Son shall not see life; but the wrath of God abideth on him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 1, E'When therefore the LORD knew how the Pharisees had heard that Jesus made and baptized more disciples than John,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 2, E'(Though Jesus himself baptized not, but his disciples,)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 3, E'He left Judaea, and departed again into Galilee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 4, E'And he must needs go through Samaria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 5, E'Then cometh he to a city of Samaria, which is called Sychar, near to the parcel of ground that Jacob gave to his son Joseph.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 6, E'Now Jacob’s well was there. Jesus therefore, being wearied with his journey, sat thus on the well: and it was about the sixth hour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 7, E'There cometh a woman of Samaria to draw water: Jesus saith unto her, Give me to drink.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 8, E'(For his disciples were gone away unto the city to buy meat.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 9, E'Then saith the woman of Samaria unto him, How is it that thou, being a Jew, askest drink of me, which am a woman of Samaria? for the Jews have no dealings with the Samaritans.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 10, E'Jesus answered and said unto her, If thou knewest the gift of God, and who it is that saith to thee, Give me to drink; thou wouldest have asked of him, and he would have given thee living water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 11, E'The woman saith unto him, Sir, thou hast nothing to draw with, and the well is deep: from whence then hast thou that living water?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 12, E'Art thou greater than our father Jacob, which gave us the well, and drank thereof himself, and his children, and his cattle?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 13, E'Jesus answered and said unto her, Whosoever drinketh of this water shall thirst again:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 14, E'But whosoever drinketh of the water that I shall give him shall never thirst; but the water that I shall give him shall be in him a well of water springing up into everlasting life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 15, E'The woman saith unto him, Sir, give me this water, that I thirst not, neither come hither to draw.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 16, E'Jesus saith unto her, Go, call thy husband, and come hither.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 17, E'The woman answered and said, I have no husband. Jesus said unto her, Thou hast well said, I have no husband:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 18, E'For thou hast had five husbands; and he whom thou now hast is not thy husband: in that saidst thou truly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 19, E'The woman saith unto him, Sir, I perceive that thou art a prophet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 20, E'Our fathers worshipped in this mountain; and ye say, that in Jerusalem is the place where men ought to worship.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 21, E'Jesus saith unto her, Woman, believe me, the hour cometh, when ye shall neither in this mountain, nor yet at Jerusalem, worship the Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 22, E'Ye worship ye know not what: we know what we worship: for salvation is of the Jews.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 23, E'But the hour cometh, and now is, when the true worshippers shall worship the Father in spirit and in truth: for the Father seeketh such to worship him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 24, E'God is a Spirit: and they that worship him must worship him in spirit and in truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 25, E'The woman saith unto him, I know that Messias cometh, which is called Christ: when he is come, he will tell us all things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 26, E'Jesus saith unto her, I that speak unto thee am he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 27, E'And upon this came his disciples, and marvelled that he talked with the woman: yet no man said, What seekest thou? or, Why talkest thou with her?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 28, E'The woman then left her waterpot, and went her way into the city, and saith to the men,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 29, E'Come, see a man, which told me all things that ever I did: is not this the Christ?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 30, E'Then they went out of the city, and came unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 31, E'In the mean while his disciples prayed him, saying, Master, eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 32, E'But he said unto them, I have meat to eat that ye know not of.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 33, E'Therefore said the disciples one to another, Hath any man brought him ought to eat?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 34, E'Jesus saith unto them, My meat is to do the will of him that sent me, and to finish his work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 35, E'Say not ye, There are yet four months, and then cometh harvest? behold, I say unto you, Lift up your eyes, and look on the fields; for they are white already to harvest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 36, E'And he that reapeth receiveth wages, and gathereth fruit unto life eternal: that both he that soweth and he that reapeth may rejoice together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 37, E'And herein is that saying true, One soweth, and another reapeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 38, E'I sent you to reap that whereon ye bestowed no labour: other men laboured, and ye are entered into their labours.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 39, E'And many of the Samaritans of that city believed on him for the saying of the woman, which testified, He told me all that ever I did.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 40, E'So when the Samaritans were come unto him, they besought him that he would tarry with them: and he abode there two days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 41, E'And many more believed because of his own word;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 42, E'And said unto the woman, Now we believe, not because of thy saying: for we have heard him ourselves, and know that this is indeed the Christ, the Saviour of the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 43, E'Now after two days he departed thence, and went into Galilee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 44, E'For Jesus himself testified, that a prophet hath no honour in his own country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 45, E'Then when he was come into Galilee, the Galilaeans received him, having seen all the things that he did at Jerusalem at the feast: for they also went unto the feast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 46, E'So Jesus came again into Cana of Galilee, where he made the water wine. And there was a certain nobleman, whose son was sick at Capernaum.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 47, E'When he heard that Jesus was come out of Judaea into Galilee, he went unto him, and besought him that he would come down, and heal his son: for he was at the point of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 48, E'Then said Jesus unto him, Except ye see signs and wonders, ye will not believe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 49, E'The nobleman saith unto him, Sir, come down ere my child die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 50, E'Jesus saith unto him, Go thy way; thy son liveth. And the man believed the word that Jesus had spoken unto him, and he went his way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 51, E'And as he was now going down, his servants met him, and told him, saying, Thy son liveth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 52, E'Then enquired he of them the hour when he began to amend. And they said unto him, Yesterday at the seventh hour the fever left him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 53, E'So the father knew that it was at the same hour, in the which Jesus said unto him, Thy son liveth: and himself believed, and his whole house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 4, 54, E'This is again the second miracle that Jesus did, when he was come out of Judaea into Galilee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 1, E'After this there was a feast of the Jews; and Jesus went up to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 2, E'Now there is at Jerusalem by the sheep market a pool, which is called in the Hebrew tongue Bethesda, having five porches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 3, E'In these lay a great multitude of impotent folk, of blind, halt, withered, waiting for the moving of the water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 4, E'For an angel went down at a certain season into the pool, and troubled the water: whosoever then first after the troubling of the water stepped in was made whole of whatsoever disease he had.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 5, E'And a certain man was there, which had an infirmity thirty and eight years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 6, E'When Jesus saw him lie, and knew that he had been now a long time in that case, he saith unto him, Wilt thou be made whole?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 7, E'The impotent man answered him, Sir, I have no man, when the water is troubled, to put me into the pool: but while I am coming, another steppeth down before me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 8, E'Jesus saith unto him, Rise, take up thy bed, and walk.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 9, E'And immediately the man was made whole, and took up his bed, and walked: and on the same day was the sabbath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 10, E'The Jews therefore said unto him that was cured, It is the sabbath day: it is not lawful for thee to carry thy bed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 11, E'He answered them, He that made me whole, the same said unto me, Take up thy bed, and walk.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 12, E'Then asked they him, What man is that which said unto thee, Take up thy bed, and walk?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 13, E'And he that was healed wist not who it was: for Jesus had conveyed himself away, a multitude being in that place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 14, E'Afterward Jesus findeth him in the temple, and said unto him, Behold, thou art made whole: sin no more, lest a worse thing come unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 15, E'The man departed, and told the Jews that it was Jesus, which had made him whole.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 16, E'And therefore did the Jews persecute Jesus, and sought to slay him, because he had done these things on the sabbath day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 17, E'But Jesus answered them, My Father worketh hitherto, and I work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 18, E'Therefore the Jews sought the more to kill him, because he not only had broken the sabbath, but said also that God was his Father, making himself equal with God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 19, E'Then answered Jesus and said unto them, Verily, verily, I say unto you, The Son can do nothing of himself, but what he seeth the Father do: for what things soever he doeth, these also doeth the Son likewise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 20, E'For the Father loveth the Son, and sheweth him all things that himself doeth: and he will shew him greater works than these, that ye may marvel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 21, E'For as the Father raiseth up the dead, and quickeneth them; even so the Son quickeneth whom he will.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 22, E'For the Father judgeth no man, but hath committed all judgment unto the Son:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 23, E'That all men should honour the Son, even as they honour the Father. He that honoureth not the Son honoureth not the Father which hath sent him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 24, E'Verily, verily, I say unto you, He that heareth my word, and believeth on him that sent me, hath everlasting life, and shall not come into condemnation; but is passed from death unto life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 25, E'Verily, verily, I say unto you, The hour is coming, and now is, when the dead shall hear the voice of the Son of God: and they that hear shall live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 26, E'For as the Father hath life in himself; so hath he given to the Son to have life in himself;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 27, E'And hath given him authority to execute judgment also, because he is the Son of man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 28, E'Marvel not at this: for the hour is coming, in the which all that are in the graves shall hear his voice,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 29, E'And shall come forth; they that have done good, unto the resurrection of life; and they that have done evil, unto the resurrection of damnation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 30, E'I can of mine own self do nothing: as I hear, I judge: and my judgment is just; because I seek not mine own will, but the will of the Father which hath sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 31, E'If I bear witness of myself, my witness is not true.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 32, E'There is another that beareth witness of me; and I know that the witness which he witnesseth of me is true.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 33, E'Ye sent unto John, and he bare witness unto the truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 34, E'But I receive not testimony from man: but these things I say, that ye might be saved.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'John') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 35, E'He was a burning and a shining light: and ye were willing for a season to rejoice in his light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 36, E'But I have greater witness than that of John: for the works which the Father hath given me to finish, the same works that I do, bear witness of me, that the Father hath sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 37, E'And the Father himself, which hath sent me, hath borne witness of me. Ye have neither heard his voice at any time, nor seen his shape.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 38, E'And ye have not his word abiding in you: for whom he hath sent, him ye believe not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 39, E'Search the scriptures; for in them ye think ye have eternal life: and they are they which testify of me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 40, E'And ye will not come to me, that ye might have life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 41, E'I receive not honour from men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 42, E'But I know you, that ye have not the love of God in you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 43, E'I am come in my Father’s name, and ye receive me not: if another shall come in his own name, him ye will receive.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 44, E'How can ye believe, which receive honour one of another, and seek not the honour that cometh from God only?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 45, E'Do not think that I will accuse you to the Father: there is one that accuseth you, even Moses, in whom ye trust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 46, E'For had ye believed Moses, ye would have believed me: for he wrote of me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 5, 47, E'But if ye believe not his writings, how shall ye believe my words?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 1, E'After these things Jesus went over the sea of Galilee, which is the sea of Tiberias.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 2, E'And a great multitude followed him, because they saw his miracles which he did on them that were diseased.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 3, E'And Jesus went up into a mountain, and there he sat with his disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 4, E'And the passover, a feast of the Jews, was nigh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 5, E'When Jesus then lifted up his eyes, and saw a great company come unto him, he saith unto Philip, Whence shall we buy bread, that these may eat?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 6, E'And this he said to prove him: for he himself knew what he would do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 7, E'Philip answered him, Two hundred pennyworth of bread is not sufficient for them, that every one of them may take a little.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 8, E'One of his disciples, Andrew, Simon Peter’s brother, saith unto him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 9, E'There is a lad here, which hath five barley loaves, and two small fishes: but what are they among so many?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 10, E'And Jesus said, Make the men sit down. Now there was much grass in the place. So the men sat down, in number about five thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 11, E'And Jesus took the loaves; and when he had given thanks, he distributed to the disciples, and the disciples to them that were set down; and likewise of the fishes as much as they would.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 12, E'When they were filled, he said unto his disciples, Gather up the fragments that remain, that nothing be lost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 13, E'Therefore they gathered them together, and filled twelve baskets with the fragments of the five barley loaves, which remained over and above unto them that had eaten.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 14, E'Then those men, when they had seen the miracle that Jesus did, said, This is of a truth that prophet that should come into the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 15, E'When Jesus therefore perceived that they would come and take him by force, to make him a king, he departed again into a mountain himself alone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 16, E'And when even was now come, his disciples went down unto the sea,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 17, E'And entered into a ship, and went over the sea toward Capernaum. And it was now dark, and Jesus was not come to them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 18, E'And the sea arose by reason of a great wind that blew.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 19, E'So when they had rowed about five and twenty or thirty furlongs, they see Jesus walking on the sea, and drawing nigh unto the ship: and they were afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 20, E'But he saith unto them, It is I; be not afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 21, E'Then they willingly received him into the ship: and immediately the ship was at the land whither they went.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 22, E'The day following, when the people which stood on the other side of the sea saw that there was none other boat there, save that one whereinto his disciples were entered, and that Jesus went not with his disciples into the boat, but that his disciples were gone away alone;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 23, E'(Howbeit there came other boats from Tiberias nigh unto the place where they did eat bread, after that the Lord had given thanks:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 24, E'When the people therefore saw that Jesus was not there, neither his disciples, they also took shipping, and came to Capernaum, seeking for Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 25, E'And when they had found him on the other side of the sea, they said unto him, Rabbi, when camest thou hither?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 26, E'Jesus answered them and said, Verily, verily, I say unto you, Ye seek me, not because ye saw the miracles, but because ye did eat of the loaves, and were filled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 27, E'Labour not for the meat which perisheth, but for that meat which endureth unto everlasting life, which the Son of man shall give unto you: for him hath God the Father sealed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 28, E'Then said they unto him, What shall we do, that we might work the works of God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 29, E'Jesus answered and said unto them, This is the work of God, that ye believe on him whom he hath sent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 30, E'They said therefore unto him, What sign shewest thou then, that we may see, and believe thee? what dost thou work?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 31, E'Our fathers did eat manna in the desert; as it is written, He gave them bread from heaven to eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 32, E'Then Jesus said unto them, Verily, verily, I say unto you, Moses gave you not that bread from heaven; but my Father giveth you the true bread from heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 33, E'For the bread of God is he which cometh down from heaven, and giveth life unto the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 34, E'Then said they unto him, Lord, evermore give us this bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 35, E'And Jesus said unto them, I am the bread of life: he that cometh to me shall never hunger; and he that believeth on me shall never thirst.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 36, E'But I said unto you, That ye also have seen me, and believe not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 37, E'All that the Father giveth me shall come to me; and him that cometh to me I will in no wise cast out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 38, E'For I came down from heaven, not to do mine own will, but the will of him that sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 39, E'And this is the Father’s will which hath sent me, that of all which he hath given me I should lose nothing, but should raise it up again at the last day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 40, E'And this is the will of him that sent me, that every one which seeth the Son, and believeth on him, may have everlasting life: and I will raise him up at the last day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 41, E'The Jews then murmured at him, because he said, I am the bread which came down from heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 42, E'And they said, Is not this Jesus, the son of Joseph, whose father and mother we know? how is it then that he saith, I came down from heaven?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 43, E'Jesus therefore answered and said unto them, Murmur not among yourselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 44, E'No man can come to me, except the Father which hath sent me draw him: and I will raise him up at the last day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 45, E'It is written in the prophets, And they shall be all taught of God. Every man therefore that hath heard, and hath learned of the Father, cometh unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 46, E'Not that any man hath seen the Father, save he which is of God, he hath seen the Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 47, E'Verily, verily, I say unto you, He that believeth on me hath everlasting life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 48, E'I am that bread of life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 49, E'Your fathers did eat manna in the wilderness, and are dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 50, E'This is the bread which cometh down from heaven, that a man may eat thereof, and not die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 51, E'I am the living bread which came down from heaven: if any man eat of this bread, he shall live for ever: and the bread that I will give is my flesh, which I will give for the life of the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 52, E'The Jews therefore strove among themselves, saying, How can this man give us his flesh to eat?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 53, E'Then Jesus said unto them, Verily, verily, I say unto you, Except ye eat the flesh of the Son of man, and drink his blood, ye have no life in you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 54, E'Whoso eateth my flesh, and drinketh my blood, hath eternal life; and I will raise him up at the last day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 55, E'For my flesh is meat indeed, and my blood is drink indeed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 56, E'He that eateth my flesh, and drinketh my blood, dwelleth in me, and I in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 57, E'As the living Father hath sent me, and I live by the Father: so he that eateth me, even he shall live by me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 58, E'This is that bread which came down from heaven: not as your fathers did eat manna, and are dead: he that eateth of this bread shall live for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 59, E'These things said he in the synagogue, as he taught in Capernaum.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 60, E'Many therefore of his disciples, when they had heard this, said, This is an hard saying; who can hear it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 61, E'When Jesus knew in himself that his disciples murmured at it, he said unto them, Doth this offend you?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 62, E'What and if ye shall see the Son of man ascend up where he was before?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 63, E'It is the spirit that quickeneth; the flesh profiteth nothing: the words that I speak unto you, they are spirit, and they are life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 64, E'But there are some of you that believe not. For Jesus knew from the beginning who they were that believed not, and who should betray him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 65, E'And he said, Therefore said I unto you, that no man can come unto me, except it were given unto him of my Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 66, E'From that time many of his disciples went back, and walked no more with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 67, E'Then said Jesus unto the twelve, Will ye also go away?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 68, E'Then Simon Peter answered him, Lord, to whom shall we go? thou hast the words of eternal life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 69, E'And we believe and are sure that thou art that Christ, the Son of the living God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 70, E'Jesus answered them, Have not I chosen you twelve, and one of you is a devil?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 6, 71, E'He spake of Judas Iscariot the son of Simon: for he it was that should betray him, being one of the twelve.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 1, E'After these things Jesus walked in Galilee: for he would not walk in Jewry, because the Jews sought to kill him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 2, E'Now the Jews’ feast of tabernacles was at hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 3, E'His brethren therefore said unto him, Depart hence, and go into Judaea, that thy disciples also may see the works that thou doest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 4, E'For there is no man that doeth any thing in secret, and he himself seeketh to be known openly. If thou do these things, shew thyself to the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 5, E'For neither did his brethren believe in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 6, E'Then Jesus said unto them, My time is not yet come: but your time is alway ready.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 7, E'The world cannot hate you; but me it hateth, because I testify of it, that the works thereof are evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 8, E'Go ye up unto this feast: I go not up yet unto this feast: for my time is not yet full come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 9, E'When he had said these words unto them, he abode still in Galilee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 10, E'But when his brethren were gone up, then went he also up unto the feast, not openly, but as it were in secret.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 11, E'Then the Jews sought him at the feast, and said, Where is he?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 12, E'And there was much murmuring among the people concerning him: for some said, He is a good man: others said, Nay; but he deceiveth the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 13, E'Howbeit no man spake openly of him for fear of the Jews.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 14, E'Now about the midst of the feast Jesus went up into the temple, and taught.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 15, E'And the Jews marvelled, saying, How knoweth this man letters, having never learned?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 16, E'Jesus answered them, and said, My doctrine is not mine, but his that sent me.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'John') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 17, E'If any man will do his will, he shall know of the doctrine, whether it be of God, or whether I speak of myself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 18, E'He that speaketh of himself seeketh his own glory: but he that seeketh his glory that sent him, the same is true, and no unrighteousness is in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 19, E'Did not Moses give you the law, and yet none of you keepeth the law? Why go ye about to kill me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 20, E'The people answered and said, Thou hast a devil: who goeth about to kill thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 21, E'Jesus answered and said unto them, I have done one work, and ye all marvel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 22, E'Moses therefore gave unto you circumcision; (not because it is of Moses, but of the fathers;) and ye on the sabbath day circumcise a man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 23, E'If a man on the sabbath day receive circumcision, that the law of Moses should not be broken; are ye angry at me, because I have made a man every whit whole on the sabbath day?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 24, E'Judge not according to the appearance, but judge righteous judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 25, E'Then said some of them of Jerusalem, Is not this he, whom they seek to kill?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 26, E'But, lo, he speaketh boldly, and they say nothing unto him. Do the rulers know indeed that this is the very Christ?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 27, E'Howbeit we know this man whence he is: but when Christ cometh, no man knoweth whence he is.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 28, E'Then cried Jesus in the temple as he taught, saying, Ye both know me, and ye know whence I am: and I am not come of myself, but he that sent me is true, whom ye know not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 29, E'But I know him: for I am from him, and he hath sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 30, E'Then they sought to take him: but no man laid hands on him, because his hour was not yet come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 31, E'And many of the people believed on him, and said, When Christ cometh, will he do more miracles than these which this man hath done?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 32, E'The Pharisees heard that the people murmured such things concerning him; and the Pharisees and the chief priests sent officers to take him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 33, E'Then said Jesus unto them, Yet a little while am I with you, and then I go unto him that sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 34, E'Ye shall seek me, and shall not find me: and where I am, thither ye cannot come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 35, E'Then said the Jews among themselves, Whither will he go, that we shall not find him? will he go unto the dispersed among the Gentiles, and teach the Gentiles?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 36, E'What manner of saying is this that he said, Ye shall seek me, and shall not find me: and where I am, thither ye cannot come?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 37, E'In the last day, that great day of the feast, Jesus stood and cried, saying, If any man thirst, let him come unto me, and drink.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 38, E'He that believeth on me, as the scripture hath said, out of his belly shall flow rivers of living water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 39, E'(But this spake he of the Spirit, which they that believe on him should receive: for the Holy Ghost was not yet given; because that Jesus was not yet glorified.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 40, E'Many of the people therefore, when they heard this saying, said, Of a truth this is the Prophet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 41, E'Others said, This is the Christ. But some said, Shall Christ come out of Galilee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 42, E'Hath not the scripture said, That Christ cometh of the seed of David, and out of the town of Bethlehem, where David was?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 43, E'So there was a division among the people because of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 44, E'And some of them would have taken him; but no man laid hands on him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 45, E'Then came the officers to the chief priests and Pharisees; and they said unto them, Why have ye not brought him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 46, E'The officers answered, Never man spake like this man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 47, E'Then answered them the Pharisees, Are ye also deceived?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 48, E'Have any of the rulers or of the Pharisees believed on him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 49, E'But this people who knoweth not the law are cursed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 50, E'Nicodemus saith unto them, (he that came to Jesus by night, being one of them,)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 51, E'Doth our law judge any man, before it hear him, and know what he doeth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 52, E'They answered and said unto him, Art thou also of Galilee? Search, and look: for out of Galilee ariseth no prophet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 7, 53, E'And every man went unto his own house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 1, E'Jesus went unto the mount of Olives.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 2, E'And early in the morning he came again into the temple, and all the people came unto him; and he sat down, and taught them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 3, E'And the scribes and Pharisees brought unto him a woman taken in adultery; and when they had set her in the midst,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 4, E'They say unto him, Master, this woman was taken in adultery, in the very act.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 5, E'Now Moses in the law commanded us, that such should be stoned: but what sayest thou?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 6, E'This they said, tempting him, that they might have to accuse him. But Jesus stooped down, and with his finger wrote on the ground, as though he heard them not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 7, E'So when they continued asking him, he lifted up himself, and said unto them, He that is without sin among you, let him first cast a stone at her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 8, E'And again he stooped down, and wrote on the ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 9, E'And they which heard it, being convicted by their own conscience, went out one by one, beginning at the eldest, even unto the last: and Jesus was left alone, and the woman standing in the midst.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 10, E'When Jesus had lifted up himself, and saw none but the woman, he said unto her, Woman, where are those thine accusers? hath no man condemned thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 11, E'She said, No man, Lord. And Jesus said unto her, Neither do I condemn thee: go, and sin no more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 12, E'Then spake Jesus again unto them, saying, I am the light of the world: he that followeth me shall not walk in darkness, but shall have the light of life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 13, E'The Pharisees therefore said unto him, Thou bearest record of thyself; thy record is not true.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 14, E'Jesus answered and said unto them, Though I bear record of myself, yet my record is true: for I know whence I came, and whither I go; but ye cannot tell whence I come, and whither I go.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 15, E'Ye judge after the flesh; I judge no man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 16, E'And yet if I judge, my judgment is true: for I am not alone, but I and the Father that sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 17, E'It is also written in your law, that the testimony of two men is true.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 18, E'I am one that bear witness of myself, and the Father that sent me beareth witness of me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 19, E'Then said they unto him, Where is thy Father? Jesus answered, Ye neither know me, nor my Father: if ye had known me, ye should have known my Father also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 20, E'These words spake Jesus in the treasury, as he taught in the temple: and no man laid hands on him; for his hour was not yet come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 21, E'Then said Jesus again unto them, I go my way, and ye shall seek me, and shall die in your sins: whither I go, ye cannot come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 22, E'Then said the Jews, Will he kill himself? because he saith, Whither I go, ye cannot come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 23, E'And he said unto them, Ye are from beneath; I am from above: ye are of this world; I am not of this world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 24, E'I said therefore unto you, that ye shall die in your sins: for if ye believe not that I am he, ye shall die in your sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 25, E'Then said they unto him, Who art thou? And Jesus saith unto them, Even the same that I said unto you from the beginning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 26, E'I have many things to say and to judge of you: but he that sent me is true; and I speak to the world those things which I have heard of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 27, E'They understood not that he spake to them of the Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 28, E'Then said Jesus unto them, When ye have lifted up the Son of man, then shall ye know that I am he, and that I do nothing of myself; but as my Father hath taught me, I speak these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 29, E'And he that sent me is with me: the Father hath not left me alone; for I do always those things that please him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 30, E'As he spake these words, many believed on him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 31, E'Then said Jesus to those Jews which believed on him, If ye continue in my word, then are ye my disciples indeed;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 32, E'And ye shall know the truth, and the truth shall make you free.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 33, E'They answered him, We be Abraham’s seed, and were never in bondage to any man: how sayest thou, Ye shall be made free?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 34, E'Jesus answered them, Verily, verily, I say unto you, Whosoever committeth sin is the servant of sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 35, E'And the servant abideth not in the house for ever: but the Son abideth ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 36, E'If the Son therefore shall make you free, ye shall be free indeed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 37, E'I know that ye are Abraham’s seed; but ye seek to kill me, because my word hath no place in you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 38, E'I speak that which I have seen with my Father: and ye do that which ye have seen with your father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 39, E'They answered and said unto him, Abraham is our father. Jesus saith unto them, If ye were Abraham’s children, ye would do the works of Abraham.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 40, E'But now ye seek to kill me, a man that hath told you the truth, which I have heard of God: this did not Abraham.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 41, E'Ye do the deeds of your father. Then said they to him, We be not born of fornication; we have one Father, even God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 42, E'Jesus said unto them, If God were your Father, ye would love me: for I proceeded forth and came from God; neither came I of myself, but he sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 43, E'Why do ye not understand my speech? even because ye cannot hear my word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 44, E'Ye are of your father the devil, and the lusts of your father ye will do. He was a murderer from the beginning, and abode not in the truth, because there is no truth in him. When he speaketh a lie, he speaketh of his own: for he is a liar, and the father of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 45, E'And because I tell you the truth, ye believe me not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 46, E'Which of you convinceth me of sin? And if I say the truth, why do ye not believe me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 47, E'He that is of God heareth God’s words: ye therefore hear them not, because ye are not of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 48, E'Then answered the Jews, and said unto him, Say we not well that thou art a Samaritan, and hast a devil?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 49, E'Jesus answered, I have not a devil; but I honour my Father, and ye do dishonour me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 50, E'And I seek not mine own glory: there is one that seeketh and judgeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 51, E'Verily, verily, I say unto you, If a man keep my saying, he shall never see death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 52, E'Then said the Jews unto him, Now we know that thou hast a devil. Abraham is dead, and the prophets; and thou sayest, If a man keep my saying, he shall never taste of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 53, E'Art thou greater than our father Abraham, which is dead? and the prophets are dead: whom makest thou thyself?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 54, E'Jesus answered, If I honour myself, my honour is nothing: it is my Father that honoureth me; of whom ye say, that he is your God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 55, E'Yet ye have not known him; but I know him: and if I should say, I know him not, I shall be a liar like unto you: but I know him, and keep his saying.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 56, E'Your father Abraham rejoiced to see my day: and he saw it, and was glad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 57, E'Then said the Jews unto him, Thou art not yet fifty years old, and hast thou seen Abraham?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 58, E'Jesus said unto them, Verily, verily, I say unto you, Before Abraham was, I am.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 8, 59, E'Then took they up stones to cast at him: but Jesus hid himself, and went out of the temple, going through the midst of them, and so passed by.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 1, E'And as Jesus passed by, he saw a man which was blind from his birth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 2, E'And his disciples asked him, saying, Master, who did sin, this man, or his parents, that he was born blind?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 3, E'Jesus answered, Neither hath this man sinned, nor his parents: but that the works of God should be made manifest in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 4, E'I must work the works of him that sent me, while it is day: the night cometh, when no man can work.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'John') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 5, E'As long as I am in the world, I am the light of the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 6, E'When he had thus spoken, he spat on the ground, and made clay of the spittle, and he anointed the eyes of the blind man with the clay,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 7, E'And said unto him, Go, wash in the pool of Siloam, (which is by interpretation, Sent.) He went his way therefore, and washed, and came seeing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 8, E'The neighbours therefore, and they which before had seen him that he was blind, said, Is not this he that sat and begged?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 9, E'Some said, This is he: others said, He is like him: but he said, I am he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 10, E'Therefore said they unto him, How were thine eyes opened?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 11, E'He answered and said, A man that is called Jesus made clay, and anointed mine eyes, and said unto me, Go to the pool of Siloam, and wash: and I went and washed, and I received sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 12, E'Then said they unto him, Where is he? He said, I know not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 13, E'They brought to the Pharisees him that aforetime was blind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 14, E'And it was the sabbath day when Jesus made the clay, and opened his eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 15, E'Then again the Pharisees also asked him how he had received his sight. He said unto them, He put clay upon mine eyes, and I washed, and do see.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 16, E'Therefore said some of the Pharisees, This man is not of God, because he keepeth not the sabbath day. Others said, How can a man that is a sinner do such miracles? And there was a division among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 17, E'They say unto the blind man again, What sayest thou of him, that he hath opened thine eyes? He said, He is a prophet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 18, E'But the Jews did not believe concerning him, that he had been blind, and received his sight, until they called the parents of him that had received his sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 19, E'And they asked them, saying, Is this your son, who ye say was born blind? how then doth he now see?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 20, E'His parents answered them and said, We know that this is our son, and that he was born blind:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 21, E'But by what means he now seeth, we know not; or who hath opened his eyes, we know not: he is of age; ask him: he shall speak for himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 22, E'These words spake his parents, because they feared the Jews: for the Jews had agreed already, that if any man did confess that he was Christ, he should be put out of the synagogue.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 23, E'Therefore said his parents, He is of age; ask him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 24, E'Then again called they the man that was blind, and said unto him, Give God the praise: we know that this man is a sinner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 25, E'He answered and said, Whether he be a sinner or no, I know not: one thing I know, that, whereas I was blind, now I see.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 26, E'Then said they to him again, What did he to thee? how opened he thine eyes?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 27, E'He answered them, I have told you already, and ye did not hear: wherefore would ye hear it again? will ye also be his disciples?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 28, E'Then they reviled him, and said, Thou art his disciple; but we are Moses’ disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 29, E'We know that God spake unto Moses: as for this fellow, we know not from whence he is.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 30, E'The man answered and said unto them, Why herein is a marvellous thing, that ye know not from whence he is, and yet he hath opened mine eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 31, E'Now we know that God heareth not sinners: but if any man be a worshipper of God, and doeth his will, him he heareth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 32, E'Since the world began was it not heard that any man opened the eyes of one that was born blind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 33, E'If this man were not of God, he could do nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 34, E'They answered and said unto him, Thou wast altogether born in sins, and dost thou teach us? And they cast him out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 35, E'Jesus heard that they had cast him out; and when he had found him, he said unto him, Dost thou believe on the Son of God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 36, E'He answered and said, Who is he, Lord, that I might believe on him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 37, E'And Jesus said unto him, Thou hast both seen him, and it is he that talketh with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 38, E'And he said, Lord, I believe. And he worshipped him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 39, E'And Jesus said, For judgment I am come into this world, that they which see not might see; and that they which see might be made blind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 40, E'And some of the Pharisees which were with him heard these words, and said unto him, Are we blind also?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 9, 41, E'Jesus said unto them, If ye were blind, ye should have no sin: but now ye say, We see; therefore your sin remaineth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 1, E'Verily, verily, I say unto you, He that entereth not by the door into the sheepfold, but climbeth up some other way, the same is a thief and a robber.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 2, E'But he that entereth in by the door is the shepherd of the sheep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 3, E'To him the porter openeth; and the sheep hear his voice: and he calleth his own sheep by name, and leadeth them out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 4, E'And when he putteth forth his own sheep, he goeth before them, and the sheep follow him: for they know his voice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 5, E'And a stranger will they not follow, but will flee from him: for they know not the voice of strangers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 6, E'This parable spake Jesus unto them: but they understood not what things they were which he spake unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 7, E'Then said Jesus unto them again, Verily, verily, I say unto you, I am the door of the sheep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 8, E'All that ever came before me are thieves and robbers: but the sheep did not hear them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 9, E'I am the door: by me if any man enter in, he shall be saved, and shall go in and out, and find pasture.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 10, E'The thief cometh not, but for to steal, and to kill, and to destroy: I am come that they might have life, and that they might have it more abundantly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 11, E'I am the good shepherd: the good shepherd giveth his life for the sheep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 12, E'But he that is an hireling, and not the shepherd, whose own the sheep are not, seeth the wolf coming, and leaveth the sheep, and fleeth: and the wolf catcheth them, and scattereth the sheep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 13, E'The hireling fleeth, because he is an hireling, and careth not for the sheep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 14, E'I am the good shepherd, and know my sheep, and am known of mine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 15, E'As the Father knoweth me, even so know I the Father: and I lay down my life for the sheep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 16, E'And other sheep I have, which are not of this fold: them also I must bring, and they shall hear my voice; and there shall be one fold, and one shepherd.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 17, E'Therefore doth my Father love me, because I lay down my life, that I might take it again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 18, E'No man taketh it from me, but I lay it down of myself. I have power to lay it down, and I have power to take it again. This commandment have I received of my Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 19, E'There was a division therefore again among the Jews for these sayings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 20, E'And many of them said, He hath a devil, and is mad; why hear ye him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 21, E'Others said, These are not the words of him that hath a devil. Can a devil open the eyes of the blind?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 22, E'And it was at Jerusalem the feast of the dedication, and it was winter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 23, E'And Jesus walked in the temple in Solomon’s porch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 24, E'Then came the Jews round about him, and said unto him, How long dost thou make us to doubt? If thou be the Christ, tell us plainly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 25, E'Jesus answered them, I told you, and ye believed not: the works that I do in my Father’s name, they bear witness of me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 26, E'But ye believe not, because ye are not of my sheep, as I said unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 27, E'My sheep hear my voice, and I know them, and they follow me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 28, E'And I give unto them eternal life; and they shall never perish, neither shall any man pluck them out of my hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 29, E'My Father, which gave them me, is greater than all; and no man is able to pluck them out of my Father’s hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 30, E'I and my Father are one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 31, E'Then the Jews took up stones again to stone him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 32, E'Jesus answered them, Many good works have I shewed you from my Father; for which of those works do ye stone me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 33, E'The Jews answered him, saying, For a good work we stone thee not; but for blasphemy; and because that thou, being a man, makest thyself God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 34, E'Jesus answered them, Is it not written in your law, I said, Ye are gods?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 35, E'If he called them gods, unto whom the word of God came, and the scripture cannot be broken;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 36, E'Say ye of him, whom the Father hath sanctified, and sent into the world, Thou blasphemest; because I said, I am the Son of God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 37, E'If I do not the works of my Father, believe me not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 38, E'But if I do, though ye believe not me, believe the works: that ye may know, and believe, that the Father is in me, and I in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 39, E'Therefore they sought again to take him: but he escaped out of their hand,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 40, E'And went away again beyond Jordan into the place where John at first baptized; and there he abode.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 41, E'And many resorted unto him, and said, John did no miracle: but all things that John spake of this man were true.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 10, 42, E'And many believed on him there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 1, E'Now a certain man was sick, named Lazarus, of Bethany, the town of Mary and her sister Martha.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 2, E'(It was that Mary which anointed the Lord with ointment, and wiped his feet with her hair, whose brother Lazarus was sick.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 3, E'Therefore his sisters sent unto him, saying, Lord, behold, he whom thou lovest is sick.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 4, E'When Jesus heard that, he said, This sickness is not unto death, but for the glory of God, that the Son of God might be glorified thereby.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 5, E'Now Jesus loved Martha, and her sister, and Lazarus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 6, E'When he had heard therefore that he was sick, he abode two days still in the same place where he was.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 7, E'Then after that saith he to his disciples, Let us go into Judaea again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 8, E'His disciples say unto him, Master, the Jews of late sought to stone thee; and goest thou thither again?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 9, E'Jesus answered, Are there not twelve hours in the day? If any man walk in the day, he stumbleth not, because he seeth the light of this world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 10, E'But if a man walk in the night, he stumbleth, because there is no light in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 11, E'These things said he: and after that he saith unto them, Our friend Lazarus sleepeth; but I go, that I may awake him out of sleep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 12, E'Then said his disciples, Lord, if he sleep, he shall do well.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 13, E'Howbeit Jesus spake of his death: but they thought that he had spoken of taking of rest in sleep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 14, E'Then said Jesus unto them plainly, Lazarus is dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 15, E'And I am glad for your sakes that I was not there, to the intent ye may believe; nevertheless let us go unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 16, E'Then said Thomas, which is called Didymus, unto his fellowdisciples, Let us also go, that we may die with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 17, E'Then when Jesus came, he found that he had lain in the grave four days already.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 18, E'Now Bethany was nigh unto Jerusalem, about fifteen furlongs off:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 19, E'And many of the Jews came to Martha and Mary, to comfort them concerning their brother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 20, E'Then Martha, as soon as she heard that Jesus was coming, went and met him: but Mary sat still in the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 21, E'Then said Martha unto Jesus, Lord, if thou hadst been here, my brother had not died.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'John') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 22, E'But I know, that even now, whatsoever thou wilt ask of God, God will give it thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 23, E'Jesus saith unto her, Thy brother shall rise again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 24, E'Martha saith unto him, I know that he shall rise again in the resurrection at the last day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 25, E'Jesus said unto her, I am the resurrection, and the life: he that believeth in me, though he were dead, yet shall he live:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 26, E'And whosoever liveth and believeth in me shall never die. Believest thou this?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 27, E'She saith unto him, Yea, Lord: I believe that thou art the Christ, the Son of God, which should come into the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 28, E'And when she had so said, she went her way, and called Mary her sister secretly, saying, The Master is come, and calleth for thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 29, E'As soon as she heard that, she arose quickly, and came unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 30, E'Now Jesus was not yet come into the town, but was in that place where Martha met him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 31, E'The Jews then which were with her in the house, and comforted her, when they saw Mary, that she rose up hastily and went out, followed her, saying, She goeth unto the grave to weep there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 32, E'Then when Mary was come where Jesus was, and saw him, she fell down at his feet, saying unto him, Lord, if thou hadst been here, my brother had not died.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 33, E'When Jesus therefore saw her weeping, and the Jews also weeping which came with her, he groaned in the spirit, and was troubled,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 34, E'And said, Where have ye laid him? They said unto him, Lord, come and see.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 35, E'Jesus wept.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 36, E'Then said the Jews, Behold how he loved him!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 37, E'And some of them said, Could not this man, which opened the eyes of the blind, have caused that even this man should not have died?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 38, E'Jesus therefore again groaning in himself cometh to the grave. It was a cave, and a stone lay upon it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 39, E'Jesus said, Take ye away the stone. Martha, the sister of him that was dead, saith unto him, Lord, by this time he stinketh: for he hath been dead four days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 40, E'Jesus saith unto her, Said I not unto thee, that, if thou wouldest believe, thou shouldest see the glory of God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 41, E'Then they took away the stone from the place where the dead was laid. And Jesus lifted up his eyes, and said, Father, I thank thee that thou hast heard me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 42, E'And I knew that thou hearest me always: but because of the people which stand by I said it, that they may believe that thou hast sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 43, E'And when he thus had spoken, he cried with a loud voice, Lazarus, come forth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 44, E'And he that was dead came forth, bound hand and foot with graveclothes: and his face was bound about with a napkin. Jesus saith unto them, Loose him, and let him go.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 45, E'Then many of the Jews which came to Mary, and had seen the things which Jesus did, believed on him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 46, E'But some of them went their ways to the Pharisees, and told them what things Jesus had done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 47, E'Then gathered the chief priests and the Pharisees a council, and said, What do we? for this man doeth many miracles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 48, E'If we let him thus alone, all men will believe on him: and the Romans shall come and take away both our place and nation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 49, E'And one of them, named Caiaphas, being the high priest that same year, said unto them, Ye know nothing at all,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 50, E'Nor consider that it is expedient for us, that one man should die for the people, and that the whole nation perish not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 51, E'And this spake he not of himself: but being high priest that year, he prophesied that Jesus should die for that nation;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 52, E'And not for that nation only, but that also he should gather together in one the children of God that were scattered abroad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 53, E'Then from that day forth they took counsel together for to put him to death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 54, E'Jesus therefore walked no more openly among the Jews; but went thence unto a country near to the wilderness, into a city called Ephraim, and there continued with his disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 55, E'And the Jews’ passover was nigh at hand: and many went out of the country up to Jerusalem before the passover, to purify themselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 56, E'Then sought they for Jesus, and spake among themselves, as they stood in the temple, What think ye, that he will not come to the feast?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 11, 57, E'Now both the chief priests and the Pharisees had given a commandment, that, if any man knew where he were, he should shew it, that they might take him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 1, E'Then Jesus six days before the passover came to Bethany, where Lazarus was, which had been dead, whom he raised from the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 2, E'There they made him a supper; and Martha served: but Lazarus was one of them that sat at the table with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 3, E'Then took Mary a pound of ointment of spikenard, very costly, and anointed the feet of Jesus, and wiped his feet with her hair: and the house was filled with the odour of the ointment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 4, E'Then saith one of his disciples, Judas Iscariot, Simon’s son, which should betray him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 5, E'Why was not this ointment sold for three hundred pence, and given to the poor?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 6, E'This he said, not that he cared for the poor; but because he was a thief, and had the bag, and bare what was put therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 7, E'Then said Jesus, Let her alone: against the day of my burying hath she kept this.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 8, E'For the poor always ye have with you; but me ye have not always.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 9, E'Much people of the Jews therefore knew that he was there: and they came not for Jesus’ sake only, but that they might see Lazarus also, whom he had raised from the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 10, E'But the chief priests consulted that they might put Lazarus also to death;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 11, E'Because that by reason of him many of the Jews went away, and believed on Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 12, E'On the next day much people that were come to the feast, when they heard that Jesus was coming to Jerusalem,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 13, E'Took branches of palm trees, and went forth to meet him, and cried, Hosanna: Blessed is the King of Israel that cometh in the name of the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 14, E'And Jesus, when he had found a young ass, sat thereon; as it is written,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 15, E'Fear not, daughter of Sion: behold, thy King cometh, sitting on an ass’s colt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 16, E'These things understood not his disciples at the first: but when Jesus was glorified, then remembered they that these things were written of him, and that they had done these things unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 17, E'The people therefore that was with him when he called Lazarus out of his grave, and raised him from the dead, bare record.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 18, E'For this cause the people also met him, for that they heard that he had done this miracle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 19, E'The Pharisees therefore said among themselves, Perceive ye how ye prevail nothing? behold, the world is gone after him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 20, E'And there were certain Greeks among them that came up to worship at the feast:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 21, E'The same came therefore to Philip, which was of Bethsaida of Galilee, and desired him, saying, Sir, we would see Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 22, E'Philip cometh and telleth Andrew: and again Andrew and Philip tell Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 23, E'And Jesus answered them, saying, The hour is come, that the Son of man should be glorified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 24, E'Verily, verily, I say unto you, Except a corn of wheat fall into the ground and die, it abideth alone: but if it die, it bringeth forth much fruit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 25, E'He that loveth his life shall lose it; and he that hateth his life in this world shall keep it unto life eternal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 26, E'If any man serve me, let him follow me; and where I am, there shall also my servant be: if any man serve me, him will my Father honour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 27, E'Now is my soul troubled; and what shall I say? Father, save me from this hour: but for this cause came I unto this hour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 28, E'Father, glorify thy name. Then came there a voice from heaven, saying, I have both glorified it, and will glorify it again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 29, E'The people therefore, that stood by, and heard it, said that it thundered: others said, An angel spake to him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 30, E'Jesus answered and said, This voice came not because of me, but for your sakes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 31, E'Now is the judgment of this world: now shall the prince of this world be cast out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 32, E'And I, if I be lifted up from the earth, will draw all men unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 33, E'This he said, signifying what death he should die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 34, E'The people answered him, We have heard out of the law that Christ abideth for ever: and how sayest thou, The Son of man must be lifted up? who is this Son of man?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 35, E'Then Jesus said unto them, Yet a little while is the light with you. Walk while ye have the light, lest darkness come upon you: for he that walketh in darkness knoweth not whither he goeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 36, E'While ye have light, believe in the light, that ye may be the children of light. These things spake Jesus, and departed, and did hide himself from them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 37, E'But though he had done so many miracles before them, yet they believed not on him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 38, E'That the saying of Esaias the prophet might be fulfilled, which he spake, Lord, who hath believed our report? and to whom hath the arm of the Lord been revealed?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 39, E'Therefore they could not believe, because that Esaias said again,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 40, E'He hath blinded their eyes, and hardened their heart; that they should not see with their eyes, nor understand with their heart, and be converted, and I should heal them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 41, E'These things said Esaias, when he saw his glory, and spake of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 42, E'Nevertheless among the chief rulers also many believed on him; but because of the Pharisees they did not confess him, lest they should be put out of the synagogue:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 43, E'For they loved the praise of men more than the praise of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 44, E'Jesus cried and said, He that believeth on me, believeth not on me, but on him that sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 45, E'And he that seeth me seeth him that sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 46, E'I am come a light into the world, that whosoever believeth on me should not abide in darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 47, E'And if any man hear my words, and believe not, I judge him not: for I came not to judge the world, but to save the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 48, E'He that rejecteth me, and receiveth not my words, hath one that judgeth him: the word that I have spoken, the same shall judge him in the last day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 49, E'For I have not spoken of myself; but the Father which sent me, he gave me a commandment, what I should say, and what I should speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 12, 50, E'And I know that his commandment is life everlasting: whatsoever I speak therefore, even as the Father said unto me, so I speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 1, E'Now before the feast of the passover, when Jesus knew that his hour was come that he should depart out of this world unto the Father, having loved his own which were in the world, he loved them unto the end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 2, E'And supper being ended, the devil having now put into the heart of Judas Iscariot, Simon’s son, to betray him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 3, E'Jesus knowing that the Father had given all things into his hands, and that he was come from God, and went to God;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 4, E'He riseth from supper, and laid aside his garments; and took a towel, and girded himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 5, E'After that he poureth water into a bason, and began to wash the disciples’ feet, and to wipe them with the towel wherewith he was girded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 6, E'Then cometh he to Simon Peter: and Peter saith unto him, Lord, dost thou wash my feet?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 7, E'Jesus answered and said unto him, What I do thou knowest not now; but thou shalt know hereafter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 8, E'Peter saith unto him, Thou shalt never wash my feet. Jesus answered him, If I wash thee not, thou hast no part with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 9, E'Simon Peter saith unto him, Lord, not my feet only, but also my hands and my head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 10, E'Jesus saith to him, He that is washed needeth not save to wash his feet, but is clean every whit: and ye are clean, but not all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 11, E'For he knew who should betray him; therefore said he, Ye are not all clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 12, E'So after he had washed their feet, and had taken his garments, and was set down again, he said unto them, Know ye what I have done to you?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 13, E'Ye call me Master and Lord: and ye say well; for so I am.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 14, E'If I then, your Lord and Master, have washed your feet; ye also ought to wash one another’s feet.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'John') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 15, E'For I have given you an example, that ye should do as I have done to you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 16, E'Verily, verily, I say unto you, The servant is not greater than his lord; neither he that is sent greater than he that sent him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 17, E'If ye know these things, happy are ye if ye do them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 18, E'I speak not of you all: I know whom I have chosen: but that the scripture may be fulfilled, He that eateth bread with me hath lifted up his heel against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 19, E'Now I tell you before it come, that, when it is come to pass, ye may believe that I am he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 20, E'Verily, verily, I say unto you, He that receiveth whomsoever I send receiveth me; and he that receiveth me receiveth him that sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 21, E'When Jesus had thus said, he was troubled in spirit, and testified, and said, Verily, verily, I say unto you, that one of you shall betray me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 22, E'Then the disciples looked one on another, doubting of whom he spake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 23, E'Now there was leaning on Jesus’ bosom one of his disciples, whom Jesus loved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 24, E'Simon Peter therefore beckoned to him, that he should ask who it should be of whom he spake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 25, E'He then lying on Jesus’ breast saith unto him, Lord, who is it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 26, E'Jesus answered, He it is, to whom I shall give a sop, when I have dipped it. And when he had dipped the sop, he gave it to Judas Iscariot, the son of Simon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 27, E'And after the sop Satan entered into him. Then said Jesus unto him, That thou doest, do quickly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 28, E'Now no man at the table knew for what intent he spake this unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 29, E'For some of them thought, because Judas had the bag, that Jesus had said unto him, Buy those things that we have need of against the feast; or, that he should give something to the poor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 30, E'He then having received the sop went immediately out: and it was night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 31, E'Therefore, when he was gone out, Jesus said, Now is the Son of man glorified, and God is glorified in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 32, E'If God be glorified in him, God shall also glorify him in himself, and shall straightway glorify him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 33, E'Little children, yet a little while I am with you. Ye shall seek me: and as I said unto the Jews, Whither I go, ye cannot come; so now I say to you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 34, E'A new commandment I give unto you, That ye love one another; as I have loved you, that ye also love one another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 35, E'By this shall all men know that ye are my disciples, if ye have love one to another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 36, E'Simon Peter said unto him, Lord, whither goest thou? Jesus answered him, Whither I go, thou canst not follow me now; but thou shalt follow me afterwards.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 37, E'Peter said unto him, Lord, why cannot I follow thee now? I will lay down my life for thy sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 13, 38, E'Jesus answered him, Wilt thou lay down thy life for my sake? Verily, verily, I say unto thee, The cock shall not crow, till thou hast denied me thrice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 1, E'Let not your heart be troubled: ye believe in God, believe also in me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 2, E'In my Father’s house are many mansions: if it were not so, I would have told you. I go to prepare a place for you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 3, E'And if I go and prepare a place for you, I will come again, and receive you unto myself; that where I am, there ye may be also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 4, E'And whither I go ye know, and the way ye know.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 5, E'Thomas saith unto him, Lord, we know not whither thou goest; and how can we know the way?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 6, E'Jesus saith unto him, I am the way, the truth, and the life: no man cometh unto the Father, but by me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 7, E'If ye had known me, ye should have known my Father also: and from henceforth ye know him, and have seen him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 8, E'Philip saith unto him, Lord, shew us the Father, and it sufficeth us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 9, E'Jesus saith unto him, Have I been so long time with you, and yet hast thou not known me, Philip? he that hath seen me hath seen the Father; and how sayest thou then, Shew us the Father?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 10, E'Believest thou not that I am in the Father, and the Father in me? the words that I speak unto you I speak not of myself: but the Father that dwelleth in me, he doeth the works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 11, E'Believe me that I am in the Father, and the Father in me: or else believe me for the very works’ sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 12, E'Verily, verily, I say unto you, He that believeth on me, the works that I do shall he do also; and greater works than these shall he do; because I go unto my Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 13, E'And whatsoever ye shall ask in my name, that will I do, that the Father may be glorified in the Son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 14, E'If ye shall ask any thing in my name, I will do it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 15, E'If ye love me, keep my commandments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 16, E'And I will pray the Father, and he shall give you another Comforter, that he may abide with you for ever;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 17, E'Even the Spirit of truth; whom the world cannot receive, because it seeth him not, neither knoweth him: but ye know him; for he dwelleth with you, and shall be in you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 18, E'I will not leave you comfortless: I will come to you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 19, E'Yet a little while, and the world seeth me no more; but ye see me: because I live, ye shall live also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 20, E'At that day ye shall know that I am in my Father, and ye in me, and I in you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 21, E'He that hath my commandments, and keepeth them, he it is that loveth me: and he that loveth me shall be loved of my Father, and I will love him, and will manifest myself to him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 22, E'Judas saith unto him, not Iscariot, Lord, how is it that thou wilt manifest thyself unto us, and not unto the world?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 23, E'Jesus answered and said unto him, If a man love me, he will keep my words: and my Father will love him, and we will come unto him, and make our abode with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 24, E'He that loveth me not keepeth not my sayings: and the word which ye hear is not mine, but the Father’s which sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 25, E'These things have I spoken unto you, being yet present with you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 26, E'But the Comforter, which is the Holy Ghost, whom the Father will send in my name, he shall teach you all things, and bring all things to your remembrance, whatsoever I have said unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 27, E'Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 28, E'Ye have heard how I said unto you, I go away, and come again unto you. If ye loved me, ye would rejoice, because I said, I go unto the Father: for my Father is greater than I.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 29, E'And now I have told you before it come to pass, that, when it is come to pass, ye might believe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 30, E'Hereafter I will not talk much with you: for the prince of this world cometh, and hath nothing in me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 14, 31, E'But that the world may know that I love the Father; and as the Father gave me commandment, even so I do. Arise, let us go hence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 1, E'I am the true vine, and my Father is the husbandman.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 2, E'Every branch in me that beareth not fruit he taketh away: and every branch that beareth fruit, he purgeth it, that it may bring forth more fruit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 3, E'Now ye are clean through the word which I have spoken unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 4, E'Abide in me, and I in you. As the branch cannot bear fruit of itself, except it abide in the vine; no more can ye, except ye abide in me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 5, E'I am the vine, ye are the branches: He that abideth in me, and I in him, the same bringeth forth much fruit: for without me ye can do nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 6, E'If a man abide not in me, he is cast forth as a branch, and is withered; and men gather them, and cast them into the fire, and they are burned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 7, E'If ye abide in me, and my words abide in you, ye shall ask what ye will, and it shall be done unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 8, E'Herein is my Father glorified, that ye bear much fruit; so shall ye be my disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 9, E'As the Father hath loved me, so have I loved you: continue ye in my love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 10, E'If ye keep my commandments, ye shall abide in my love; even as I have kept my Father’s commandments, and abide in his love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 11, E'These things have I spoken unto you, that my joy might remain in you, and that your joy might be full.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 12, E'This is my commandment, That ye love one another, as I have loved you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 13, E'Greater love hath no man than this, that a man lay down his life for his friends.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 14, E'Ye are my friends, if ye do whatsoever I command you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 15, E'Henceforth I call you not servants; for the servant knoweth not what his lord doeth: but I have called you friends; for all things that I have heard of my Father I have made known unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 16, E'Ye have not chosen me, but I have chosen you, and ordained you, that ye should go and bring forth fruit, and that your fruit should remain: that whatsoever ye shall ask of the Father in my name, he may give it you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 17, E'These things I command you, that ye love one another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 18, E'If the world hate you, ye know that it hated me before it hated you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 19, E'If ye were of the world, the world would love his own: but because ye are not of the world, but I have chosen you out of the world, therefore the world hateth you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 20, E'Remember the word that I said unto you, The servant is not greater than his lord. If they have persecuted me, they will also persecute you; if they have kept my saying, they will keep yours also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 21, E'But all these things will they do unto you for my name’s sake, because they know not him that sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 22, E'If I had not come and spoken unto them, they had not had sin: but now they have no cloak for their sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 23, E'He that hateth me hateth my Father also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 24, E'If I had not done among them the works which none other man did, they had not had sin: but now have they both seen and hated both me and my Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 25, E'But this cometh to pass, that the word might be fulfilled that is written in their law, They hated me without a cause.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 26, E'But when the Comforter is come, whom I will send unto you from the Father, even the Spirit of truth, which proceedeth from the Father, he shall testify of me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 15, 27, E'And ye also shall bear witness, because ye have been with me from the beginning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 1, E'These things have I spoken unto you, that ye should not be offended.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 2, E'They shall put you out of the synagogues: yea, the time cometh, that whosoever killeth you will think that he doeth God service.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 3, E'And these things will they do unto you, because they have not known the Father, nor me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 4, E'But these things have I told you, that when the time shall come, ye may remember that I told you of them. And these things I said not unto you at the beginning, because I was with you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 5, E'But now I go my way to him that sent me; and none of you asketh me, Whither goest thou?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 6, E'But because I have said these things unto you, sorrow hath filled your heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 7, E'Nevertheless I tell you the truth; It is expedient for you that I go away: for if I go not away, the Comforter will not come unto you; but if I depart, I will send him unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 8, E'And when he is come, he will reprove the world of sin, and of righteousness, and of judgment:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 9, E'Of sin, because they believe not on me;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 10, E'Of righteousness, because I go to my Father, and ye see me no more;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 11, E'Of judgment, because the prince of this world is judged.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 12, E'I have yet many things to say unto you, but ye cannot bear them now.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 13, E'Howbeit when he, the Spirit of truth, is come, he will guide you into all truth: for he shall not speak of himself; but whatsoever he shall hear, that shall he speak: and he will shew you things to come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 14, E'He shall glorify me: for he shall receive of mine, and shall shew it unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 15, E'All things that the Father hath are mine: therefore said I, that he shall take of mine, and shall shew it unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 16, E'A little while, and ye shall not see me: and again, a little while, and ye shall see me, because I go to the Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 17, E'Then said some of his disciples among themselves, What is this that he saith unto us, A little while, and ye shall not see me: and again, a little while, and ye shall see me: and, Because I go to the Father?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 18, E'They said therefore, What is this that he saith, A little while? we cannot tell what he saith.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'John') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 19, E'Now Jesus knew that they were desirous to ask him, and said unto them, Do ye enquire among yourselves of that I said, A little while, and ye shall not see me: and again, a little while, and ye shall see me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 20, E'Verily, verily, I say unto you, That ye shall weep and lament, but the world shall rejoice: and ye shall be sorrowful, but your sorrow shall be turned into joy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 21, E'A woman when she is in travail hath sorrow, because her hour is come: but as soon as she is delivered of the child, she remembereth no more the anguish, for joy that a man is born into the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 22, E'And ye now therefore have sorrow: but I will see you again, and your heart shall rejoice, and your joy no man taketh from you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 23, E'And in that day ye shall ask me nothing. Verily, verily, I say unto you, Whatsoever ye shall ask the Father in my name, he will give it you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 24, E'Hitherto have ye asked nothing in my name: ask, and ye shall receive, that your joy may be full.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 25, E'These things have I spoken unto you in proverbs: but the time cometh, when I shall no more speak unto you in proverbs, but I shall shew you plainly of the Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 26, E'At that day ye shall ask in my name: and I say not unto you, that I will pray the Father for you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 27, E'For the Father himself loveth you, because ye have loved me, and have believed that I came out from God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 28, E'I came forth from the Father, and am come into the world: again, I leave the world, and go to the Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 29, E'His disciples said unto him, Lo, now speakest thou plainly, and speakest no proverb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 30, E'Now are we sure that thou knowest all things, and needest not that any man should ask thee: by this we believe that thou camest forth from God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 31, E'Jesus answered them, Do ye now believe?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 32, E'Behold, the hour cometh, yea, is now come, that ye shall be scattered, every man to his own, and shall leave me alone: and yet I am not alone, because the Father is with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 16, 33, E'These things I have spoken unto you, that in me ye might have peace. In the world ye shall have tribulation: but be of good cheer; I have overcome the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 1, E'These words spake Jesus, and lifted up his eyes to heaven, and said, Father, the hour is come; glorify thy Son, that thy Son also may glorify thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 2, E'As thou hast given him power over all flesh, that he should give eternal life to as many as thou hast given him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 3, E'And this is life eternal, that they might know thee the only true God, and Jesus Christ, whom thou hast sent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 4, E'I have glorified thee on the earth: I have finished the work which thou gavest me to do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 5, E'And now, O Father, glorify thou me with thine own self with the glory which I had with thee before the world was.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 6, E'I have manifested thy name unto the men which thou gavest me out of the world: thine they were, and thou gavest them me; and they have kept thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 7, E'Now they have known that all things whatsoever thou hast given me are of thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 8, E'For I have given unto them the words which thou gavest me; and they have received them, and have known surely that I came out from thee, and they have believed that thou didst send me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 9, E'I pray for them: I pray not for the world, but for them which thou hast given me; for they are thine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 10, E'And all mine are thine, and thine are mine; and I am glorified in them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 11, E'And now I am no more in the world, but these are in the world, and I come to thee. Holy Father, keep through thine own name those whom thou hast given me, that they may be one, as we are.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 12, E'While I was with them in the world, I kept them in thy name: those that thou gavest me I have kept, and none of them is lost, but the son of perdition; that the scripture might be fulfilled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 13, E'And now come I to thee; and these things I speak in the world, that they might have my joy fulfilled in themselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 14, E'I have given them thy word; and the world hath hated them, because they are not of the world, even as I am not of the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 15, E'I pray not that thou shouldest take them out of the world, but that thou shouldest keep them from the evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 16, E'They are not of the world, even as I am not of the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 17, E'Sanctify them through thy truth: thy word is truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 18, E'As thou hast sent me into the world, even so have I also sent them into the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 19, E'And for their sakes I sanctify myself, that they also might be sanctified through the truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 20, E'Neither pray I for these alone, but for them also which shall believe on me through their word;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 21, E'That they all may be one; as thou, Father, art in me, and I in thee, that they also may be one in us: that the world may believe that thou hast sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 22, E'And the glory which thou gavest me I have given them; that they may be one, even as we are one:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 23, E'I in them, and thou in me, that they may be made perfect in one; and that the world may know that thou hast sent me, and hast loved them, as thou hast loved me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 24, E'Father, I will that they also, whom thou hast given me, be with me where I am; that they may behold my glory, which thou hast given me: for thou lovedst me before the foundation of the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 25, E'O righteous Father, the world hath not known thee: but I have known thee, and these have known that thou hast sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 17, 26, E'And I have declared unto them thy name, and will declare it: that the love wherewith thou hast loved me may be in them, and I in them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 1, E'When Jesus had spoken these words, he went forth with his disciples over the brook Cedron, where was a garden, into the which he entered, and his disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 2, E'And Judas also, which betrayed him, knew the place: for Jesus ofttimes resorted thither with his disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 3, E'Judas then, having received a band of men and officers from the chief priests and Pharisees, cometh thither with lanterns and torches and weapons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 4, E'Jesus therefore, knowing all things that should come upon him, went forth, and said unto them, Whom seek ye?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 5, E'They answered him, Jesus of Nazareth. Jesus saith unto them, I am he. And Judas also, which betrayed him, stood with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 6, E'As soon then as he had said unto them, I am he, they went backward, and fell to the ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 7, E'Then asked he them again, Whom seek ye? And they said, Jesus of Nazareth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 8, E'Jesus answered, I have told you that I am he: if therefore ye seek me, let these go their way:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 9, E'That the saying might be fulfilled, which he spake, Of them which thou gavest me have I lost none.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 10, E'Then Simon Peter having a sword drew it, and smote the high priest’s servant, and cut off his right ear. The servant’s name was Malchus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 11, E'Then said Jesus unto Peter, Put up thy sword into the sheath: the cup which my Father hath given me, shall I not drink it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 12, E'Then the band and the captain and officers of the Jews took Jesus, and bound him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 13, E'And led him away to Annas first; for he was father in law to Caiaphas, which was the high priest that same year.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 14, E'Now Caiaphas was he, which gave counsel to the Jews, that it was expedient that one man should die for the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 15, E'And Simon Peter followed Jesus, and so did another disciple: that disciple was known unto the high priest, and went in with Jesus into the palace of the high priest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 16, E'But Peter stood at the door without. Then went out that other disciple, which was known unto the high priest, and spake unto her that kept the door, and brought in Peter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 17, E'Then saith the damsel that kept the door unto Peter, Art not thou also one of this man’s disciples? He saith, I am not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 18, E'And the servants and officers stood there, who had made a fire of coals; for it was cold: and they warmed themselves: and Peter stood with them, and warmed himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 19, E'The high priest then asked Jesus of his disciples, and of his doctrine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 20, E'Jesus answered him, I spake openly to the world; I ever taught in the synagogue, and in the temple, whither the Jews always resort; and in secret have I said nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 21, E'Why askest thou me? ask them which heard me, what I have said unto them: behold, they know what I said.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 22, E'And when he had thus spoken, one of the officers which stood by struck Jesus with the palm of his hand, saying, Answerest thou the high priest so?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 23, E'Jesus answered him, If I have spoken evil, bear witness of the evil: but if well, why smitest thou me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 24, E'Now Annas had sent him bound unto Caiaphas the high priest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 25, E'And Simon Peter stood and warmed himself. They said therefore unto him, Art not thou also one of his disciples? He denied it, and said, I am not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 26, E'One of the servants of the high priest, being his kinsman whose ear Peter cut off, saith, Did not I see thee in the garden with him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 27, E'Peter then denied again: and immediately the cock crew.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 28, E'Then led they Jesus from Caiaphas unto the hall of judgment: and it was early; and they themselves went not into the judgment hall, lest they should be defiled; but that they might eat the passover.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 29, E'Pilate then went out unto them, and said, What accusation bring ye against this man?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 30, E'They answered and said unto him, If he were not a malefactor, we would not have delivered him up unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 31, E'Then said Pilate unto them, Take ye him, and judge him according to your law. The Jews therefore said unto him, It is not lawful for us to put any man to death:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 32, E'That the saying of Jesus might be fulfilled, which he spake, signifying what death he should die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 33, E'Then Pilate entered into the judgment hall again, and called Jesus, and said unto him, Art thou the King of the Jews?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 34, E'Jesus answered him, Sayest thou this thing of thyself, or did others tell it thee of me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 35, E'Pilate answered, Am I a Jew? Thine own nation and the chief priests have delivered thee unto me: what hast thou done?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 36, E'Jesus answered, My kingdom is not of this world: if my kingdom were of this world, then would my servants fight, that I should not be delivered to the Jews: but now is my kingdom not from hence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 37, E'Pilate therefore said unto him, Art thou a king then? Jesus answered, Thou sayest that I am a king. To this end was I born, and for this cause came I into the world, that I should bear witness unto the truth. Every one that is of the truth heareth my voice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 38, E'Pilate saith unto him, What is truth? And when he had said this, he went out again unto the Jews, and saith unto them, I find in him no fault at all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 39, E'But ye have a custom, that I should release unto you one at the passover: will ye therefore that I release unto you the King of the Jews?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 18, 40, E'Then cried they all again, saying, Not this man, but Barabbas. Now Barabbas was a robber.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 1, E'Then Pilate therefore took Jesus, and scourged him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 2, E'And the soldiers platted a crown of thorns, and put it on his head, and they put on him a purple robe,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 3, E'And said, Hail, King of the Jews! and they smote him with their hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 4, E'Pilate therefore went forth again, and saith unto them, Behold, I bring him forth to you, that ye may know that I find no fault in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 5, E'Then came Jesus forth, wearing the crown of thorns, and the purple robe. And Pilate saith unto them, Behold the man!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 6, E'When the chief priests therefore and officers saw him, they cried out, saying, Crucify him, crucify him. Pilate saith unto them, Take ye him, and crucify him: for I find no fault in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 7, E'The Jews answered him, We have a law, and by our law he ought to die, because he made himself the Son of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 8, E'When Pilate therefore heard that saying, he was the more afraid;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 9, E'And went again into the judgment hall, and saith unto Jesus, Whence art thou? But Jesus gave him no answer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 10, E'Then saith Pilate unto him, Speakest thou not unto me? knowest thou not that I have power to crucify thee, and have power to release thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 11, E'Jesus answered, Thou couldest have no power at all against me, except it were given thee from above: therefore he that delivered me unto thee hath the greater sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 12, E'And from thenceforth Pilate sought to release him: but the Jews cried out, saying, If thou let this man go, thou art not Caesar’s friend: whosoever maketh himself a king speaketh against Caesar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 13, E'When Pilate therefore heard that saying, he brought Jesus forth, and sat down in the judgment seat in a place that is called the Pavement, but in the Hebrew, Gabbatha.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 14, E'And it was the preparation of the passover, and about the sixth hour: and he saith unto the Jews, Behold your King!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 15, E'But they cried out, Away with him, away with him, crucify him. Pilate saith unto them, Shall I crucify your King? The chief priests answered, We have no king but Caesar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 16, E'Then delivered he him therefore unto them to be crucified. And they took Jesus, and led him away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 17, E'And he bearing his cross went forth into a place called the place of a skull, which is called in the Hebrew Golgotha:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 18, E'Where they crucified him, and two other with him, on either side one, and Jesus in the midst.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 19, E'And Pilate wrote a title, and put it on the cross. And the writing was, JESUS OF NAZARETH THE KING OF THE JEWS.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'John') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 20, E'This title then read many of the Jews: for the place where Jesus was crucified was nigh to the city: and it was written in Hebrew, and Greek, and Latin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 21, E'Then said the chief priests of the Jews to Pilate, Write not, The King of the Jews; but that he said, I am King of the Jews.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 22, E'Pilate answered, What I have written I have written.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 23, E'Then the soldiers, when they had crucified Jesus, took his garments, and made four parts, to every soldier a part; and also his coat: now the coat was without seam, woven from the top throughout.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 24, E'They said therefore among themselves, Let us not rend it, but cast lots for it, whose it shall be: that the scripture might be fulfilled, which saith, They parted my raiment among them, and for my vesture they did cast lots. These things therefore the soldiers did.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 25, E'Now there stood by the cross of Jesus his mother, and his mother’s sister, Mary the wife of Cleophas, and Mary Magdalene.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 26, E'When Jesus therefore saw his mother, and the disciple standing by, whom he loved, he saith unto his mother, Woman, behold thy son!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 27, E'Then saith he to the disciple, Behold thy mother! And from that hour that disciple took her unto his own home.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 28, E'After this, Jesus knowing that all things were now accomplished, that the scripture might be fulfilled, saith, I thirst.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 29, E'Now there was set a vessel full of vinegar: and they filled a spunge with vinegar, and put it upon hyssop, and put it to his mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 30, E'When Jesus therefore had received the vinegar, he said, It is finished: and he bowed his head, and gave up the ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 31, E'The Jews therefore, because it was the preparation, that the bodies should not remain upon the cross on the sabbath day, (for that sabbath day was an high day,) besought Pilate that their legs might be broken, and that they might be taken away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 32, E'Then came the soldiers, and brake the legs of the first, and of the other which was crucified with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 33, E'But when they came to Jesus, and saw that he was dead already, they brake not his legs:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 34, E'But one of the soldiers with a spear pierced his side, and forthwith came there out blood and water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 35, E'And he that saw it bare record, and his record is true: and he knoweth that he saith true, that ye might believe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 36, E'For these things were done, that the scripture should be fulfilled, A bone of him shall not be broken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 37, E'And again another scripture saith, They shall look on him whom they pierced.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 38, E'And after this Joseph of Arimathaea, being a disciple of Jesus, but secretly for fear of the Jews, besought Pilate that he might take away the body of Jesus: and Pilate gave him leave. He came therefore, and took the body of Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 39, E'And there came also Nicodemus, which at the first came to Jesus by night, and brought a mixture of myrrh and aloes, about an hundred pound weight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 40, E'Then took they the body of Jesus, and wound it in linen clothes with the spices, as the manner of the Jews is to bury.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 41, E'Now in the place where he was crucified there was a garden; and in the garden a new sepulchre, wherein was never man yet laid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 19, 42, E'There laid they Jesus therefore because of the Jews’ preparation day; for the sepulchre was nigh at hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 1, E'The first day of the week cometh Mary Magdalene early, when it was yet dark, unto the sepulchre, and seeth the stone taken away from the sepulchre.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 2, E'Then she runneth, and cometh to Simon Peter, and to the other disciple, whom Jesus loved, and saith unto them, They have taken away the LORD out of the sepulchre, and we know not where they have laid him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 3, E'Peter therefore went forth, and that other disciple, and came to the sepulchre.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 4, E'So they ran both together: and the other disciple did outrun Peter, and came first to the sepulchre.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 5, E'And he stooping down, and looking in, saw the linen clothes lying; yet went he not in.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 6, E'Then cometh Simon Peter following him, and went into the sepulchre, and seeth the linen clothes lie,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 7, E'And the napkin, that was about his head, not lying with the linen clothes, but wrapped together in a place by itself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 8, E'Then went in also that other disciple, which came first to the sepulchre, and he saw, and believed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 9, E'For as yet they knew not the scripture, that he must rise again from the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 10, E'Then the disciples went away again unto their own home.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 11, E'But Mary stood without at the sepulchre weeping: and as she wept, she stooped down, and looked into the sepulchre,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 12, E'And seeth two angels in white sitting, the one at the head, and the other at the feet, where the body of Jesus had lain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 13, E'And they say unto her, Woman, why weepest thou? She saith unto them, Because they have taken away my LORD, and I know not where they have laid him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 14, E'And when she had thus said, she turned herself back, and saw Jesus standing, and knew not that it was Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 15, E'Jesus saith unto her, Woman, why weepest thou? whom seekest thou? She, supposing him to be the gardener, saith unto him, Sir, if thou have borne him hence, tell me where thou hast laid him, and I will take him away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 16, E'Jesus saith unto her, Mary. She turned herself, and saith unto him, Rabboni; which is to say, Master.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 17, E'Jesus saith unto her, Touch me not; for I am not yet ascended to my Father: but go to my brethren, and say unto them, I ascend unto my Father, and your Father; and to my God, and your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 18, E'Mary Magdalene came and told the disciples that she had seen the LORD, and that he had spoken these things unto her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 19, E'Then the same day at evening, being the first day of the week, when the doors were shut where the disciples were assembled for fear of the Jews, came Jesus and stood in the midst, and saith unto them, Peace be unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 20, E'And when he had so said, he shewed unto them his hands and his side. Then were the disciples glad, when they saw the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 21, E'Then said Jesus to them again, Peace be unto you: as my Father hath sent me, even so send I you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 22, E'And when he had said this, he breathed on them, and saith unto them, Receive ye the Holy Ghost:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 23, E'Whose soever sins ye remit, they are remitted unto them; and whose soever sins ye retain, they are retained.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 24, E'But Thomas, one of the twelve, called Didymus, was not with them when Jesus came.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 25, E'The other disciples therefore said unto him, We have seen the LORD. But he said unto them, Except I shall see in his hands the print of the nails, and put my finger into the print of the nails, and thrust my hand into his side, I will not believe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 26, E'And after eight days again his disciples were within, and Thomas with them: then came Jesus, the doors being shut, and stood in the midst, and said, Peace be unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 27, E'Then saith he to Thomas, Reach hither thy finger, and behold my hands; and reach hither thy hand, and thrust it into my side: and be not faithless, but believing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 28, E'And Thomas answered and said unto him, My LORD and my God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 29, E'Jesus saith unto him, Thomas, because thou hast seen me, thou hast believed: blessed are they that have not seen, and yet have believed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 30, E'And many other signs truly did Jesus in the presence of his disciples, which are not written in this book:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 20, 31, E'But these are written, that ye might believe that Jesus is the Christ, the Son of God; and that believing ye might have life through his name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 1, E'After these things Jesus shewed himself again to the disciples at the sea of Tiberias; and on this wise shewed he himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 2, E'There were together Simon Peter, and Thomas called Didymus, and Nathanael of Cana in Galilee, and the sons of Zebedee, and two other of his disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 3, E'Simon Peter saith unto them, I go a fishing. They say unto him, We also go with thee. They went forth, and entered into a ship immediately; and that night they caught nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 4, E'But when the morning was now come, Jesus stood on the shore: but the disciples knew not that it was Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 5, E'Then Jesus saith unto them, Children, have ye any meat? They answered him, No.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 6, E'And he said unto them, Cast the net on the right side of the ship, and ye shall find. They cast therefore, and now they were not able to draw it for the multitude of fishes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 7, E'Therefore that disciple whom Jesus loved saith unto Peter, It is the Lord. Now when Simon Peter heard that it was the Lord, he girt his fisher’s coat unto him, (for he was naked,) and did cast himself into the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 8, E'And the other disciples came in a little ship; (for they were not far from land, but as it were two hundred cubits,) dragging the net with fishes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 9, E'As soon then as they were come to land, they saw a fire of coals there, and fish laid thereon, and bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 10, E'Jesus saith unto them, Bring of the fish which ye have now caught.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 11, E'Simon Peter went up, and drew the net to land full of great fishes, an hundred and fifty and three: and for all there were so many, yet was not the net broken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 12, E'Jesus saith unto them, Come and dine. And none of the disciples durst ask him, Who art thou? knowing that it was the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 13, E'Jesus then cometh, and taketh bread, and giveth them, and fish likewise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 14, E'This is now the third time that Jesus shewed himself to his disciples, after that he was risen from the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 15, E'So when they had dined, Jesus saith to Simon Peter, Simon, son of Jonas, lovest thou me more than these? He saith unto him, Yea, Lord; thou knowest that I love thee. He saith unto him, Feed my lambs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 16, E'He saith to him again the second time, Simon, son of Jonas, lovest thou me? He saith unto him, Yea, Lord; thou knowest that I love thee. He saith unto him, Feed my sheep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 17, E'He saith unto him the third time, Simon, son of Jonas, lovest thou me? Peter was grieved because he said unto him the third time, Lovest thou me? And he said unto him, Lord, thou knowest all things; thou knowest that I love thee. Jesus saith unto him, Feed my sheep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 18, E'Verily, verily, I say unto thee, When thou wast young, thou girdedst thyself, and walkedst whither thou wouldest: but when thou shalt be old, thou shalt stretch forth thy hands, and another shall gird thee, and carry thee whither thou wouldest not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 19, E'This spake he, signifying by what death he should glorify God. And when he had spoken this, he saith unto him, Follow me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 20, E'Then Peter, turning about, seeth the disciple whom Jesus loved following; which also leaned on his breast at supper, and said, Lord, which is he that betrayeth thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 21, E'Peter seeing him saith to Jesus, Lord, and what shall this man do?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 22, E'Jesus saith unto him, If I will that he tarry till I come, what is that to thee? follow thou me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 23, E'Then went this saying abroad among the brethren, that that disciple should not die: yet Jesus said not unto him, He shall not die; but, If I will that he tarry till I come, what is that to thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 24, E'This is the disciple which testifieth of these things, and wrote these things: and we know that his testimony is true.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '16b94e4c-5a8b-4493-961d-e4f25aa9d8ac', 21, 25, E'And there are also many other things which Jesus did, the which, if they should be written every one, I suppose that even the world itself could not contain the books that should be written. Amen.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'John') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 1, E'The former treatise have I made, O Theophilus, of all that Jesus began both to do and teach,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 2, E'Until the day in which he was taken up, after that he through the Holy Ghost had given commandments unto the apostles whom he had chosen:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 3, E'To whom also he shewed himself alive after his passion by many infallible proofs, being seen of them forty days, and speaking of the things pertaining to the kingdom of God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 4, E'And, being assembled together with them, commanded them that they should not depart from Jerusalem, but wait for the promise of the Father, which, saith he, ye have heard of me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 5, E'For John truly baptized with water; but ye shall be baptized with the Holy Ghost not many days hence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 6, E'When they therefore were come together, they asked of him, saying, Lord, wilt thou at this time restore again the kingdom to Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 7, E'And he said unto them, It is not for you to know the times or the seasons, which the Father hath put in his own power.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 8, E'But ye shall receive power, after that the Holy Ghost is come upon you: and ye shall be witnesses unto me both in Jerusalem, and in all Judaea, and in Samaria, and unto the uttermost part of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 9, E'And when he had spoken these things, while they beheld, he was taken up; and a cloud received him out of their sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 10, E'And while they looked stedfastly toward heaven as he went up, behold, two men stood by them in white apparel;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 11, E'Which also said, Ye men of Galilee, why stand ye gazing up into heaven? this same Jesus, which is taken up from you into heaven, shall so come in like manner as ye have seen him go into heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 12, E'Then returned they unto Jerusalem from the mount called Olivet, which is from Jerusalem a sabbath day’s journey.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 13, E'And when they were come in, they went up into an upper room, where abode both Peter, and James, and John, and Andrew, Philip, and Thomas, Bartholomew, and Matthew, James the son of Alphaeus, and Simon Zelotes, and Judas the brother of James.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 14, E'These all continued with one accord in prayer and supplication, with the women, and Mary the mother of Jesus, and with his brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 15, E'And in those days Peter stood up in the midst of the disciples, and said, (the number of names together were about an hundred and twenty,)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 16, E'Men and brethren, this scripture must needs have been fulfilled, which the Holy Ghost by the mouth of David spake before concerning Judas, which was guide to them that took Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 17, E'For he was numbered with us, and had obtained part of this ministry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 18, E'Now this man purchased a field with the reward of iniquity; and falling headlong, he burst asunder in the midst, and all his bowels gushed out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 19, E'And it was known unto all the dwellers at Jerusalem; insomuch as that field is called in their proper tongue, Aceldama, that is to say, The field of blood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 20, E'For it is written in the book of Psalms, Let his habitation be desolate, and let no man dwell therein: and his bishoprick let another take.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 21, E'Wherefore of these men which have companied with us all the time that the Lord Jesus went in and out among us,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 22, E'Beginning from the baptism of John, unto that same day that he was taken up from us, must one be ordained to be a witness with us of his resurrection.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 23, E'And they appointed two, Joseph called Barsabas, who was surnamed Justus, and Matthias.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 24, E'And they prayed, and said, Thou, Lord, which knowest the hearts of all men, shew whether of these two thou hast chosen,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 25, E'That he may take part of this ministry and apostleship, from which Judas by transgression fell, that he might go to his own place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 1, 26, E'And they gave forth their lots; and the lot fell upon Matthias; and he was numbered with the eleven apostles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 1, E'And when the day of Pentecost was fully come, they were all with one accord in one place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 2, E'And suddenly there came a sound from heaven as of a rushing mighty wind, and it filled all the house where they were sitting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 3, E'And there appeared unto them cloven tongues like as of fire, and it sat upon each of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 4, E'And they were all filled with the Holy Ghost, and began to speak with other tongues, as the Spirit gave them utterance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 5, E'And there were dwelling at Jerusalem Jews, devout men, out of every nation under heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 6, E'Now when this was noised abroad, the multitude came together, and were confounded, because that every man heard them speak in his own language.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 7, E'And they were all amazed and marvelled, saying one to another, Behold, are not all these which speak Galilaeans?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 8, E'And how hear we every man in our own tongue, wherein we were born?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 9, E'Parthians, and Medes, and Elamites, and the dwellers in Mesopotamia, and in Judaea, and Cappadocia, in Pontus, and Asia,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 10, E'Phrygia, and Pamphylia, in Egypt, and in the parts of Libya about Cyrene, and strangers of Rome, Jews and proselytes,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 11, E'Cretes and Arabians, we do hear them speak in our tongues the wonderful works of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 12, E'And they were all amazed, and were in doubt, saying one to another, What meaneth this?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 13, E'Others mocking said, These men are full of new wine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 14, E'But Peter, standing up with the eleven, lifted up his voice, and said unto them, Ye men of Judaea, and all ye that dwell at Jerusalem, be this known unto you, and hearken to my words:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 15, E'For these are not drunken, as ye suppose, seeing it is but the third hour of the day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 16, E'But this is that which was spoken by the prophet Joel;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 17, E'And it shall come to pass in the last days, saith God, I will pour out of my Spirit upon all flesh: and your sons and your daughters shall prophesy, and your young men shall see visions, and your old men shall dream dreams:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 18, E'And on my servants and on my handmaidens I will pour out in those days of my Spirit; and they shall prophesy:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 19, E'And I will shew wonders in heaven above, and signs in the earth beneath; blood, and fire, and vapour of smoke:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 20, E'The sun shall be turned into darkness, and the moon into blood, before that great and notable day of the Lord come:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 21, E'And it shall come to pass, that whosoever shall call on the name of the Lord shall be saved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 22, E'Ye men of Israel, hear these words; Jesus of Nazareth, a man approved of God among you by miracles and wonders and signs, which God did by him in the midst of you, as ye yourselves also know:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 23, E'Him, being delivered by the determinate counsel and foreknowledge of God, ye have taken, and by wicked hands have crucified and slain:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 24, E'Whom God hath raised up, having loosed the pains of death: because it was not possible that he should be holden of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 25, E'For David speaketh concerning him, I foresaw the Lord always before my face, for he is on my right hand, that I should not be moved:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 26, E'Therefore did my heart rejoice, and my tongue was glad; moreover also my flesh shall rest in hope:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 27, E'Because thou wilt not leave my soul in hell, neither wilt thou suffer thine Holy One to see corruption.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 28, E'Thou hast made known to me the ways of life; thou shalt make me full of joy with thy countenance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 29, E'Men and brethren, let me freely speak unto you of the patriarch David, that he is both dead and buried, and his sepulchre is with us unto this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 30, E'Therefore being a prophet, and knowing that God had sworn with an oath to him, that of the fruit of his loins, according to the flesh, he would raise up Christ to sit on his throne;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 31, E'He seeing this before spake of the resurrection of Christ, that his soul was not left in hell, neither his flesh did see corruption.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 32, E'This Jesus hath God raised up, whereof we all are witnesses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 33, E'Therefore being by the right hand of God exalted, and having received of the Father the promise of the Holy Ghost, he hath shed forth this, which ye now see and hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 34, E'For David is not ascended into the heavens: but he saith himself, The Lord said unto my Lord, Sit thou on my right hand,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 35, E'Until I make thy foes thy footstool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 36, E'Therefore let all the house of Israel know assuredly, that God hath made that same Jesus, whom ye have crucified, both Lord and Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 37, E'Now when they heard this, they were pricked in their heart, and said unto Peter and to the rest of the apostles, Men and brethren, what shall we do?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 38, E'Then Peter said unto them, Repent, and be baptized every one of you in the name of Jesus Christ for the remission of sins, and ye shall receive the gift of the Holy Ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 39, E'For the promise is unto you, and to your children, and to all that are afar off, even as many as the LORD our God shall call.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 40, E'And with many other words did he testify and exhort, saying, Save yourselves from this untoward generation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 41, E'Then they that gladly received his word were baptized: and the same day there were added unto them about three thousand souls.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 42, E'And they continued stedfastly in the apostles’ doctrine and fellowship, and in breaking of bread, and in prayers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 43, E'And fear came upon every soul: and many wonders and signs were done by the apostles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 44, E'And all that believed were together, and had all things common;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 45, E'And sold their possessions and goods, and parted them to all men, as every man had need.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 46, E'And they, continuing daily with one accord in the temple, and breaking bread from house to house, did eat their meat with gladness and singleness of heart,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 2, 47, E'Praising God, and having favour with all the people. And the Lord added to the church daily such as should be saved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 1, E'Now Peter and John went up together into the temple at the hour of prayer, being the ninth hour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 2, E'And a certain man lame from his mother’s womb was carried, whom they laid daily at the gate of the temple which is called Beautiful, to ask alms of them that entered into the temple;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 3, E'Who seeing Peter and John about to go into the temple asked an alms.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 4, E'And Peter, fastening his eyes upon him with John, said, Look on us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 5, E'And he gave heed unto them, expecting to receive something of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 6, E'Then Peter said, Silver and gold have I none; but such as I have give I thee: In the name of Jesus Christ of Nazareth rise up and walk.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 7, E'And he took him by the right hand, and lifted him up: and immediately his feet and ankle bones received strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 8, E'And he leaping up stood, and walked, and entered with them into the temple, walking, and leaping, and praising God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 9, E'And all the people saw him walking and praising God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 10, E'And they knew that it was he which sat for alms at the Beautiful gate of the temple: and they were filled with wonder and amazement at that which had happened unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 11, E'And as the lame man which was healed held Peter and John, all the people ran together unto them in the porch that is called Solomon’s, greatly wondering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 12, E'And when Peter saw it, he answered unto the people, Ye men of Israel, why marvel ye at this? or why look ye so earnestly on us, as though by our own power or holiness we had made this man to walk?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 13, E'The God of Abraham, and of Isaac, and of Jacob, the God of our fathers, hath glorified his Son Jesus; whom ye delivered up, and denied him in the presence of Pilate, when he was determined to let him go.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 14, E'But ye denied the Holy One and the Just, and desired a murderer to be granted unto you;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 15, E'And killed the Prince of life, whom God hath raised from the dead; whereof we are witnesses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 16, E'And his name through faith in his name hath made this man strong, whom ye see and know: yea, the faith which is by him hath given him this perfect soundness in the presence of you all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 17, E'And now, brethren, I wot that through ignorance ye did it, as did also your rulers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 18, E'But those things, which God before had shewed by the mouth of all his prophets, that Christ should suffer, he hath so fulfilled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 19, E'Repent ye therefore, and be converted, that your sins may be blotted out, when the times of refreshing shall come from the presence of the Lord;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 20, E'And he shall send Jesus Christ, which before was preached unto you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 21, E'Whom the heaven must receive until the times of restitution of all things, which God hath spoken by the mouth of all his holy prophets since the world began.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 22, E'For Moses truly said unto the fathers, A prophet shall the Lord your God raise up unto you of your brethren, like unto me; him shall ye hear in all things whatsoever he shall say unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 23, E'And it shall come to pass, that every soul, which will not hear that prophet, shall be destroyed from among the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 24, E'Yea, and all the prophets from Samuel and those that follow after, as many as have spoken, have likewise foretold of these days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 25, E'Ye are the children of the prophets, and of the covenant which God made with our fathers, saying unto Abraham, And in thy seed shall all the kindreds of the earth be blessed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 3, 26, E'Unto you first God, having raised up his Son Jesus, sent him to bless you, in turning away every one of you from his iniquities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 1, E'And as they spake unto the people, the priests, and the captain of the temple, and the Sadducees, came upon them,')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Acts') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 2, E'Being grieved that they taught the people, and preached through Jesus the resurrection from the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 3, E'And they laid hands on them, and put them in hold unto the next day: for it was now eventide.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 4, E'Howbeit many of them which heard the word believed; and the number of the men was about five thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 5, E'And it came to pass on the morrow, that their rulers, and elders, and scribes,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 6, E'And Annas the high priest, and Caiaphas, and John, and Alexander, and as many as were of the kindred of the high priest, were gathered together at Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 7, E'And when they had set them in the midst, they asked, By what power, or by what name, have ye done this?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 8, E'Then Peter, filled with the Holy Ghost, said unto them, Ye rulers of the people, and elders of Israel,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 9, E'If we this day be examined of the good deed done to the impotent man, by what means he is made whole;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 10, E'Be it known unto you all, and to all the people of Israel, that by the name of Jesus Christ of Nazareth, whom ye crucified, whom God raised from the dead, even by him doth this man stand here before you whole.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 11, E'This is the stone which was set at nought of you builders, which is become the head of the corner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 12, E'Neither is there salvation in any other: for there is none other name under heaven given among men, whereby we must be saved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 13, E'Now when they saw the boldness of Peter and John, and perceived that they were unlearned and ignorant men, they marvelled; and they took knowledge of them, that they had been with Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 14, E'And beholding the man which was healed standing with them, they could say nothing against it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 15, E'But when they had commanded them to go aside out of the council, they conferred among themselves,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 16, E'Saying, What shall we do to these men? for that indeed a notable miracle hath been done by them is manifest to all them that dwell in Jerusalem; and we cannot deny it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 17, E'But that it spread no further among the people, let us straitly threaten them, that they speak henceforth to no man in this name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 18, E'And they called them, and commanded them not to speak at all nor teach in the name of Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 19, E'But Peter and John answered and said unto them, Whether it be right in the sight of God to hearken unto you more than unto God, judge ye.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 20, E'For we cannot but speak the things which we have seen and heard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 21, E'So when they had further threatened them, they let them go, finding nothing how they might punish them, because of the people: for all men glorified God for that which was done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 22, E'For the man was above forty years old, on whom this miracle of healing was shewed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 23, E'And being let go, they went to their own company, and reported all that the chief priests and elders had said unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 24, E'And when they heard that, they lifted up their voice to God with one accord, and said, Lord, thou art God, which hast made heaven, and earth, and the sea, and all that in them is:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 25, E'Who by the mouth of thy servant David hast said, Why did the heathen rage, and the people imagine vain things?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 26, E'The kings of the earth stood up, and the rulers were gathered together against the Lord, and against his Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 27, E'For of a truth against thy holy child Jesus, whom thou hast anointed, both Herod, and Pontius Pilate, with the Gentiles, and the people of Israel, were gathered together,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 28, E'For to do whatsoever thy hand and thy counsel determined before to be done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 29, E'And now, Lord, behold their threatenings: and grant unto thy servants, that with all boldness they may speak thy word,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 30, E'By stretching forth thine hand to heal; and that signs and wonders may be done by the name of thy holy child Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 31, E'And when they had prayed, the place was shaken where they were assembled together; and they were all filled with the Holy Ghost, and they spake the word of God with boldness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 32, E'And the multitude of them that believed were of one heart and of one soul: neither said any of them that ought of the things which he possessed was his own; but they had all things common.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 33, E'And with great power gave the apostles witness of the resurrection of the Lord Jesus: and great grace was upon them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 34, E'Neither was there any among them that lacked: for as many as were possessors of lands or houses sold them, and brought the prices of the things that were sold,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 35, E'And laid them down at the apostles’ feet: and distribution was made unto every man according as he had need.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 36, E'And Joses, who by the apostles was surnamed Barnabas, (which is, being interpreted, The son of consolation,) a Levite, and of the country of Cyprus,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 4, 37, E'Having land, sold it, and brought the money, and laid it at the apostles’ feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 1, E'But a certain man named Ananias, with Sapphira his wife, sold a possession,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 2, E'And kept back part of the price, his wife also being privy to it, and brought a certain part, and laid it at the apostles’ feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 3, E'But Peter said, Ananias, why hath Satan filled thine heart to lie to the Holy Ghost, and to keep back part of the price of the land?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 4, E'Whiles it remained, was it not thine own? and after it was sold, was it not in thine own power? why hast thou conceived this thing in thine heart? thou hast not lied unto men, but unto God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 5, E'And Ananias hearing these words fell down, and gave up the ghost: and great fear came on all them that heard these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 6, E'And the young men arose, wound him up, and carried him out, and buried him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 7, E'And it was about the space of three hours after, when his wife, not knowing what was done, came in.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 8, E'And Peter answered unto her, Tell me whether ye sold the land for so much? And she said, Yea, for so much.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 9, E'Then Peter said unto her, How is it that ye have agreed together to tempt the Spirit of the Lord? behold, the feet of them which have buried thy husband are at the door, and shall carry thee out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 10, E'Then fell she down straightway at his feet, and yielded up the ghost: and the young men came in, and found her dead, and, carrying her forth, buried her by her husband.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 11, E'And great fear came upon all the church, and upon as many as heard these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 12, E'And by the hands of the apostles were many signs and wonders wrought among the people; (and they were all with one accord in Solomon’s porch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 13, E'And of the rest durst no man join himself to them: but the people magnified them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 14, E'And believers were the more added to the Lord, multitudes both of men and women.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 15, E'Insomuch that they brought forth the sick into the streets, and laid them on beds and couches, that at the least the shadow of Peter passing by might overshadow some of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 16, E'There came also a multitude out of the cities round about unto Jerusalem, bringing sick folks, and them which were vexed with unclean spirits: and they were healed every one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 17, E'Then the high priest rose up, and all they that were with him, (which is the sect of the Sadducees,) and were filled with indignation,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 18, E'And laid their hands on the apostles, and put them in the common prison.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 19, E'But the angel of the Lord by night opened the prison doors, and brought them forth, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 20, E'Go, stand and speak in the temple to the people all the words of this life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 21, E'And when they heard that, they entered into the temple early in the morning, and taught. But the high priest came, and they that were with him, and called the council together, and all the senate of the children of Israel, and sent to the prison to have them brought.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 22, E'But when the officers came, and found them not in the prison, they returned, and told,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 23, E'Saying, The prison truly found we shut with all safety, and the keepers standing without before the doors: but when we had opened, we found no man within.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 24, E'Now when the high priest and the captain of the temple and the chief priests heard these things, they doubted of them whereunto this would grow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 25, E'Then came one and told them, saying, Behold, the men whom ye put in prison are standing in the temple, and teaching the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 26, E'Then went the captain with the officers, and brought them without violence: for they feared the people, lest they should have been stoned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 27, E'And when they had brought them, they set them before the council: and the high priest asked them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 28, E'Saying, Did not we straitly command you that ye should not teach in this name? and, behold, ye have filled Jerusalem with your doctrine, and intend to bring this man’s blood upon us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 29, E'Then Peter and the other apostles answered and said, We ought to obey God rather than men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 30, E'The God of our fathers raised up Jesus, whom ye slew and hanged on a tree.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 31, E'Him hath God exalted with his right hand to be a Prince and a Saviour, for to give repentance to Israel, and forgiveness of sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 32, E'And we are his witnesses of these things; and so is also the Holy Ghost, whom God hath given to them that obey him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 33, E'When they heard that, they were cut to the heart, and took counsel to slay them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 34, E'Then stood there up one in the council, a Pharisee, named Gamaliel, a doctor of the law, had in reputation among all the people, and commanded to put the apostles forth a little space;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 35, E'And said unto them, Ye men of Israel, take heed to yourselves what ye intend to do as touching these men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 36, E'For before these days rose up Theudas, boasting himself to be somebody; to whom a number of men, about four hundred, joined themselves: who was slain; and all, as many as obeyed him, were scattered, and brought to nought.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 37, E'After this man rose up Judas of Galilee in the days of the taxing, and drew away much people after him: he also perished; and all, even as many as obeyed him, were dispersed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 38, E'And now I say unto you, Refrain from these men, and let them alone: for if this counsel or this work be of men, it will come to nought:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 39, E'But if it be of God, ye cannot overthrow it; lest haply ye be found even to fight against God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 40, E'And to him they agreed: and when they had called the apostles, and beaten them, they commanded that they should not speak in the name of Jesus, and let them go.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 41, E'And they departed from the presence of the council, rejoicing that they were counted worthy to suffer shame for his name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 5, 42, E'And daily in the temple, and in every house, they ceased not to teach and preach Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 6, 1, E'And in those days, when the number of the disciples was multiplied, there arose a murmuring of the Grecians against the Hebrews, because their widows were neglected in the daily ministration.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 6, 2, E'Then the twelve called the multitude of the disciples unto them, and said, It is not reason that we should leave the word of God, and serve tables.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 6, 3, E'Wherefore, brethren, look ye out among you seven men of honest report, full of the Holy Ghost and wisdom, whom we may appoint over this business.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 6, 4, E'But we will give ourselves continually to prayer, and to the ministry of the word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 6, 5, E'And the saying pleased the whole multitude: and they chose Stephen, a man full of faith and of the Holy Ghost, and Philip, and Prochorus, and Nicanor, and Timon, and Parmenas, and Nicolas a proselyte of Antioch:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 6, 6, E'Whom they set before the apostles: and when they had prayed, they laid their hands on them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 6, 7, E'And the word of God increased; and the number of the disciples multiplied in Jerusalem greatly; and a great company of the priests were obedient to the faith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 6, 8, E'And Stephen, full of faith and power, did great wonders and miracles among the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 6, 9, E'Then there arose certain of the synagogue, which is called the synagogue of the Libertines, and Cyrenians, and Alexandrians, and of them of Cilicia and of Asia, disputing with Stephen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 6, 10, E'And they were not able to resist the wisdom and the spirit by which he spake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 6, 11, E'Then they suborned men, which said, We have heard him speak blasphemous words against Moses, and against God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 6, 12, E'And they stirred up the people, and the elders, and the scribes, and came upon him, and caught him, and brought him to the council,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 6, 13, E'And set up false witnesses, which said, This man ceaseth not to speak blasphemous words against this holy place, and the law:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 6, 14, E'For we have heard him say, that this Jesus of Nazareth shall destroy this place, and shall change the customs which Moses delivered us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 6, 15, E'And all that sat in the council, looking stedfastly on him, saw his face as it had been the face of an angel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 1, E'Then said the high priest, Are these things so?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 2, E'And he said, Men, brethren, and fathers, hearken; The God of glory appeared unto our father Abraham, when he was in Mesopotamia, before he dwelt in Charran,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 3, E'And said unto him, Get thee out of thy country, and from thy kindred, and come into the land which I shall shew thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 4, E'Then came he out of the land of the Chaldaeans, and dwelt in Charran: and from thence, when his father was dead, he removed him into this land, wherein ye now dwell.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 5, E'And he gave him none inheritance in it, no, not so much as to set his foot on: yet he promised that he would give it to him for a possession, and to his seed after him, when as yet he had no child.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 6, E'And God spake on this wise, That his seed should sojourn in a strange land; and that they should bring them into bondage, and entreat them evil four hundred years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 7, E'And the nation to whom they shall be in bondage will I judge, said God: and after that shall they come forth, and serve me in this place.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Acts') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 8, E'And he gave him the covenant of circumcision: and so Abraham begat Isaac, and circumcised him the eighth day; and Isaac begat Jacob; and Jacob begat the twelve patriarchs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 9, E'And the patriarchs, moved with envy, sold Joseph into Egypt: but God was with him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 10, E'And delivered him out of all his afflictions, and gave him favour and wisdom in the sight of Pharaoh king of Egypt; and he made him governor over Egypt and all his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 11, E'Now there came a dearth over all the land of Egypt and Chanaan, and great affliction: and our fathers found no sustenance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 12, E'But when Jacob heard that there was corn in Egypt, he sent out our fathers first.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 13, E'And at the second time Joseph was made known to his brethren; and Joseph’s kindred was made known unto Pharaoh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 14, E'Then sent Joseph, and called his father Jacob to him, and all his kindred, threescore and fifteen souls.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 15, E'So Jacob went down into Egypt, and died, he, and our fathers,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 16, E'And were carried over into Sychem, and laid in the sepulchre that Abraham bought for a sum of money of the sons of Emmor the father of Sychem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 17, E'But when the time of the promise drew nigh, which God had sworn to Abraham, the people grew and multiplied in Egypt,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 18, E'Till another king arose, which knew not Joseph.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 19, E'The same dealt subtilly with our kindred, and evil entreated our fathers, so that they cast out their young children, to the end they might not live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 20, E'In which time Moses was born, and was exceeding fair, and nourished up in his father’s house three months:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 21, E'And when he was cast out, Pharaoh’s daughter took him up, and nourished him for her own son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 22, E'And Moses was learned in all the wisdom of the Egyptians, and was mighty in words and in deeds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 23, E'And when he was full forty years old, it came into his heart to visit his brethren the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 24, E'And seeing one of them suffer wrong, he defended him, and avenged him that was oppressed, and smote the Egyptian:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 25, E'For he supposed his brethren would have understood how that God by his hand would deliver them: but they understood not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 26, E'And the next day he shewed himself unto them as they strove, and would have set them at one again, saying, Sirs, ye are brethren; why do ye wrong one to another?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 27, E'But he that did his neighbour wrong thrust him away, saying, Who made thee a ruler and a judge over us?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 28, E'Wilt thou kill me, as thou diddest the Egyptian yesterday?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 29, E'Then fled Moses at this saying, and was a stranger in the land of Madian, where he begat two sons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 30, E'And when forty years were expired, there appeared to him in the wilderness of mount Sina an angel of the Lord in a flame of fire in a bush.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 31, E'When Moses saw it, he wondered at the sight: and as he drew near to behold it, the voice of the LORD came unto him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 32, E'Saying, I am the God of thy fathers, the God of Abraham, and the God of Isaac, and the God of Jacob. Then Moses trembled, and durst not behold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 33, E'Then said the Lord to him, Put off thy shoes from thy feet: for the place where thou standest is holy ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 34, E'I have seen, I have seen the affliction of my people which is in Egypt, and I have heard their groaning, and am come down to deliver them. And now come, I will send thee into Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 35, E'This Moses whom they refused, saying, Who made thee a ruler and a judge? the same did God send to be a ruler and a deliverer by the hand of the angel which appeared to him in the bush.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 36, E'He brought them out, after that he had shewed wonders and signs in the land of Egypt, and in the Red sea, and in the wilderness forty years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 37, E'This is that Moses, which said unto the children of Israel, A prophet shall the Lord your God raise up unto you of your brethren, like unto me; him shall ye hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 38, E'This is he, that was in the church in the wilderness with the angel which spake to him in the mount Sina, and with our fathers: who received the lively oracles to give unto us:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 39, E'To whom our fathers would not obey, but thrust him from them, and in their hearts turned back again into Egypt,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 40, E'Saying unto Aaron, Make us gods to go before us: for as for this Moses, which brought us out of the land of Egypt, we wot not what is become of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 41, E'And they made a calf in those days, and offered sacrifice unto the idol, and rejoiced in the works of their own hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 42, E'Then God turned, and gave them up to worship the host of heaven; as it is written in the book of the prophets, O ye house of Israel, have ye offered to me slain beasts and sacrifices by the space of forty years in the wilderness?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 43, E'Yea, ye took up the tabernacle of Moloch, and the star of your god Remphan, figures which ye made to worship them: and I will carry you away beyond Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 44, E'Our fathers had the tabernacle of witness in the wilderness, as he had appointed, speaking unto Moses, that he should make it according to the fashion that he had seen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 45, E'Which also our fathers that came after brought in with Jesus into the possession of the Gentiles, whom God drave out before the face of our fathers, unto the days of David;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 46, E'Who found favour before God, and desired to find a tabernacle for the God of Jacob.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 47, E'But Solomon built him an house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 48, E'Howbeit the most High dwelleth not in temples made with hands; as saith the prophet,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 49, E'Heaven is my throne, and earth is my footstool: what house will ye build me? saith the Lord: or what is the place of my rest?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 50, E'Hath not my hand made all these things?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 51, E'Ye stiffnecked and uncircumcised in heart and ears, ye do always resist the Holy Ghost: as your fathers did, so do ye.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 52, E'Which of the prophets have not your fathers persecuted? and they have slain them which shewed before of the coming of the Just One; of whom ye have been now the betrayers and murderers:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 53, E'Who have received the law by the disposition of angels, and have not kept it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 54, E'When they heard these things, they were cut to the heart, and they gnashed on him with their teeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 55, E'But he, being full of the Holy Ghost, looked up stedfastly into heaven, and saw the glory of God, and Jesus standing on the right hand of God,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 56, E'And said, Behold, I see the heavens opened, and the Son of man standing on the right hand of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 57, E'Then they cried out with a loud voice, and stopped their ears, and ran upon him with one accord,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 58, E'And cast him out of the city, and stoned him: and the witnesses laid down their clothes at a young man’s feet, whose name was Saul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 59, E'And they stoned Stephen, calling upon God, and saying, Lord Jesus, receive my spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 7, 60, E'And he kneeled down, and cried with a loud voice, Lord, lay not this sin to their charge. And when he had said this, he fell asleep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 1, E'And Saul was consenting unto his death. And at that time there was a great persecution against the church which was at Jerusalem; and they were all scattered abroad throughout the regions of Judaea and Samaria, except the apostles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 2, E'And devout men carried Stephen to his burial, and made great lamentation over him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 3, E'As for Saul, he made havock of the church, entering into every house, and haling men and women committed them to prison.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 4, E'Therefore they that were scattered abroad went every where preaching the word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 5, E'Then Philip went down to the city of Samaria, and preached Christ unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 6, E'And the people with one accord gave heed unto those things which Philip spake, hearing and seeing the miracles which he did.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 7, E'For unclean spirits, crying with loud voice, came out of many that were possessed with them: and many taken with palsies, and that were lame, were healed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 8, E'And there was great joy in that city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 9, E'But there was a certain man, called Simon, which beforetime in the same city used sorcery, and bewitched the people of Samaria, giving out that himself was some great one:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 10, E'To whom they all gave heed, from the least to the greatest, saying, This man is the great power of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 11, E'And to him they had regard, because that of long time he had bewitched them with sorceries.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 12, E'But when they believed Philip preaching the things concerning the kingdom of God, and the name of Jesus Christ, they were baptized, both men and women.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 13, E'Then Simon himself believed also: and when he was baptized, he continued with Philip, and wondered, beholding the miracles and signs which were done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 14, E'Now when the apostles which were at Jerusalem heard that Samaria had received the word of God, they sent unto them Peter and John:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 15, E'Who, when they were come down, prayed for them, that they might receive the Holy Ghost:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 16, E'(For as yet he was fallen upon none of them: only they were baptized in the name of the Lord Jesus.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 17, E'Then laid they their hands on them, and they received the Holy Ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 18, E'And when Simon saw that through laying on of the apostles’ hands the Holy Ghost was given, he offered them money,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 19, E'Saying, Give me also this power, that on whomsoever I lay hands, he may receive the Holy Ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 20, E'But Peter said unto him, Thy money perish with thee, because thou hast thought that the gift of God may be purchased with money.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 21, E'Thou hast neither part nor lot in this matter: for thy heart is not right in the sight of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 22, E'Repent therefore of this thy wickedness, and pray God, if perhaps the thought of thine heart may be forgiven thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 23, E'For I perceive that thou art in the gall of bitterness, and in the bond of iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 24, E'Then answered Simon, and said, Pray ye to the LORD for me, that none of these things which ye have spoken come upon me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 25, E'And they, when they had testified and preached the word of the Lord, returned to Jerusalem, and preached the gospel in many villages of the Samaritans.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 26, E'And the angel of the Lord spake unto Philip, saying, Arise, and go toward the south unto the way that goeth down from Jerusalem unto Gaza, which is desert.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 27, E'And he arose and went: and, behold, a man of Ethiopia, an eunuch of great authority under Candace queen of the Ethiopians, who had the charge of all her treasure, and had come to Jerusalem for to worship,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 28, E'Was returning, and sitting in his chariot read Esaias the prophet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 29, E'Then the Spirit said unto Philip, Go near, and join thyself to this chariot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 30, E'And Philip ran thither to him, and heard him read the prophet Esaias, and said, Understandest thou what thou readest?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 31, E'And he said, How can I, except some man should guide me? And he desired Philip that he would come up and sit with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 32, E'The place of the scripture which he read was this, He was led as a sheep to the slaughter; and like a lamb dumb before his shearer, so opened he not his mouth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 33, E'In his humiliation his judgment was taken away: and who shall declare his generation? for his life is taken from the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 34, E'And the eunuch answered Philip, and said, I pray thee, of whom speaketh the prophet this? of himself, or of some other man?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 35, E'Then Philip opened his mouth, and began at the same scripture, and preached unto him Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 36, E'And as they went on their way, they came unto a certain water: and the eunuch said, See, here is water; what doth hinder me to be baptized?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 37, E'And Philip said, If thou believest with all thine heart, thou mayest. And he answered and said, I believe that Jesus Christ is the Son of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 38, E'And he commanded the chariot to stand still: and they went down both into the water, both Philip and the eunuch; and he baptized him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 39, E'And when they were come up out of the water, the Spirit of the Lord caught away Philip, that the eunuch saw him no more: and he went on his way rejoicing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 8, 40, E'But Philip was found at Azotus: and passing through he preached in all the cities, till he came to Caesarea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 1, E'And Saul, yet breathing out threatenings and slaughter against the disciples of the Lord, went unto the high priest,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 2, E'And desired of him letters to Damascus to the synagogues, that if he found any of this way, whether they were men or women, he might bring them bound unto Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 3, E'And as he journeyed, he came near Damascus: and suddenly there shined round about him a light from heaven:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 4, E'And he fell to the earth, and heard a voice saying unto him, Saul, Saul, why persecutest thou me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 5, E'And he said, Who art thou, Lord? And the Lord said, I am Jesus whom thou persecutest: it is hard for thee to kick against the pricks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 6, E'And he trembling and astonished said, Lord, what wilt thou have me to do? And the Lord said unto him, Arise, and go into the city, and it shall be told thee what thou must do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 7, E'And the men which journeyed with him stood speechless, hearing a voice, but seeing no man.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Acts') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 8, E'And Saul arose from the earth; and when his eyes were opened, he saw no man: but they led him by the hand, and brought him into Damascus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 9, E'And he was three days without sight, and neither did eat nor drink.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 10, E'And there was a certain disciple at Damascus, named Ananias; and to him said the Lord in a vision, Ananias. And he said, Behold, I am here, Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 11, E'And the Lord said unto him, Arise, and go into the street which is called Straight, and enquire in the house of Judas for one called Saul, of Tarsus: for, behold, he prayeth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 12, E'And hath seen in a vision a man named Ananias coming in, and putting his hand on him, that he might receive his sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 13, E'Then Ananias answered, Lord, I have heard by many of this man, how much evil he hath done to thy saints at Jerusalem:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 14, E'And here he hath authority from the chief priests to bind all that call on thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 15, E'But the Lord said unto him, Go thy way: for he is a chosen vessel unto me, to bear my name before the Gentiles, and kings, and the children of Israel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 16, E'For I will shew him how great things he must suffer for my name’s sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 17, E'And Ananias went his way, and entered into the house; and putting his hands on him said, Brother Saul, the Lord, even Jesus, that appeared unto thee in the way as thou camest, hath sent me, that thou mightest receive thy sight, and be filled with the Holy Ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 18, E'And immediately there fell from his eyes as it had been scales: and he received sight forthwith, and arose, and was baptized.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 19, E'And when he had received meat, he was strengthened. Then was Saul certain days with the disciples which were at Damascus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 20, E'And straightway he preached Christ in the synagogues, that he is the Son of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 21, E'But all that heard him were amazed, and said; Is not this he that destroyed them which called on this name in Jerusalem, and came hither for that intent, that he might bring them bound unto the chief priests?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 22, E'But Saul increased the more in strength, and confounded the Jews which dwelt at Damascus, proving that this is very Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 23, E'And after that many days were fulfilled, the Jews took counsel to kill him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 24, E'But their laying await was known of Saul. And they watched the gates day and night to kill him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 25, E'Then the disciples took him by night, and let him down by the wall in a basket.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 26, E'And when Saul was come to Jerusalem, he assayed to join himself to the disciples: but they were all afraid of him, and believed not that he was a disciple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 27, E'But Barnabas took him, and brought him to the apostles, and declared unto them how he had seen the Lord in the way, and that he had spoken to him, and how he had preached boldly at Damascus in the name of Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 28, E'And he was with them coming in and going out at Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 29, E'And he spake boldly in the name of the Lord Jesus, and disputed against the Grecians: but they went about to slay him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 30, E'Which when the brethren knew, they brought him down to Caesarea, and sent him forth to Tarsus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 31, E'Then had the churches rest throughout all Judaea and Galilee and Samaria, and were edified; and walking in the fear of the Lord, and in the comfort of the Holy Ghost, were multiplied.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 32, E'And it came to pass, as Peter passed throughout all quarters, he came down also to the saints which dwelt at Lydda.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 33, E'And there he found a certain man named Aeneas, which had kept his bed eight years, and was sick of the palsy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 34, E'And Peter said unto him, Aeneas, Jesus Christ maketh thee whole: arise, and make thy bed. And he arose immediately.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 35, E'And all that dwelt at Lydda and Saron saw him, and turned to the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 36, E'Now there was at Joppa a certain disciple named Tabitha, which by interpretation is called Dorcas: this woman was full of good works and almsdeeds which she did.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 37, E'And it came to pass in those days, that she was sick, and died: whom when they had washed, they laid her in an upper chamber.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 38, E'And forasmuch as Lydda was nigh to Joppa, and the disciples had heard that Peter was there, they sent unto him two men, desiring him that he would not delay to come to them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 39, E'Then Peter arose and went with them. When he was come, they brought him into the upper chamber: and all the widows stood by him weeping, and shewing the coats and garments which Dorcas made, while she was with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 40, E'But Peter put them all forth, and kneeled down, and prayed; and turning him to the body said, Tabitha, arise. And she opened her eyes: and when she saw Peter, she sat up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 41, E'And he gave her his hand, and lifted her up, and when he had called the saints and widows, presented her alive.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 42, E'And it was known throughout all Joppa; and many believed in the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 9, 43, E'And it came to pass, that he tarried many days in Joppa with one Simon a tanner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 1, E'There was a certain man in Caesarea called Cornelius, a centurion of the band called the Italian band,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 2, E'A devout man, and one that feared God with all his house, which gave much alms to the people, and prayed to God alway.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 3, E'He saw in a vision evidently about the ninth hour of the day an angel of God coming in to him, and saying unto him, Cornelius.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 4, E'And when he looked on him, he was afraid, and said, What is it, Lord? And he said unto him, Thy prayers and thine alms are come up for a memorial before God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 5, E'And now send men to Joppa, and call for one Simon, whose surname is Peter:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 6, E'He lodgeth with one Simon a tanner, whose house is by the sea side: he shall tell thee what thou oughtest to do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 7, E'And when the angel which spake unto Cornelius was departed, he called two of his household servants, and a devout soldier of them that waited on him continually;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 8, E'And when he had declared all these things unto them, he sent them to Joppa.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 9, E'On the morrow, as they went on their journey, and drew nigh unto the city, Peter went up upon the housetop to pray about the sixth hour:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 10, E'And he became very hungry, and would have eaten: but while they made ready, he fell into a trance,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 11, E'And saw heaven opened, and a certain vessel descending unto him, as it had been a great sheet knit at the four corners, and let down to the earth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 12, E'Wherein were all manner of fourfooted beasts of the earth, and wild beasts, and creeping things, and fowls of the air.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 13, E'And there came a voice to him, Rise, Peter; kill, and eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 14, E'But Peter said, Not so, Lord; for I have never eaten any thing that is common or unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 15, E'And the voice spake unto him again the second time, What God hath cleansed, that call not thou common.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 16, E'This was done thrice: and the vessel was received up again into heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 17, E'Now while Peter doubted in himself what this vision which he had seen should mean, behold, the men which were sent from Cornelius had made enquiry for Simon’s house, and stood before the gate,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 18, E'And called, and asked whether Simon, which was surnamed Peter, were lodged there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 19, E'While Peter thought on the vision, the Spirit said unto him, Behold, three men seek thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 20, E'Arise therefore, and get thee down, and go with them, doubting nothing: for I have sent them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 21, E'Then Peter went down to the men which were sent unto him from Cornelius; and said, Behold, I am he whom ye seek: what is the cause wherefore ye are come?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 22, E'And they said, Cornelius the centurion, a just man, and one that feareth God, and of good report among all the nation of the Jews, was warned from God by an holy angel to send for thee into his house, and to hear words of thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 23, E'Then called he them in, and lodged them. And on the morrow Peter went away with them, and certain brethren from Joppa accompanied him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 24, E'And the morrow after they entered into Caesarea. And Cornelius waited for them, and had called together his kinsmen and near friends.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 25, E'And as Peter was coming in, Cornelius met him, and fell down at his feet, and worshipped him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 26, E'But Peter took him up, saying, Stand up; I myself also am a man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 27, E'And as he talked with him, he went in, and found many that were come together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 28, E'And he said unto them, Ye know how that it is an unlawful thing for a man that is a Jew to keep company, or come unto one of another nation; but God hath shewed me that I should not call any man common or unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 29, E'Therefore came I unto you without gainsaying, as soon as I was sent for: I ask therefore for what intent ye have sent for me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 30, E'And Cornelius said, Four days ago I was fasting until this hour; and at the ninth hour I prayed in my house, and, behold, a man stood before me in bright clothing,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 31, E'And said, Cornelius, thy prayer is heard, and thine alms are had in remembrance in the sight of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 32, E'Send therefore to Joppa, and call hither Simon, whose surname is Peter; he is lodged in the house of one Simon a tanner by the sea side: who, when he cometh, shall speak unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 33, E'Immediately therefore I sent to thee; and thou hast well done that thou art come. Now therefore are we all here present before God, to hear all things that are commanded thee of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 34, E'Then Peter opened his mouth, and said, Of a truth I perceive that God is no respecter of persons:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 35, E'But in every nation he that feareth him, and worketh righteousness, is accepted with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 36, E'The word which God sent unto the children of Israel, preaching peace by Jesus Christ: (he is Lord of all:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 37, E'That word, I say, ye know, which was published throughout all Judaea, and began from Galilee, after the baptism which John preached;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 38, E'How God anointed Jesus of Nazareth with the Holy Ghost and with power: who went about doing good, and healing all that were oppressed of the devil; for God was with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 39, E'And we are witnesses of all things which he did both in the land of the Jews, and in Jerusalem; whom they slew and hanged on a tree:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 40, E'Him God raised up the third day, and shewed him openly;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 41, E'Not to all the people, but unto witnesses chosen before of God, even to us, who did eat and drink with him after he rose from the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 42, E'And he commanded us to preach unto the people, and to testify that it is he which was ordained of God to be the Judge of quick and dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 43, E'To him give all the prophets witness, that through his name whosoever believeth in him shall receive remission of sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 44, E'While Peter yet spake these words, the Holy Ghost fell on all them which heard the word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 45, E'And they of the circumcision which believed were astonished, as many as came with Peter, because that on the Gentiles also was poured out the gift of the Holy Ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 46, E'For they heard them speak with tongues, and magnify God. Then answered Peter,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 47, E'Can any man forbid water, that these should not be baptized, which have received the Holy Ghost as well as we?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 10, 48, E'And he commanded them to be baptized in the name of the Lord. Then prayed they him to tarry certain days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 1, E'And the apostles and brethren that were in Judaea heard that the Gentiles had also received the word of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 2, E'And when Peter was come up to Jerusalem, they that were of the circumcision contended with him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 3, E'Saying, Thou wentest in to men uncircumcised, and didst eat with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 4, E'But Peter rehearsed the matter from the beginning, and expounded it by order unto them, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 5, E'I was in the city of Joppa praying: and in a trance I saw a vision, A certain vessel descend, as it had been a great sheet, let down from heaven by four corners; and it came even to me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 6, E'Upon the which when I had fastened mine eyes, I considered, and saw fourfooted beasts of the earth, and wild beasts, and creeping things, and fowls of the air.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 7, E'And I heard a voice saying unto me, Arise, Peter; slay and eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 8, E'But I said, Not so, Lord: for nothing common or unclean hath at any time entered into my mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 9, E'But the voice answered me again from heaven, What God hath cleansed, that call not thou common.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 10, E'And this was done three times: and all were drawn up again into heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 11, E'And, behold, immediately there were three men already come unto the house where I was, sent from Caesarea unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 12, E'And the Spirit bade me go with them, nothing doubting. Moreover these six brethren accompanied me, and we entered into the man’s house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 13, E'And he shewed us how he had seen an angel in his house, which stood and said unto him, Send men to Joppa, and call for Simon, whose surname is Peter;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 14, E'Who shall tell thee words, whereby thou and all thy house shall be saved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 15, E'And as I began to speak, the Holy Ghost fell on them, as on us at the beginning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 16, E'Then remembered I the word of the Lord, how that he said, John indeed baptized with water; but ye shall be baptized with the Holy Ghost.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Acts') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 17, E'Forasmuch then as God gave them the like gift as he did unto us, who believed on the Lord Jesus Christ; what was I, that I could withstand God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 18, E'When they heard these things, they held their peace, and glorified God, saying, Then hath God also to the Gentiles granted repentance unto life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 19, E'Now they which were scattered abroad upon the persecution that arose about Stephen travelled as far as Phenice, and Cyprus, and Antioch, preaching the word to none but unto the Jews only.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 20, E'And some of them were men of Cyprus and Cyrene, which, when they were come to Antioch, spake unto the Grecians, preaching the LORD Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 21, E'And the hand of the Lord was with them: and a great number believed, and turned unto the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 22, E'Then tidings of these things came unto the ears of the church which was in Jerusalem: and they sent forth Barnabas, that he should go as far as Antioch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 23, E'Who, when he came, and had seen the grace of God, was glad, and exhorted them all, that with purpose of heart they would cleave unto the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 24, E'For he was a good man, and full of the Holy Ghost and of faith: and much people was added unto the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 25, E'Then departed Barnabas to Tarsus, for to seek Saul:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 26, E'And when he had found him, he brought him unto Antioch. And it came to pass, that a whole year they assembled themselves with the church, and taught much people. And the disciples were called Christians first in Antioch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 27, E'And in these days came prophets from Jerusalem unto Antioch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 28, E'And there stood up one of them named Agabus, and signified by the Spirit that there should be great dearth throughout all the world: which came to pass in the days of Claudius Caesar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 29, E'Then the disciples, every man according to his ability, determined to send relief unto the brethren which dwelt in Judaea:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 11, 30, E'Which also they did, and sent it to the elders by the hands of Barnabas and Saul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 1, E'Now about that time Herod the king stretched forth his hands to vex certain of the church.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 2, E'And he killed James the brother of John with the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 3, E'And because he saw it pleased the Jews, he proceeded further to take Peter also. (Then were the days of unleavened bread.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 4, E'And when he had apprehended him, he put him in prison, and delivered him to four quaternions of soldiers to keep him; intending after Easter to bring him forth to the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 5, E'Peter therefore was kept in prison: but prayer was made without ceasing of the church unto God for him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 6, E'And when Herod would have brought him forth, the same night Peter was sleeping between two soldiers, bound with two chains: and the keepers before the door kept the prison.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 7, E'And, behold, the angel of the Lord came upon him, and a light shined in the prison: and he smote Peter on the side, and raised him up, saying, Arise up quickly. And his chains fell off from his hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 8, E'And the angel said unto him, Gird thyself, and bind on thy sandals. And so he did. And he saith unto him, Cast thy garment about thee, and follow me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 9, E'And he went out, and followed him; and wist not that it was true which was done by the angel; but thought he saw a vision.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 10, E'When they were past the first and the second ward, they came unto the iron gate that leadeth unto the city; which opened to them of his own accord: and they went out, and passed on through one street; and forthwith the angel departed from him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 11, E'And when Peter was come to himself, he said, Now I know of a surety, that the LORD hath sent his angel, and hath delivered me out of the hand of Herod, and from all the expectation of the people of the Jews.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 12, E'And when he had considered the thing, he came to the house of Mary the mother of John, whose surname was Mark; where many were gathered together praying.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 13, E'And as Peter knocked at the door of the gate, a damsel came to hearken, named Rhoda.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 14, E'And when she knew Peter’s voice, she opened not the gate for gladness, but ran in, and told how Peter stood before the gate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 15, E'And they said unto her, Thou art mad. But she constantly affirmed that it was even so. Then said they, It is his angel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 16, E'But Peter continued knocking: and when they had opened the door, and saw him, they were astonished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 17, E'But he, beckoning unto them with the hand to hold their peace, declared unto them how the Lord had brought him out of the prison. And he said, Go shew these things unto James, and to the brethren. And he departed, and went into another place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 18, E'Now as soon as it was day, there was no small stir among the soldiers, what was become of Peter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 19, E'And when Herod had sought for him, and found him not, he examined the keepers, and commanded that they should be put to death. And he went down from Judaea to Caesarea, and there abode.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 20, E'And Herod was highly displeased with them of Tyre and Sidon: but they came with one accord to him, and, having made Blastus the king’s chamberlain their friend, desired peace; because their country was nourished by the king’s country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 21, E'And upon a set day Herod, arrayed in royal apparel, sat upon his throne, and made an oration unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 22, E'And the people gave a shout, saying, It is the voice of a god, and not of a man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 23, E'And immediately the angel of the Lord smote him, because he gave not God the glory: and he was eaten of worms, and gave up the ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 24, E'But the word of God grew and multiplied.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 12, 25, E'And Barnabas and Saul returned from Jerusalem, when they had fulfilled their ministry, and took with them John, whose surname was Mark.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 1, E'Now there were in the church that was at Antioch certain prophets and teachers; as Barnabas, and Simeon that was called Niger, and Lucius of Cyrene, and Manaen, which had been brought up with Herod the tetrarch, and Saul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 2, E'As they ministered to the Lord, and fasted, the Holy Ghost said, Separate me Barnabas and Saul for the work whereunto I have called them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 3, E'And when they had fasted and prayed, and laid their hands on them, they sent them away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 4, E'So they, being sent forth by the Holy Ghost, departed unto Seleucia; and from thence they sailed to Cyprus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 5, E'And when they were at Salamis, they preached the word of God in the synagogues of the Jews: and they had also John to their minister.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 6, E'And when they had gone through the isle unto Paphos, they found a certain sorcerer, a false prophet, a Jew, whose name was Barjesus:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 7, E'Which was with the deputy of the country, Sergius Paulus, a prudent man; who called for Barnabas and Saul, and desired to hear the word of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 8, E'But Elymas the sorcerer (for so is his name by interpretation) withstood them, seeking to turn away the deputy from the faith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 9, E'Then Saul, (who also is called Paul,) filled with the Holy Ghost, set his eyes on him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 10, E'And said, O full of all subtilty and all mischief, thou child of the devil, thou enemy of all righteousness, wilt thou not cease to pervert the right ways of the Lord?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 11, E'And now, behold, the hand of the Lord is upon thee, and thou shalt be blind, not seeing the sun for a season. And immediately there fell on him a mist and a darkness; and he went about seeking some to lead him by the hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 12, E'Then the deputy, when he saw what was done, believed, being astonished at the doctrine of the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 13, E'Now when Paul and his company loosed from Paphos, they came to Perga in Pamphylia: and John departing from them returned to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 14, E'But when they departed from Perga, they came to Antioch in Pisidia, and went into the synagogue on the sabbath day, and sat down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 15, E'And after the reading of the law and the prophets the rulers of the synagogue sent unto them, saying, Ye men and brethren, if ye have any word of exhortation for the people, say on.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 16, E'Then Paul stood up, and beckoning with his hand said, Men of Israel, and ye that fear God, give audience.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 17, E'The God of this people of Israel chose our fathers, and exalted the people when they dwelt as strangers in the land of Egypt, and with an high arm brought he them out of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 18, E'And about the time of forty years suffered he their manners in the wilderness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 19, E'And when he had destroyed seven nations in the land of Chanaan, he divided their land to them by lot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 20, E'And after that he gave unto them judges about the space of four hundred and fifty years, until Samuel the prophet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 21, E'And afterward they desired a king: and God gave unto them Saul the son of Cis, a man of the tribe of Benjamin, by the space of forty years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 22, E'And when he had removed him, he raised up unto them David to be their king; to whom also he gave testimony, and said, I have found David the son of Jesse, a man after mine own heart, which shall fulfil all my will.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 23, E'Of this man’s seed hath God according to his promise raised unto Israel a Saviour, Jesus:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 24, E'When John had first preached before his coming the baptism of repentance to all the people of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 25, E'And as John fulfilled his course, he said, Whom think ye that I am? I am not he. But, behold, there cometh one after me, whose shoes of his feet I am not worthy to loose.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 26, E'Men and brethren, children of the stock of Abraham, and whosoever among you feareth God, to you is the word of this salvation sent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 27, E'For they that dwell at Jerusalem, and their rulers, because they knew him not, nor yet the voices of the prophets which are read every sabbath day, they have fulfilled them in condemning him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 28, E'And though they found no cause of death in him, yet desired they Pilate that he should be slain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 29, E'And when they had fulfilled all that was written of him, they took him down from the tree, and laid him in a sepulchre.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 30, E'But God raised him from the dead:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 31, E'And he was seen many days of them which came up with him from Galilee to Jerusalem, who are his witnesses unto the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 32, E'And we declare unto you glad tidings, how that the promise which was made unto the fathers,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 33, E'God hath fulfilled the same unto us their children, in that he hath raised up Jesus again; as it is also written in the second psalm, Thou art my Son, this day have I begotten thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 34, E'And as concerning that he raised him up from the dead, now no more to return to corruption, he said on this wise, I will give you the sure mercies of David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 35, E'Wherefore he saith also in another psalm, Thou shalt not suffer thine Holy One to see corruption.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 36, E'For David, after he had served his own generation by the will of God, fell on sleep, and was laid unto his fathers, and saw corruption:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 37, E'But he, whom God raised again, saw no corruption.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 38, E'Be it known unto you therefore, men and brethren, that through this man is preached unto you the forgiveness of sins:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 39, E'And by him all that believe are justified from all things, from which ye could not be justified by the law of Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 40, E'Beware therefore, lest that come upon you, which is spoken of in the prophets;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 41, E'Behold, ye despisers, and wonder, and perish: for I work a work in your days, a work which ye shall in no wise believe, though a man declare it unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 42, E'And when the Jews were gone out of the synagogue, the Gentiles besought that these words might be preached to them the next sabbath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 43, E'Now when the congregation was broken up, many of the Jews and religious proselytes followed Paul and Barnabas: who, speaking to them, persuaded them to continue in the grace of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 44, E'And the next sabbath day came almost the whole city together to hear the word of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 45, E'But when the Jews saw the multitudes, they were filled with envy, and spake against those things which were spoken by Paul, contradicting and blaspheming.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 46, E'Then Paul and Barnabas waxed bold, and said, It was necessary that the word of God should first have been spoken to you: but seeing ye put it from you, and judge yourselves unworthy of everlasting life, lo, we turn to the Gentiles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 47, E'For so hath the Lord commanded us, saying, I have set thee to be a light of the Gentiles, that thou shouldest be for salvation unto the ends of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 48, E'And when the Gentiles heard this, they were glad, and glorified the word of the Lord: and as many as were ordained to eternal life believed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 49, E'And the word of the Lord was published throughout all the region.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 50, E'But the Jews stirred up the devout and honourable women, and the chief men of the city, and raised persecution against Paul and Barnabas, and expelled them out of their coasts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 51, E'But they shook off the dust of their feet against them, and came unto Iconium.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 13, 52, E'And the disciples were filled with joy, and with the Holy Ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 1, E'And it came to pass in Iconium, that they went both together into the synagogue of the Jews, and so spake, that a great multitude both of the Jews and also of the Greeks believed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 2, E'But the unbelieving Jews stirred up the Gentiles, and made their minds evil affected against the brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 3, E'Long time therefore abode they speaking boldly in the Lord, which gave testimony unto the word of his grace, and granted signs and wonders to be done by their hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 4, E'But the multitude of the city was divided: and part held with the Jews, and part with the apostles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 5, E'And when there was an assault made both of the Gentiles, and also of the Jews with their rulers, to use them despitefully, and to stone them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 6, E'They were ware of it, and fled unto Lystra and Derbe, cities of Lycaonia, and unto the region that lieth round about:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 7, E'And there they preached the gospel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 8, E'And there sat a certain man at Lystra, impotent in his feet, being a cripple from his mother’s womb, who never had walked:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 9, E'The same heard Paul speak: who stedfastly beholding him, and perceiving that he had faith to be healed,')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Acts') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 10, E'Said with a loud voice, Stand upright on thy feet. And he leaped and walked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 11, E'And when the people saw what Paul had done, they lifted up their voices, saying in the speech of Lycaonia, The gods are come down to us in the likeness of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 12, E'And they called Barnabas, Jupiter; and Paul, Mercurius, because he was the chief speaker.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 13, E'Then the priest of Jupiter, which was before their city, brought oxen and garlands unto the gates, and would have done sacrifice with the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 14, E'Which when the apostles, Barnabas and Paul, heard of, they rent their clothes, and ran in among the people, crying out,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 15, E'And saying, Sirs, why do ye these things? We also are men of like passions with you, and preach unto you that ye should turn from these vanities unto the living God, which made heaven, and earth, and the sea, and all things that are therein:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 16, E'Who in times past suffered all nations to walk in their own ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 17, E'Nevertheless he left not himself without witness, in that he did good, and gave us rain from heaven, and fruitful seasons, filling our hearts with food and gladness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 18, E'And with these sayings scarce restrained they the people, that they had not done sacrifice unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 19, E'And there came thither certain Jews from Antioch and Iconium, who persuaded the people, and, having stoned Paul, drew him out of the city, supposing he had been dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 20, E'Howbeit, as the disciples stood round about him, he rose up, and came into the city: and the next day he departed with Barnabas to Derbe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 21, E'And when they had preached the gospel to that city, and had taught many, they returned again to Lystra, and to Iconium, and Antioch,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 22, E'Confirming the souls of the disciples, and exhorting them to continue in the faith, and that we must through much tribulation enter into the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 23, E'And when they had ordained them elders in every church, and had prayed with fasting, they commended them to the Lord, on whom they believed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 24, E'And after they had passed throughout Pisidia, they came to Pamphylia.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 25, E'And when they had preached the word in Perga, they went down into Attalia:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 26, E'And thence sailed to Antioch, from whence they had been recommended to the grace of God for the work which they fulfilled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 27, E'And when they were come, and had gathered the church together, they rehearsed all that God had done with them, and how he had opened the door of faith unto the Gentiles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 14, 28, E'And there they abode long time with the disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 1, E'And certain men which came down from Judaea taught the brethren, and said, Except ye be circumcised after the manner of Moses, ye cannot be saved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 2, E'When therefore Paul and Barnabas had no small dissension and disputation with them, they determined that Paul and Barnabas, and certain other of them, should go up to Jerusalem unto the apostles and elders about this question.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 3, E'And being brought on their way by the church, they passed through Phenice and Samaria, declaring the conversion of the Gentiles: and they caused great joy unto all the brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 4, E'And when they were come to Jerusalem, they were received of the church, and of the apostles and elders, and they declared all things that God had done with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 5, E'But there rose up certain of the sect of the Pharisees which believed, saying, That it was needful to circumcise them, and to command them to keep the law of Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 6, E'And the apostles and elders came together for to consider of this matter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 7, E'And when there had been much disputing, Peter rose up, and said unto them, Men and brethren, ye know how that a good while ago God made choice among us, that the Gentiles by my mouth should hear the word of the gospel, and believe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 8, E'And God, which knoweth the hearts, bare them witness, giving them the Holy Ghost, even as he did unto us;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 9, E'And put no difference between us and them, purifying their hearts by faith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 10, E'Now therefore why tempt ye God, to put a yoke upon the neck of the disciples, which neither our fathers nor we were able to bear?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 11, E'But we believe that through the grace of the LORD Jesus Christ we shall be saved, even as they.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 12, E'Then all the multitude kept silence, and gave audience to Barnabas and Paul, declaring what miracles and wonders God had wrought among the Gentiles by them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 13, E'And after they had held their peace, James answered, saying, Men and brethren, hearken unto me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 14, E'Simeon hath declared how God at the first did visit the Gentiles, to take out of them a people for his name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 15, E'And to this agree the words of the prophets; as it is written,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 16, E'After this I will return, and will build again the tabernacle of David, which is fallen down; and I will build again the ruins thereof, and I will set it up:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 17, E'That the residue of men might seek after the Lord, and all the Gentiles, upon whom my name is called, saith the Lord, who doeth all these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 18, E'Known unto God are all his works from the beginning of the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 19, E'Wherefore my sentence is, that we trouble not them, which from among the Gentiles are turned to God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 20, E'But that we write unto them, that they abstain from pollutions of idols, and from fornication, and from things strangled, and from blood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 21, E'For Moses of old time hath in every city them that preach him, being read in the synagogues every sabbath day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 22, E'Then pleased it the apostles and elders, with the whole church, to send chosen men of their own company to Antioch with Paul and Barnabas; namely, Judas surnamed Barsabas, and Silas, chief men among the brethren:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 23, E'And they wrote letters by them after this manner; The apostles and elders and brethren send greeting unto the brethren which are of the Gentiles in Antioch and Syria and Cilicia:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 24, E'Forasmuch as we have heard, that certain which went out from us have troubled you with words, subverting your souls, saying, Ye must be circumcised, and keep the law: to whom we gave no such commandment:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 25, E'It seemed good unto us, being assembled with one accord, to send chosen men unto you with our beloved Barnabas and Paul,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 26, E'Men that have hazarded their lives for the name of our Lord Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 27, E'We have sent therefore Judas and Silas, who shall also tell you the same things by mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 28, E'For it seemed good to the Holy Ghost, and to us, to lay upon you no greater burden than these necessary things;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 29, E'That ye abstain from meats offered to idols, and from blood, and from things strangled, and from fornication: from which if ye keep yourselves, ye shall do well. Fare ye well.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 30, E'So when they were dismissed, they came to Antioch: and when they had gathered the multitude together, they delivered the epistle:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 31, E'Which when they had read, they rejoiced for the consolation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 32, E'And Judas and Silas, being prophets also themselves, exhorted the brethren with many words, and confirmed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 33, E'And after they had tarried there a space, they were let go in peace from the brethren unto the apostles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 34, E'Notwithstanding it pleased Silas to abide there still.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 35, E'Paul also and Barnabas continued in Antioch, teaching and preaching the word of the Lord, with many others also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 36, E'And some days after Paul said unto Barnabas, Let us go again and visit our brethren in every city where we have preached the word of the LORD, and see how they do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 37, E'And Barnabas determined to take with them John, whose surname was Mark.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 38, E'But Paul thought not good to take him with them, who departed from them from Pamphylia, and went not with them to the work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 39, E'And the contention was so sharp between them, that they departed asunder one from the other: and so Barnabas took Mark, and sailed unto Cyprus;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 40, E'And Paul chose Silas, and departed, being recommended by the brethren unto the grace of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 15, 41, E'And he went through Syria and Cilicia, confirming the churches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 1, E'Then came he to Derbe and Lystra: and, behold, a certain disciple was there, named Timotheus, the son of a certain woman, which was a Jewess, and believed; but his father was a Greek:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 2, E'Which was well reported of by the brethren that were at Lystra and Iconium.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 3, E'Him would Paul have to go forth with him; and took and circumcised him because of the Jews which were in those quarters: for they knew all that his father was a Greek.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 4, E'And as they went through the cities, they delivered them the decrees for to keep, that were ordained of the apostles and elders which were at Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 5, E'And so were the churches established in the faith, and increased in number daily.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 6, E'Now when they had gone throughout Phrygia and the region of Galatia, and were forbidden of the Holy Ghost to preach the word in Asia,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 7, E'After they were come to Mysia, they assayed to go into Bithynia: but the Spirit suffered them not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 8, E'And they passing by Mysia came down to Troas.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 9, E'And a vision appeared to Paul in the night; There stood a man of Macedonia, and prayed him, saying, Come over into Macedonia, and help us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 10, E'And after he had seen the vision, immediately we endeavoured to go into Macedonia, assuredly gathering that the Lord had called us for to preach the gospel unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 11, E'Therefore loosing from Troas, we came with a straight course to Samothracia, and the next day to Neapolis;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 12, E'And from thence to Philippi, which is the chief city of that part of Macedonia, and a colony: and we were in that city abiding certain days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 13, E'And on the sabbath we went out of the city by a river side, where prayer was wont to be made; and we sat down, and spake unto the women which resorted thither.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 14, E'And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 15, E'And when she was baptized, and her household, she besought us, saying, If ye have judged me to be faithful to the Lord, come into my house, and abide there. And she constrained us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 16, E'And it came to pass, as we went to prayer, a certain damsel possessed with a spirit of divination met us, which brought her masters much gain by soothsaying:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 17, E'The same followed Paul and us, and cried, saying, These men are the servants of the most high God, which shew unto us the way of salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 18, E'And this did she many days. But Paul, being grieved, turned and said to the spirit, I command thee in the name of Jesus Christ to come out of her. And he came out the same hour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 19, E'And when her masters saw that the hope of their gains was gone, they caught Paul and Silas, and drew them into the marketplace unto the rulers,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 20, E'And brought them to the magistrates, saying, These men, being Jews, do exceedingly trouble our city,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 21, E'And teach customs, which are not lawful for us to receive, neither to observe, being Romans.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 22, E'And the multitude rose up together against them: and the magistrates rent off their clothes, and commanded to beat them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 23, E'And when they had laid many stripes upon them, they cast them into prison, charging the jailor to keep them safely:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 24, E'Who, having received such a charge, thrust them into the inner prison, and made their feet fast in the stocks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 25, E'And at midnight Paul and Silas prayed, and sang praises unto God: and the prisoners heard them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 26, E'And suddenly there was a great earthquake, so that the foundations of the prison were shaken: and immediately all the doors were opened, and every one’s bands were loosed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 27, E'And the keeper of the prison awaking out of his sleep, and seeing the prison doors open, he drew out his sword, and would have killed himself, supposing that the prisoners had been fled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 28, E'But Paul cried with a loud voice, saying, Do thyself no harm: for we are all here.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 29, E'Then he called for a light, and sprang in, and came trembling, and fell down before Paul and Silas,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 30, E'And brought them out, and said, Sirs, what must I do to be saved?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 31, E'And they said, Believe on the Lord Jesus Christ, and thou shalt be saved, and thy house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 32, E'And they spake unto him the word of the Lord, and to all that were in his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 33, E'And he took them the same hour of the night, and washed their stripes; and was baptized, he and all his, straightway.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 34, E'And when he had brought them into his house, he set meat before them, and rejoiced, believing in God with all his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 35, E'And when it was day, the magistrates sent the serjeants, saying, Let those men go.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 36, E'And the keeper of the prison told this saying to Paul, The magistrates have sent to let you go: now therefore depart, and go in peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 37, E'But Paul said unto them, They have beaten us openly uncondemned, being Romans, and have cast us into prison; and now do they thrust us out privily? nay verily; but let them come themselves and fetch us out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 38, E'And the serjeants told these words unto the magistrates: and they feared, when they heard that they were Romans.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 39, E'And they came and besought them, and brought them out, and desired them to depart out of the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 16, 40, E'And they went out of the prison, and entered into the house of Lydia: and when they had seen the brethren, they comforted them, and departed.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Acts') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 1, E'Now when they had passed through Amphipolis and Apollonia, they came to Thessalonica, where was a synagogue of the Jews:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 2, E'And Paul, as his manner was, went in unto them, and three sabbath days reasoned with them out of the scriptures,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 3, E'Opening and alleging, that Christ must needs have suffered, and risen again from the dead; and that this Jesus, whom I preach unto you, is Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 4, E'And some of them believed, and consorted with Paul and Silas; and of the devout Greeks a great multitude, and of the chief women not a few.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 5, E'But the Jews which believed not, moved with envy, took unto them certain lewd fellows of the baser sort, and gathered a company, and set all the city on an uproar, and assaulted the house of Jason, and sought to bring them out to the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 6, E'And when they found them not, they drew Jason and certain brethren unto the rulers of the city, crying, These that have turned the world upside down are come hither also;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 7, E'Whom Jason hath received: and these all do contrary to the decrees of Caesar, saying that there is another king, one Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 8, E'And they troubled the people and the rulers of the city, when they heard these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 9, E'And when they had taken security of Jason, and of the other, they let them go.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 10, E'And the brethren immediately sent away Paul and Silas by night unto Berea: who coming thither went into the synagogue of the Jews.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 11, E'These were more noble than those in Thessalonica, in that they received the word with all readiness of mind, and searched the scriptures daily, whether those things were so.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 12, E'Therefore many of them believed; also of honourable women which were Greeks, and of men, not a few.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 13, E'But when the Jews of Thessalonica had knowledge that the word of God was preached of Paul at Berea, they came thither also, and stirred up the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 14, E'And then immediately the brethren sent away Paul to go as it were to the sea: but Silas and Timotheus abode there still.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 15, E'And they that conducted Paul brought him unto Athens: and receiving a commandment unto Silas and Timotheus for to come to him with all speed, they departed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 16, E'Now while Paul waited for them at Athens, his spirit was stirred in him, when he saw the city wholly given to idolatry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 17, E'Therefore disputed he in the synagogue with the Jews, and with the devout persons, and in the market daily with them that met with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 18, E'Then certain philosophers of the Epicureans, and of the Stoicks, encountered him. And some said, What will this babbler say? other some, He seemeth to be a setter forth of strange gods: because he preached unto them Jesus, and the resurrection.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 19, E'And they took him, and brought him unto Areopagus, saying, May we know what this new doctrine, whereof thou speakest, is?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 20, E'For thou bringest certain strange things to our ears: we would know therefore what these things mean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 21, E'(For all the Athenians and strangers which were there spent their time in nothing else, but either to tell, or to hear some new thing.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 22, E'Then Paul stood in the midst of Mars’ hill, and said, Ye men of Athens, I perceive that in all things ye are too superstitious.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 23, E'For as I passed by, and beheld your devotions, I found an altar with this inscription, TO THE UNKNOWN GOD. Whom therefore ye ignorantly worship, him declare I unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 24, E'God that made the world and all things therein, seeing that he is Lord of heaven and earth, dwelleth not in temples made with hands;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 25, E'Neither is worshipped with men’s hands, as though he needed any thing, seeing he giveth to all life, and breath, and all things;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 26, E'And hath made of one blood all nations of men for to dwell on all the face of the earth, and hath determined the times before appointed, and the bounds of their habitation;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 27, E'That they should seek the Lord, if haply they might feel after him, and find him, though he be not far from every one of us:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 28, E'For in him we live, and move, and have our being; as certain also of your own poets have said, For we are also his offspring.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 29, E'Forasmuch then as we are the offspring of God, we ought not to think that the Godhead is like unto gold, or silver, or stone, graven by art and man’s device.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 30, E'And the times of this ignorance God winked at; but now commandeth all men every where to repent:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 31, E'Because he hath appointed a day, in the which he will judge the world in righteousness by that man whom he hath ordained; whereof he hath given assurance unto all men, in that he hath raised him from the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 32, E'And when they heard of the resurrection of the dead, some mocked: and others said, We will hear thee again of this matter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 33, E'So Paul departed from among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 17, 34, E'Howbeit certain men clave unto him, and believed: among the which was Dionysius the Areopagite, and a woman named Damaris, and others with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 1, E'After these things Paul departed from Athens, and came to Corinth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 2, E'And found a certain Jew named Aquila, born in Pontus, lately come from Italy, with his wife Priscilla; (because that Claudius had commanded all Jews to depart from Rome:) and came unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 3, E'And because he was of the same craft, he abode with them, and wrought: for by their occupation they were tentmakers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 4, E'And he reasoned in the synagogue every sabbath, and persuaded the Jews and the Greeks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 5, E'And when Silas and Timotheus were come from Macedonia, Paul was pressed in the spirit, and testified to the Jews that Jesus was Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 6, E'And when they opposed themselves, and blasphemed, he shook his raiment, and said unto them, Your blood be upon your own heads; I am clean: from henceforth I will go unto the Gentiles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 7, E'And he departed thence, and entered into a certain man’s house, named Justus, one that worshipped God, whose house joined hard to the synagogue.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 8, E'And Crispus, the chief ruler of the synagogue, believed on the Lord with all his house; and many of the Corinthians hearing believed, and were baptized.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 9, E'Then spake the Lord to Paul in the night by a vision, Be not afraid, but speak, and hold not thy peace:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 10, E'For I am with thee, and no man shall set on thee to hurt thee: for I have much people in this city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 11, E'And he continued there a year and six months, teaching the word of God among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 12, E'And when Gallio was the deputy of Achaia, the Jews made insurrection with one accord against Paul, and brought him to the judgment seat,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 13, E'Saying, This fellow persuadeth men to worship God contrary to the law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 14, E'And when Paul was now about to open his mouth, Gallio said unto the Jews, If it were a matter of wrong or wicked lewdness, O ye Jews, reason would that I should bear with you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 15, E'But if it be a question of words and names, and of your law, look ye to it; for I will be no judge of such matters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 16, E'And he drave them from the judgment seat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 17, E'Then all the Greeks took Sosthenes, the chief ruler of the synagogue, and beat him before the judgment seat. And Gallio cared for none of those things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 18, E'And Paul after this tarried there yet a good while, and then took his leave of the brethren, and sailed thence into Syria, and with him Priscilla and Aquila; having shorn his head in Cenchrea: for he had a vow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 19, E'And he came to Ephesus, and left them there: but he himself entered into the synagogue, and reasoned with the Jews.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 20, E'When they desired him to tarry longer time with them, he consented not;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 21, E'But bade them farewell, saying, I must by all means keep this feast that cometh in Jerusalem: but I will return again unto you, if God will. And he sailed from Ephesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 22, E'And when he had landed at Caesarea, and gone up, and saluted the church, he went down to Antioch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 23, E'And after he had spent some time there, he departed, and went over all the country of Galatia and Phrygia in order, strengthening all the disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 24, E'And a certain Jew named Apollos, born at Alexandria, an eloquent man, and mighty in the scriptures, came to Ephesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 25, E'This man was instructed in the way of the Lord; and being fervent in the spirit, he spake and taught diligently the things of the Lord, knowing only the baptism of John.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 26, E'And he began to speak boldly in the synagogue: whom when Aquila and Priscilla had heard, they took him unto them, and expounded unto him the way of God more perfectly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 27, E'And when he was disposed to pass into Achaia, the brethren wrote, exhorting the disciples to receive him: who, when he was come, helped them much which had believed through grace:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 18, 28, E'For he mightily convinced the Jews, and that publickly, shewing by the scriptures that Jesus was Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 1, E'And it came to pass, that, while Apollos was at Corinth, Paul having passed through the upper coasts came to Ephesus: and finding certain disciples,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 2, E'He said unto them, Have ye received the Holy Ghost since ye believed? And they said unto him, We have not so much as heard whether there be any Holy Ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 3, E'And he said unto them, Unto what then were ye baptized? And they said, Unto John’s baptism.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 4, E'Then said Paul, John verily baptized with the baptism of repentance, saying unto the people, that they should believe on him which should come after him, that is, on Christ Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 5, E'When they heard this, they were baptized in the name of the Lord Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 6, E'And when Paul had laid his hands upon them, the Holy Ghost came on them; and they spake with tongues, and prophesied.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 7, E'And all the men were about twelve.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 8, E'And he went into the synagogue, and spake boldly for the space of three months, disputing and persuading the things concerning the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 9, E'But when divers were hardened, and believed not, but spake evil of that way before the multitude, he departed from them, and separated the disciples, disputing daily in the school of one Tyrannus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 10, E'And this continued by the space of two years; so that all they which dwelt in Asia heard the word of the Lord Jesus, both Jews and Greeks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 11, E'And God wrought special miracles by the hands of Paul:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 12, E'So that from his body were brought unto the sick handkerchiefs or aprons, and the diseases departed from them, and the evil spirits went out of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 13, E'Then certain of the vagabond Jews, exorcists, took upon them to call over them which had evil spirits the name of the LORD Jesus, saying, We adjure you by Jesus whom Paul preacheth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 14, E'And there were seven sons of one Sceva, a Jew, and chief of the priests, which did so.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 15, E'And the evil spirit answered and said, Jesus I know, and Paul I know; but who are ye?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 16, E'And the man in whom the evil spirit was leaped on them, and overcame them, and prevailed against them, so that they fled out of that house naked and wounded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 17, E'And this was known to all the Jews and Greeks also dwelling at Ephesus; and fear fell on them all, and the name of the Lord Jesus was magnified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 18, E'And many that believed came, and confessed, and shewed their deeds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 19, E'Many of them also which used curious arts brought their books together, and burned them before all men: and they counted the price of them, and found it fifty thousand pieces of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 20, E'So mightily grew the word of God and prevailed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 21, E'After these things were ended, Paul purposed in the spirit, when he had passed through Macedonia and Achaia, to go to Jerusalem, saying, After I have been there, I must also see Rome.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 22, E'So he sent into Macedonia two of them that ministered unto him, Timotheus and Erastus; but he himself stayed in Asia for a season.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 23, E'And the same time there arose no small stir about that way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 24, E'For a certain man named Demetrius, a silversmith, which made silver shrines for Diana, brought no small gain unto the craftsmen;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 25, E'Whom he called together with the workmen of like occupation, and said, Sirs, ye know that by this craft we have our wealth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 26, E'Moreover ye see and hear, that not alone at Ephesus, but almost throughout all Asia, this Paul hath persuaded and turned away much people, saying that they be no gods, which are made with hands:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 27, E'So that not only this our craft is in danger to be set at nought; but also that the temple of the great goddess Diana should be despised, and her magnificence should be destroyed, whom all Asia and the world worshippeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 28, E'And when they heard these sayings, they were full of wrath, and cried out, saying, Great is Diana of the Ephesians.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 29, E'And the whole city was filled with confusion: and having caught Gaius and Aristarchus, men of Macedonia, Paul’s companions in travel, they rushed with one accord into the theatre.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 30, E'And when Paul would have entered in unto the people, the disciples suffered him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 31, E'And certain of the chief of Asia, which were his friends, sent unto him, desiring him that he would not adventure himself into the theatre.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 32, E'Some therefore cried one thing, and some another: for the assembly was confused; and the more part knew not wherefore they were come together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 33, E'And they drew Alexander out of the multitude, the Jews putting him forward. And Alexander beckoned with the hand, and would have made his defence unto the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 34, E'But when they knew that he was a Jew, all with one voice about the space of two hours cried out, Great is Diana of the Ephesians.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 35, E'And when the townclerk had appeased the people, he said, Ye men of Ephesus, what man is there that knoweth not how that the city of the Ephesians is a worshipper of the great goddess Diana, and of the image which fell down from Jupiter?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 36, E'Seeing then that these things cannot be spoken against, ye ought to be quiet, and to do nothing rashly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 37, E'For ye have brought hither these men, which are neither robbers of churches, nor yet blasphemers of your goddess.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 38, E'Wherefore if Demetrius, and the craftsmen which are with him, have a matter against any man, the law is open, and there are deputies: let them implead one another.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Acts') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 39, E'But if ye enquire any thing concerning other matters, it shall be determined in a lawful assembly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 40, E'For we are in danger to be called in question for this day’s uproar, there being no cause whereby we may give an account of this concourse.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 19, 41, E'And when he had thus spoken, he dismissed the assembly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 1, E'And after the uproar was ceased, Paul called unto him the disciples, and embraced them, and departed for to go into Macedonia.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 2, E'And when he had gone over those parts, and had given them much exhortation, he came into Greece,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 3, E'And there abode three months. And when the Jews laid wait for him, as he was about to sail into Syria, he purposed to return through Macedonia.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 4, E'And there accompanied him into Asia Sopater of Berea; and of the Thessalonians, Aristarchus and Secundus; and Gaius of Derbe, and Timotheus; and of Asia, Tychicus and Trophimus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 5, E'These going before tarried for us at Troas.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 6, E'And we sailed away from Philippi after the days of unleavened bread, and came unto them to Troas in five days; where we abode seven days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 7, E'And upon the first day of the week, when the disciples came together to break bread, Paul preached unto them, ready to depart on the morrow; and continued his speech until midnight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 8, E'And there were many lights in the upper chamber, where they were gathered together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 9, E'And there sat in a window a certain young man named Eutychus, being fallen into a deep sleep: and as Paul was long preaching, he sunk down with sleep, and fell down from the third loft, and was taken up dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 10, E'And Paul went down, and fell on him, and embracing him said, Trouble not yourselves; for his life is in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 11, E'When he therefore was come up again, and had broken bread, and eaten, and talked a long while, even till break of day, so he departed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 12, E'And they brought the young man alive, and were not a little comforted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 13, E'And we went before to ship, and sailed unto Assos, there intending to take in Paul: for so had he appointed, minding himself to go afoot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 14, E'And when he met with us at Assos, we took him in, and came to Mitylene.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 15, E'And we sailed thence, and came the next day over against Chios; and the next day we arrived at Samos, and tarried at Trogyllium; and the next day we came to Miletus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 16, E'For Paul had determined to sail by Ephesus, because he would not spend the time in Asia: for he hasted, if it were possible for him, to be at Jerusalem the day of Pentecost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 17, E'And from Miletus he sent to Ephesus, and called the elders of the church.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 18, E'And when they were come to him, he said unto them, Ye know, from the first day that I came into Asia, after what manner I have been with you at all seasons,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 19, E'Serving the LORD with all humility of mind, and with many tears, and temptations, which befell me by the lying in wait of the Jews:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 20, E'And how I kept back nothing that was profitable unto you, but have shewed you, and have taught you publickly, and from house to house,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 21, E'Testifying both to the Jews, and also to the Greeks, repentance toward God, and faith toward our Lord Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 22, E'And now, behold, I go bound in the spirit unto Jerusalem, not knowing the things that shall befall me there:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 23, E'Save that the Holy Ghost witnesseth in every city, saying that bonds and afflictions abide me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 24, E'But none of these things move me, neither count I my life dear unto myself, so that I might finish my course with joy, and the ministry, which I have received of the Lord Jesus, to testify the gospel of the grace of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 25, E'And now, behold, I know that ye all, among whom I have gone preaching the kingdom of God, shall see my face no more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 26, E'Wherefore I take you to record this day, that I am pure from the blood of all men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 27, E'For I have not shunned to declare unto you all the counsel of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 28, E'Take heed therefore unto yourselves, and to all the flock, over the which the Holy Ghost hath made you overseers, to feed the church of God, which he hath purchased with his own blood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 29, E'For I know this, that after my departing shall grievous wolves enter in among you, not sparing the flock.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 30, E'Also of your own selves shall men arise, speaking perverse things, to draw away disciples after them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 31, E'Therefore watch, and remember, that by the space of three years I ceased not to warn every one night and day with tears.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 32, E'And now, brethren, I commend you to God, and to the word of his grace, which is able to build you up, and to give you an inheritance among all them which are sanctified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 33, E'I have coveted no man’s silver, or gold, or apparel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 34, E'Yea, ye yourselves know, that these hands have ministered unto my necessities, and to them that were with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 35, E'I have shewed you all things, how that so labouring ye ought to support the weak, and to remember the words of the Lord Jesus, how he said, It is more blessed to give than to receive.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 36, E'And when he had thus spoken, he kneeled down, and prayed with them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 37, E'And they all wept sore, and fell on Paul’s neck, and kissed him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 20, 38, E'Sorrowing most of all for the words which he spake, that they should see his face no more. And they accompanied him unto the ship.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 1, E'And it came to pass, that after we were gotten from them, and had launched, we came with a straight course unto Coos, and the day following unto Rhodes, and from thence unto Patara:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 2, E'And finding a ship sailing over unto Phenicia, we went aboard, and set forth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 3, E'Now when we had discovered Cyprus, we left it on the left hand, and sailed into Syria, and landed at Tyre: for there the ship was to unlade her burden.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 4, E'And finding disciples, we tarried there seven days: who said to Paul through the Spirit, that he should not go up to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 5, E'And when we had accomplished those days, we departed and went our way; and they all brought us on our way, with wives and children, till we were out of the city: and we kneeled down on the shore, and prayed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 6, E'And when we had taken our leave one of another, we took ship; and they returned home again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 7, E'And when we had finished our course from Tyre, we came to Ptolemais, and saluted the brethren, and abode with them one day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 8, E'And the next day we that were of Paul’s company departed, and came unto Caesarea: and we entered into the house of Philip the evangelist, which was one of the seven; and abode with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 9, E'And the same man had four daughters, virgins, which did prophesy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 10, E'And as we tarried there many days, there came down from Judaea a certain prophet, named Agabus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 11, E'And when he was come unto us, he took Paul’s girdle, and bound his own hands and feet, and said, Thus saith the Holy Ghost, So shall the Jews at Jerusalem bind the man that owneth this girdle, and shall deliver him into the hands of the Gentiles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 12, E'And when we heard these things, both we, and they of that place, besought him not to go up to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 13, E'Then Paul answered, What mean ye to weep and to break mine heart? for I am ready not to be bound only, but also to die at Jerusalem for the name of the Lord Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 14, E'And when he would not be persuaded, we ceased, saying, The will of the Lord be done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 15, E'And after those days we took up our carriages, and went up to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 16, E'There went with us also certain of the disciples of Caesarea, and brought with them one Mnason of Cyprus, an old disciple, with whom we should lodge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 17, E'And when we were come to Jerusalem, the brethren received us gladly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 18, E'And the day following Paul went in with us unto James; and all the elders were present.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 19, E'And when he had saluted them, he declared particularly what things God had wrought among the Gentiles by his ministry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 20, E'And when they heard it, they glorified the Lord, and said unto him, Thou seest, brother, how many thousands of Jews there are which believe; and they are all zealous of the law:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 21, E'And they are informed of thee, that thou teachest all the Jews which are among the Gentiles to forsake Moses, saying that they ought not to circumcise their children, neither to walk after the customs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 22, E'What is it therefore? the multitude must needs come together: for they will hear that thou art come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 23, E'Do therefore this that we say to thee: We have four men which have a vow on them;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 24, E'Them take, and purify thyself with them, and be at charges with them, that they may shave their heads: and all may know that those things, whereof they were informed concerning thee, are nothing; but that thou thyself also walkest orderly, and keepest the law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 25, E'As touching the Gentiles which believe, we have written and concluded that they observe no such thing, save only that they keep themselves from things offered to idols, and from blood, and from strangled, and from fornication.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 26, E'Then Paul took the men, and the next day purifying himself with them entered into the temple, to signify the accomplishment of the days of purification, until that an offering should be offered for every one of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 27, E'And when the seven days were almost ended, the Jews which were of Asia, when they saw him in the temple, stirred up all the people, and laid hands on him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 28, E'Crying out, Men of Israel, help: This is the man, that teacheth all men every where against the people, and the law, and this place: and further brought Greeks also into the temple, and hath polluted this holy place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 29, E'(For they had seen before with him in the city Trophimus an Ephesian, whom they supposed that Paul had brought into the temple.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 30, E'And all the city was moved, and the people ran together: and they took Paul, and drew him out of the temple: and forthwith the doors were shut.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 31, E'And as they went about to kill him, tidings came unto the chief captain of the band, that all Jerusalem was in an uproar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 32, E'Who immediately took soldiers and centurions, and ran down unto them: and when they saw the chief captain and the soldiers, they left beating of Paul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 33, E'Then the chief captain came near, and took him, and commanded him to be bound with two chains; and demanded who he was, and what he had done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 34, E'And some cried one thing, some another, among the multitude: and when he could not know the certainty for the tumult, he commanded him to be carried into the castle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 35, E'And when he came upon the stairs, so it was, that he was borne of the soldiers for the violence of the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 36, E'For the multitude of the people followed after, crying, Away with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 37, E'And as Paul was to be led into the castle, he said unto the chief captain, May I speak unto thee? Who said, Canst thou speak Greek?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 38, E'Art not thou that Egyptian, which before these days madest an uproar, and leddest out into the wilderness four thousand men that were murderers?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 39, E'But Paul said, I am a man which am a Jew of Tarsus, a city in Cilicia, a citizen of no mean city: and, I beseech thee, suffer me to speak unto the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 21, 40, E'And when he had given him licence, Paul stood on the stairs, and beckoned with the hand unto the people. And when there was made a great silence, he spake unto them in the Hebrew tongue, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 22, 1, E'Men, brethren, and fathers, hear ye my defence which I make now unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 22, 2, E'(And when they heard that he spake in the Hebrew tongue to them, they kept the more silence: and he saith,)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 22, 3, E'I am verily a man which am a Jew, born in Tarsus, a city in Cilicia, yet brought up in this city at the feet of Gamaliel, and taught according to the perfect manner of the law of the fathers, and was zealous toward God, as ye all are this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 22, 4, E'And I persecuted this way unto the death, binding and delivering into prisons both men and women.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 22, 5, E'As also the high priest doth bear me witness, and all the estate of the elders: from whom also I received letters unto the brethren, and went to Damascus, to bring them which were there bound unto Jerusalem, for to be punished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 22, 6, E'And it came to pass, that, as I made my journey, and was come nigh unto Damascus about noon, suddenly there shone from heaven a great light round about me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 22, 7, E'And I fell unto the ground, and heard a voice saying unto me, Saul, Saul, why persecutest thou me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 22, 8, E'And I answered, Who art thou, Lord? And he said unto me, I am Jesus of Nazareth, whom thou persecutest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 22, 9, E'And they that were with me saw indeed the light, and were afraid; but they heard not the voice of him that spake to me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 22, 10, E'And I said, What shall I do, LORD? And the Lord said unto me, Arise, and go into Damascus; and there it shall be told thee of all things which are appointed for thee to do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 22, 11, E'And when I could not see for the glory of that light, being led by the hand of them that were with me, I came into Damascus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 22, 12, E'And one Ananias, a devout man according to the law, having a good report of all the Jews which dwelt there,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 22, 13, E'Came unto me, and stood, and said unto me, Brother Saul, receive thy sight. And the same hour I looked up upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 22, 14, E'And he said, The God of our fathers hath chosen thee, that thou shouldest know his will, and see that Just One, and shouldest hear the voice of his mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 22, 15, E'For thou shalt be his witness unto all men of what thou hast seen and heard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 22, 16, E'And now why tarriest thou? arise, and be baptized, and wash away thy sins, calling on the name of the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 22, 17, E'And it came to pass, that, when I was come again to Jerusalem, even while I prayed in the temple, I was in a trance;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 22, 18, E'And saw him saying unto me, Make haste, and get thee quickly out of Jerusalem: for they will not receive thy testimony concerning me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'abdb5bca-adbf-4b82-b690-f6422fe4a267', 22, 19, E'And I said, Lord, they know that I imprisoned and beat in every synagogue them that believed on thee:')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Acts') b
ON CONFLICT DO NOTHING;

